quests[1] = { id = 1, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanrethads Quest", description = "Willkommen zurück im Reich der Toten.\n\nEin ganzes Zeitalter ist es her, seit Ihr ein stolzer Held unter euresgleichen wart. Doch nun seid Ihr <ein geschlagener Mann/eine geschlagene Frau> -gebrochen, ein Relikt vergangener Tage. Höret nun und ich werde der Legende, die Ihr einst wart, neues Leben einhauchen.\n\nIch werde Waffen und Kräfte, die Ihr verloren habt, wiederherstellen und Euch wieder ins Leben rufen.Ihr erlernt:", sourceObjective = "Sprecht mit Kanrethad, um Eure Talente, Waffen und Euer Reittier wiederherzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2] = { id = 2, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klaue von Scharfkralle", description = "Der mächtige Hippogryph Scharfkralle wurde getötet und die Klaue der erschlagenen Bestie dient als Beweis für Euren Sieg. Senani Donnerherz im Splitterholzposten wird zum Beweis Eurer Tat sicher gern diese Trophäe sehen wollen.", sourceObjective = "Bringt die Klaue von Scharfkralle zu Senani Donnerherz im Splitterholzposten im Eschental.", progress = "Ja, {class}, ich habe Eure Ankunft bereits gespürt. Habt Ihr weitere Neuigkeiten von Eurer Jagd zu berichten?", completion = "Wirklich beeindruckend, {name}... Die Klaue von Scharfkralle dürfte nicht einfach zu bekommen gewesen sein. Die Jagd in Ashenvale läuft gut für Euch!\n\nScharfkralle hat über lange Zeit hinweg die Peons aus den Holzfällerlagern entlang seinem Weg terrorisiert, wenn diese versuchten, hierher zum Splintertreeposten zu gelangen. Zweifelsohne werden viele begeisterte Lieder über Eure Tapferkeit an den Lagerfeuern und in den Holzfällerlagern überall in Ashenvale erschallen, sobald man davon hört, dass Ihr es wart, der die Bestie bezwungen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[5] = { id = 5, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bibbers' knurrender Magen", description = "Ich verstecke mich jetzt schon seit Wochen in dieser Geisterstadt, und die ganze Zeit habe ich nichts gegessen außer Maden und Unkraut! Ich brauche was Anständiges zum Essen, und ich werde mich nicht lumpen lassen.\n\nBringt mir ein Festessen, und ich bezahle Euch gut dafür.\n\nIch habe gehört, dass Küchenchef Grual aus der Taverne Zum roten Raben in Dunkelhain ganz ausgezeichnete schwärzliche Krebsküchlein macht...", sourceObjective = "Sprecht mit Küchenchef Grual.", completion = "Ihr braucht einige Krebsküchlein, wie? Na ja, ich könnte Euch vielleicht ein paar machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6] = { id = 6, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld auf Garrick Schleichfuß", description = "Garrick Schleichfuß, ein Dieb und Halsabschneider, der schon seit Wochen unseren Bauern und Händlern das Leben schwer macht, ist bei einem Schuppen in der Nähe der Weinberge gesehen worden. Die Weinberge liegen im Osten der Abtei, auf der anderen Seite der Brücke. Bringt mir den Kopf des Schurken und verdient Euch das Kopfgeld, das auf ihn ausgesetzt ist!\n\nDoch seht Euch vor, {name}. Garrick hat eine Bande von Rohlingen um sich versammelt, also werdet Ihr nicht leicht an ihn herankommen.", sourceObjective = "Tötet Garrick Schleichfuß und bringt seinen Kopf zu Stellvertreter Willem in der Nähe der Abtei von Nordhain.", progress = "Habt Ihr Garricks Schuppen gefunden? Sind wir diesen Schurken endlich los?", completion = "Ha, Ihr habt ihn erwischt! Ihr habt ganz Elwynn einen großen Dienst erwiesen und Euch ein schönes Kopfgeld verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[7] = { id = 7, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung im Koboldlager", description = "Eure erste Aufgabe ist eine Säuberung, {name}. Ein Koboldklan hat sich in den Wäldern im Norden eingenistet. Begebt Euch dorthin und bekämpft das Koboldgezücht, das Ihr dort finden werdet. Dezimiert es, damit wir die Kobolde eines Tages gänzlich aus Nordhain vertreiben können.", sourceObjective = "Tötet 8 von dem Koboldgezücht und kehrt dann zu Marschall McBride zurück.", completion = "Gut gemacht, Bürger. Diese Kobolde sind Diebe und Feiglinge, aber wenn sie in Massen auftreten, dann sind sie doch eine Gefahr für uns. Und die Menschen von Stormwind können nun wirklich keine weitere Gefahr gebrauchen.\n\nHabt meinen Dank dafür, dass Ihr sie besiegtet!", sourceObjectiveStatus = "unverified-source-field" }
quests[8] = { id = 8, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schurkenhandel", description = "Heda, Kamerad! Wollt Ihr nicht einem jungen Mann, der mehr als seinen Teil an hirnlosen Zombies und Spinnen umgelegt hat, einen Gefallen tun?\n\nIch hab hier einen Brief, der muss nach Brill... zu so einer Gastwirtin namens Renee Irgendwas. Ist eigentlich völlig egal, wie sie mit Nachnamen heißt.\n\nNa egal, jedenfalls ist es ein netter kleiner Ort, wo lauter Opfer der Seuche wohnen, die versuchen, sich irgendwie durchs Leben zu schlagen. Und es wäre ein toller Ort für Euch, an dem Ihr Euch ausruhen könnt, falls das mal nötig wird. Ihr solltet Euch den wirklich mal anseh'n - macht es, und ich bezahl Euch auch noch gut dafür.", sourceObjective = "Liefert den unscheinbaren Brief bei Gastwirtin Renee in Tirisfal ab.", progress = "Ja? Ja? Was ist?\n\nFür ein Volk von Wesen, die unter Wasser nicht atmen müssen, haben sie schon einen sehr gesunden Appetit. Fühlt Euch ganz wie zu Hause, fühlt Euch ganz wie zu Hause. Ich heiße Renee, falls Ihr irgendetwas braucht.", completion = "Ach? Ein Brief? Wie schön! Ich warte schon seit langem darauf, wieder einmal etwas von meiner lieben alten Mutter in Deathknell zu hören. Sie ist ja eine so wunderbare Person! Ich frage mich, wie die Gute so zurechtkommt.\n\nWas? Zu fröhlich? Ihr kauft mir das nicht ab, wie?\n\nNa, dann verschwindet. Es geht Euch sowieso rein gar nichts an, von wem dieser Brief ist. Na los! Verschwindet schon!\n\nKommt wieder, sobald Ihr 'n bisschen Geld habt, das Ihr ausgeben könnt, Faulenzer.\n\nSonst kommt Ihr als Nächstes noch her und wollt Euch nach einem langen Tag des Abenteuerns hier ausruhen oder so'n Quark.", sourceObjectiveStatus = "unverified-source-field" }
quests[9] = { id = 9, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod auf den Feldern", description = "Jetzt seht Euch nur an, was aus diesem Ort geworden ist! In dieser Gegend lebten einst ehrbare Bauersleute. Die verdammten Diebe haben sie alle vertrieben. Aber mich nicht! Jetzt sieht es allerdings so aus, als hätten einige Erntebehüter sich in den Feldern breit gemacht.\n\nWenn Ihr Euch dem gewachsen fühlt, dann geht hinaus und tötet dort draußen 20 von ihnen. Wenn Ihr fertig seid, kommt zurück und holt Euch Eure Bezahlung ab. Und wenn Ihr alle in meinem Feld erwischt habt, dann räumt auch in den angrenzenden Feldern auf.", sourceObjective = "Bauer Saldean möchte, dass Ihr 20 Erntebehüter tötet.", progress = "Ah, wie ich sehe, seid Ihr wieder da! Ich hoffe doch sehr, dass Ihr fleißig wart und die Felder von diesen Erntebehütern gesäubert habt. Habt Ihr schon 20 getötet?", completion = "Gute Arbeit, mein Freund. Ihr habt Euch Eure Bezahlung redlich verdient. Wer weiß, vielleicht wird Westfall ja wieder aufblühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10] = { id = 10, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erlösung von Kieselschliff", description = "Oh, das ist einfach schrecklich! Ich habe meinen besten Gehilfen, Unterfeldmesser Kieselschliff, in die Wüste südöstlich von hier geschickt. Das ist ein Gebiet, das wir die Klaffende Schlucht nennen. Nun ja, er wird vermisst und in seinem letzten Bericht sprach er davon, dass es dort, wo er war, noch mehr dieser komischen Viecher gäbe. Könnte es sein, dass sie sich jetzt in zwei großen Gebieten der Wüste eingenistet haben?\n\nBegebt Euch bitte für mich zur Klaffenden Schlucht und sucht nach Kieselschliff! Das... oder findet wenigstens seine Feldmesserausrüstung. Ich fürchte, das ist alles, was von dem Armen übrig geblieben ist.", sourceObjective = "Erforscht das Schicksal von Unterfeldmesser Kieselschliff und bringt entweder ihn oder seine Feldmesserausrüstung nach Gadgetzan zum Leitenden Feldmesser Rutenwünschels.", progress = "Nun, was habt Ihr für Neuigkeiten? Ihr seht aus, als hättet Ihr einiges durchgemacht... ist Scrimshank am Leben?", completion = "Er war ein guter Goblin, der junge Scrimshank. Hoffen wir, dass sein Ableben durch das, was er mit seiner Feldmesserausrüstung aufzeichnen konnte, nicht umsonst war.\n\nEs scheint als wären wir mit diesen Viechern in eine ziemlich unangenehme Lage geraten. Sie sind viel zu gerissen und unsere bisherigen Forschungen deuten an, dass sie sich möglicherweise sogar unter dem kontrollierenden Einfluss eines Dritten befinden! Wenn das stimmt, ist das nicht nur für Gadgetzan ein schlechtes Zeichen, sondern für die ganze Wüste!", sourceObjectiveStatus = "unverified-source-field" }
quests[11] = { id = 11, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld auf die Flusspfotengnolle", description = "Gnolle, brutale Wesen, die in dieser Gegend nichts zu suchen haben, sind entlang der Grenzen des Waldes von Elwynn gesehen worden. Ein großes Rudel, viel zu viele, als dass wir allein mit ihnen fertig werden könnten, hat sich in den Wäldern südlich von jenem Wachturm dort eingenistet. Eine weitere Gruppe hat sich im Gebiet nahe des Steinhügelsees im Osten eingenistet.\n\nDie Armee von Sturmwind wird jeden belobigen, der dabei hilft, die Gnolle zu töten. Bringt mir ihre bemalten Gnollarmbinden als Beweis für Eure Tat.", sourceObjective = "Bringt Stellvertreter Rainer in der Kaserne 8 bemalte Gnollarmbinden.", progress = "Seid gegrüßt, {name}. Wart Ihr Gnolle töten?", completion = "Wie ich sehe, wart Ihr fleißig! Habt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12] = { id = 12, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Volksmiliz", description = "Die Volksmiliz hat nur ein einziges Ziel: Westfall zu verteidigen und den Frieden in dieses Land zurückzubringen. Doch leider muss der Frieden nur allzu oft mit Blut bezahlt werden. \n\nEiner meiner Späher hat uns Kunde davon gebracht, dass eine Fallenstellerbande der Defias hier in der Nähe verheerende Schäden anrichtet. Mir liegen Berichte vor, dass einige Fallensteller der Defias in der Nähe des Jangoschachts im Nordwesten gesichtet wurden, ebenso bei Molsens Hof und bei Brauenwirbels Kürbishof. Wenn Ihr unseren Reihen beizutreten wünscht, dann erschlagt 15 Fallensteller der Defias und 15 Schmuggler der Defias und kehrt zu mir zurück.", sourceObjective = "Gryan Starkmantel möchte, dass Ihr 15 Fallensteller der Defias und 15 Schmuggler der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", progress = "Vielleicht habe ich mich nicht klar genug ausgedrückt, Kandidat. Um Euren Wert als Diener der Volksmiliz und Diener des Lichtes zu beweisen, müsst Ihr 15 Fallensteller der Defias und 15 Schmuggler der Defias erschlagen und zu mir zurückkehren, sobald Ihr dies getan habt.", completion = "Gut gemacht, {name}. Mein Späher hat Eure tapferen Taten beobachtet. Bis jetzt bewährt Ihr Euch recht gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[13] = { id = 13, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Volksmiliz", description = "Eine Bande heimtückischer Plünderer der Defias ist dabei gesehen worden, wie sie den Goldküstensteinbruch, Mondbruch und Alexstons Bauernhof ausplünderten. Die Volksmiliz kann ein solches Verhalten nicht hinnehmen. Macht Euch unverzüglich auf den Weg, {name}, und zeigt, dass das Licht in Westfall zugegen ist.\n\nDer Goldküstensteinbruch befindet sich in der Nähe der Küste, westlich vom Turm. Im nächsten Schritt Eurer Ausbildung müsst Ihr 15 dieser üblen Plünderer der Defias und 15 Ausplünderer der Defias töten.", sourceObjective = "Gryan Starkmantel möchte, dass Ihr 15 Plünderer der Defias und 15 Ausplünderer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", progress = "Wir haben jetzt keine Zeit für Geschwätz, {name}! Die Plünderer der Defias hindern die Bewohner von Westfall daran, den Frieden und Wohlstand zu genießen, den diese verdient haben. Tötet unbedingt mindestens 15 Plünderer der Defias und 15 Ausplünderer der Defias. Das wird ihnen die deutliche Botschaft vermitteln, dass wir Verderbnis hier nicht tolerieren.", completion = "Ihr habt Euren Wert für die Volksmiliz durch die tapferen Taten bewiesen, die Ihr bisher vollbracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14] = { id = 14, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Volksmiliz", description = "Einige Defias konnten wir bislang nicht erwischen. Mein bester Späher berichtet, dass diese Defias in der ganzen Gegend auf Raubzug gehen und schon bis Süd-Westfall gekommen sind. Wir glauben, dass sie sich in den Dolchhügeln versteckt halten und dort ihren nächsten Schachzug planen. Schaltet diese Verbrecher im Namen der Volksmiliz aus.", sourceObjective = "Gryan Starkmantel möchte, dass Ihr 15 Straßenräuber der Defias, 5 Pfadpirscher der Defias und 5 Knöchelhauer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", progress = "Es ist jetzt nicht die Zeit für müßiges Geplauder, {name}. Wenn Ihr Euch der Volksmiliz noch immer beweisen wollt, so müsst Ihr die Defias töten, von denen ich Euch zuvor berichtete. Kehrt zu mir zurück, wenn Ihr Eure Pflicht erfüllt habt.", completion = "Als ich Lordaeron, dieses besudelte Land, verließ, fand ich hier, in meiner Heimat, schlimme Zustände vor. Doch es besteht noch Hoffnung für Westfall. Wie Ihr durch Euren Heldenmut im Kampfe bewiesen habt, dient Ihr ganz offensichtlich ehrenvoll unserer Sache. Mit großem Stolz berufe ich Euch in die Volksmiliz ein. Möge das Licht über Euch leuchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[15] = { id = 15, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überprüfung der Echokammmine", description = "Wie mir meine Späher mitteilen, ist das Koboldproblem größer als wir dachten, {name}. Eine Gruppe Koboldtagelöhner hat ihr Lager in der Nähe der Echokammmine im Norden aufgeschlagen.\n\nBegebt Euch zu der Mine und entfernt die Kobolde. Wir wissen, dass sich mindestens 8 von ihnen dort aufhalten. Tötet sie, seht nach, ob dort noch mehr von ihnen sind, kommt dann zu mir zurück und erstattet Bericht.", sourceObjective = "Tötet 8 Koboldtagelöhner und erstattet dann Marschall McBride Euren Bericht.", completion = "Es gefällt mir gar nicht, dass sich so viele Kobolde in unserer Mine herumtreiben. Das bedeutet nichts Gutes. Hier, nehmt dies als Bezahlung und sprecht mich wieder an, sobald Ihr dazu bereit seid. Denn ich möchte, dass Ihr noch einmal in die Minen zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[16] = { id = 16, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas zu trinken für Gerard", progress = "Es macht durstig, das Land zu bestellen, und ich bin immer auf der Suche nach erfrischendem Quellwasser.\n\nWenn Ihr welches habt, dann mache ich einen Tauschhandel mit Euch.", completion = "Danke, {name}! Und kommt jederzeit wieder, wenn Ihr noch einen Handel machen wollt." }
quests[17] = { id = 17, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenzsuche in Uldaman", description = "Ich habe von einer neu entdeckten Pilzsorte gehört, den Magentafunguskappen. Sie wachsen in Kolonien bei der Uldaman-Grabungsstätte. Man findet sie häufig in den vorderen Tunnelabschnitten und auch tief in den unerforschten Regionen der Grabungsstätte. Ich möchte ihren potenziellen Nutzen für die Alchemie erforschen und dafür brauche ich Euch.\n\nFindet die Magentafunguskappen-Kolonien und bringt mir ein Dutzend Kappen. Aber seid gewarnt - die Pilze stoßen vielleicht Giftsporen aus, wenn man sie anstößt.\n\nWenn Ihr das für mich tut, dann braue ich Euch einen Schwung von meinem berühmten Regenerierungselixier!", sourceObjective = "Bringt zwölf Magentafunguskappen nach Thelsamar zu Ghak Heilsegen.", progress = "Habt Ihr die magenta Funguskappen bekommen, die ich für meine alchimistische Arbeit benötige? Keine Kappen - keine Belohnung!", completion = "Gut gemacht, {name}, Ihr habt Euren Wert abermals bewiesen! Die Pilzkappen werden wahrlich ein interessantes Studienobjekt sein!\n\nUnd nun genießt, wie versprochen, eine Kostprobe meines wirksamen Regenerierungsgebräus aus meinem persönlichen Vorrat...\n\nFalls Ihr ein geübter Alchimist seid, ergeben sich für uns vielleicht noch weitere Geschäfte. Ungeachtet dessen danke ich Euch für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[18] = { id = 18, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruderschaft der Diebe", description = "Seit Kurzem treibt sich eine neue Diebesbande in Nordhain herum. Sie nennen sich die \"Bruderschaft der Defias\" und sind auf der anderen Seite des Flusses im Osten gesehen worden.\n\nIch weiß nicht genau, was sie vorhaben, aber ich bin mir sicher, es ist nichts Gutes! Bringt mir die Kopftücher, die sie tragen, und ich werde Euch mit einer Waffe belohnen.", sourceObjective = "Bringt 8 rote Sackleinenkopftücher zu Stellvertreter Willem in der Nähe der Abtei von Nordhain.", progress = "Habt Ihr schon diese Kopftücher für mich zusammenbekommen?", completion = "Ah, wie ich sehe, seid Ihr zurück und habt Kopftücher dabei. Die Armee von Stormwind weiß Eure Hilfe zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[19] = { id = 19, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tharil'zun", description = "Zwischen hier und Burg Steinwacht legen Kundschafter und Renegaten des Schwarzfels ständig Hinterhalte. Der Anführer der Kundschafter heißt Tharil'zun und diesen Orc wollen wir haben. Bringt mir den Kopf von Tharil'zun!", sourceObjective = "Bringt den Kopf von Tharil'zun ins Rotkammgebirge zu Marschall Marris.", progress = "Die Blackrockorcs setzen uns noch immer stark unter Druck. Aber habt Ihr uns wenigstens von Tharil'zun befreit?", completion = "Tharil'zun war ein bösartiger, verschlagener Orc. Gut gemacht! Ich bin sicher, er war nicht leicht zu besiegen. Hier ist Eure Belohnung, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[20] = { id = 20, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung durch den Schwarzfelsklan", description = "Die Orcs des Schwarzfelsklans haben die brennende Steppe verlassen und Burg Steinwacht im Norden besetzt. Von dort aus ziehen sie marodierend durch das Gebiet nördlich von Seenhain, so dass dessen Bewohner sich nicht mehr aus der Stadt wagen und dort eingesperrt sind wie Vieh in einem zu engen Pferch.\n\nHelft uns, diese Bedrohung von Seenhain zu nehmen! Tötet diese Orcs des Schwarzfels und bringt mir 10 ihrer kampferprobten Äxte zum Beweis.\n\nUnd obwohl der Schwarzfelsklan uns vor allem aus dem Norden bedroht, haben wir auch gehört, dass sich noch weitere Schwarzfelsorcs in der südöstlichen Ecke des Rotkammgebirges aufhalten. Wenn Ihr dort welche findet, solltet Ihr die auch jagen.", sourceObjective = "Bringt 10 kampferprobte Äxte nach Seenhain zu Marschall Marris.", progress = "Na, habt Ihr Orcs erschlagen, {name}? Dann zeigt es mir.", completion = "Gut, jetzt sind es wesentlich weniger Orcs, um die wir uns sorgen müssen, danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[21] = { id = 21, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharmützel in der Echokammmine", description = "Eure Untersuchungen beweisen, dass die Echokammmine gesäubert werden muss. Kehrt in die Mine zurück und helft dabei, sie von den Kobolden zu befreien.\n\nIhr dürft keine Zeit verlieren, {name}. Je länger die Kobolde sich ungehindert in der Mine aufhalten können, umso festere Wurzeln fassen sie in Nordhain.", sourceObjective = "Tötet 8 Koboldhilfsarbeiter und kehrt dann zu Marschall McBride in der Abtei von Nordhain zurück.", progress = "Ich weiß, das es ein blutiges Geschäft ist, {name}, aber die Sicherheit von Nordhain hängt davon ab. Seid Ihr bereit, mir Bericht zu erstatten?", completion = "Und wieder habt Ihr Euch meinen Respekt und die Dankbarkeit der Armee von Stormwind verdient. Vielleicht gibt es in der Mine noch immer Kobolde, doch ich werde andere schicken, um gegen sie zu kämpfen. Für Euch haben wir andere Aufgaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[22] = { id = 22, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pastete aus Geiferzahnleber", description = "Die Zwiebeln sind geschält, der Knoblauch ist gehackt, der Rosmarin ist zerstoßen, die Kruste ist gebacken, das Dillkraut ist gewiegt und die Sauce steht auf dem Herd. Jetzt brauche ich für meine berühmte Fleischpastete nur noch 8 Geiferzahnlebern!", sourceObjective = "Salma Saldean braucht 8 Geiferzahnlebern für ihre Pastete aus Geiferzahnleber.", progress = "Ich brauche für meine berühmte Fleischpastete nichts weiter als 8 Geiferzahnlebern!", completion = "Die sind genau richtig, {name}! Vielen herzlichen Dank. Heute abend werden Bauer Saldean und ich königlich speisen. Und hier ist auch etwas für Euch, für Eure harte Arbeit. Bei mir muss kein {class} hungern.", sourceObjectiveStatus = "unverified-source-field" }
quests[23] = { id = 23, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursangus' Tatze", description = "Die Tatze des mächtigen Bären Ursangus stellt die Trophäe für diesen Teil der Jagd im Eschental dar. Auf der Tatze befindet sich ein kleines Halbmond-Emblem; die Bedeutung dieses Emblems bleibt jedoch ein Geheimnis.\n\nDie Tatze soll zu Senani Donnerherz im Splitterholzposten gebracht werden, um zu beweisen, dass Ihr das mächtige Tier besiegt und diesen Teil der Jagd abgeschlossen habt.", sourceObjective = "Bringt Ursangus' Tatze zu Senani Donnerherz im Splitterholzposten im Eschental.", progress = "Ah... {name}... ich habe gerade an Euch gedacht! Wie geht es mit der Jagd voran?", completion = "Ah, die Tatze von Ursangus! Euer Geschick ist beeindruckend, {class}, denn er soll etliche Leute getötet haben. Der Halbmond auf seiner Tatze ist zweifelsohne ein Zeichen, dass er von den Nachtelfen ausgebildet wurde, die in Ashenvale herumschleichen. Ursangus ist... war einer der mächtigsten Bären, die Ihr in dieser Gegend finden konntet. Solch eine Kreatur besiegt zu haben, ist ein Beweis Eurer Willenskraft und Eures Mutes.\n\nEure Vorfahren wären stolz auf Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[24] = { id = 24, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattumbras Kopf", description = "Der einstmals so flinke Schattumbra liegt jetzt regungslos vor Euch und der Sieg ist Euer. Der Kopf des erschlagenen Nachtsäblers ist eine passende Trophäe für diesen Kampf. Senani Donnerherz im Splitterholzposten wird eine solche Trophäe sehen wollen, um Euch den Erfolg in diesem Teil der Jagd im Eschental anzurechnen.", sourceObjective = "Bringt Schattumbras Kopf zu Senani Donnerherz im Splitterholzposten im Eschental.", progress = "Seid mir erneut gegrüßt, {name}! Seid Ihr gekommen, um mir einen Beweis Eurer Jagd vorzulegen?", completion = "Ein Sieg für {name} in der Jagd von Ashenvale! Gut gemacht... der Kopf von Schattumbra ist eine passende Trophäe für solch einen beeindruckenden Kampf, keine Frage.\n\nSchattumbras Wildheit war im ganzen Außenposten hier bekannt. Jede Reise nach Westen, insbesondere wenn man zu Fuß versuchte den Zoramstrand zu erreichen, war ob des Tigers von Gefahr überschattet. Dank Euch hat diese Gefahr jetzt ein Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[25] = { id = 25, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stillstand am Steinkrallenpfad", description = "Wenn Ihr Euch nützlich machen wollt, warum unternehmt Ihr dann nicht etwas wegen der Situation am Steinkrallenpfad?\n\nDer Güterverkehr zwischen dem Eschental und dem Steinkrallengebirge steht still, weil der See zum Leben erwacht ist und alles angreift, was ihm zu nahe kommt... und das bedeutet, jeden auf dem Pfad. Noch weitaus nützlicher als einfach nur die Wasserelementare zu unterjochen, wäre es, wenn jemand den Pavillon auf dem Mystralsee auskundschaften würde... der, von dem aus man einen guten Blick auf den dortigen Außenposten der Allianz hat.\n\nNa, wollt Ihr Euch nützlich machen?", sourceObjective = "Erledigt 12 beschmutzte Wasserelementare am Mystralsee östlich vom Steinkrallenpfad und südwestlich vom Splitterholzposten.\n\nErkundet den Pavillon am Mystralsee, der den nahen Außenposten der Allianz überblickt.\n\nKehrt zu Mastok Wutfauch im Splitterholzposten im Eschental zurück.", completion = "Ja, ich habe gehört, dass jemand den See auseinander genommen hat wie ein Staubteufel, der durch das Brachland tobt. So wie es klingt, können wir vielleicht außerdem einen Beobachtungsposten da draußen einrichten, um unsere Freunde von der Allianz im Auge zu behalten. Zumindest wenn wir kein Aufsehen erregen...\n\nEs scheint, als hättet Ihr Euch letzten Endes als ziemlich nützlich erwiesen. Die Transporte zwischen hier und dem Steinkrallengebirge sollten jetzt weniger Probleme haben. Nehmt dies - Ihr habt es Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[26] = { id = 26, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wertvolle Lektion", description = "{name}, ich habe Euren Fortschritt mit großem Genuss verfolgt. Ihr entwickelt Euch definitiv zu einem wertvollen Beschützer der Natur.\n\nEs ist an der Zeit für Euch, mehr über einen der diversen Tieraspekte zu lernen, in die wir uns dank Cenarius' Segen verwandeln können... einen, der Euch die Beherrschung des Wassers ermöglicht. Dazu müsst Ihr zur Mondlichtung in das Dorf Nachthafen reisen und mit Dendrite Sternenschauer vom Zirkel des Cenarius sprechen. Er wird Euch weiter anleiten.", sourceObjective = "Sprecht mit Dendrite Sternenschauer im Dorf Nachthafen auf der Mondlichtung.", completion = "Seid gegrüßt, junger {class}. Es ist an der Zeit für Euch, unsere Wassergestalt kennen zu lernen. Dabei handelt es sich um eine Gestalt, die es Euch ermöglicht, Euch frei und beliebig lange durchs Wasser zu bewegen. Ihr werdet diesen Aspekt als ein nützliches Werkzeug und einen Segen empfinden... aber man muss sich ihn verdienen, bevor man ihn meistern kann.\n\nIhr werdet Euch dafür zwei Prüfungen stellen. Die Erste wird Eure Fähigkeit prüfen, unter Druck im Wasser zu arbeiten. Die Zweite wird Eure Entschlossenheit prüfen, die Aspekte der Form als solche zu verstehen.\n\nMacht Euch bereit, denn die Zeit der Prüfung ist gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27] = { id = 27, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wertvolle Lektion", description = "{name}, ich habe Euren Fortschritt mit großem Genuss verfolgt. Ihr entwickelt Euch definitiv zu einem wertvollen Beschützer der Natur.\n\nEs ist an der Zeit für Euch, mehr über einen der diversen Tieraspekte zu lernen, in die wir uns dank Cenarius' Segen verwandeln können... einen, der Euch die Beherrschung des Wassers ermöglicht. Dazu müsst Ihr zur Mondlichtung in das Dorf Nachthafen reisen und mit Dendrite Sternenschauer vom Zirkel des Cenarius sprechen. Er wird Euch weiter anleiten.", sourceObjective = "Sprecht mit Dendrite Sternenschauer im Dorf Nachthafen auf der Mondlichtung.", completion = "Seid gegrüßt, junger {class}. Es ist an der Zeit für Euch, unsere Wassergestalt kennen zu lernen. Dabei handelt es sich um eine Gestalt, die es Euch ermöglicht, Euch frei und beliebig lange durchs Wasser zu bewegen. Ihr werdet diesen Aspekt als ein nützliches Werkzeug und einen Segen empfinden... aber man muss sich ihn verdienen, bevor man ihn meistern kann.\n\nIhr werdet Euch dafür zwei Prüfungen stellen. Die Erste wird Eure Fähigkeit prüfen, unter Druck im Wasser zu arbeiten. Die Zweite wird Eure Entschlossenheit prüfen, die Aspekte der Form als solche zu verstehen.\n\nMacht Euch bereit, denn die Zeit der Prüfung ist gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28] = { id = 28, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung des Sees", description = "Als Eure erste Prüfung müsst Ihr in den Tiefen des Sees von Elune'ara nach einem Schreinschmuckstück suchen. Es zerfällt schnell, daher solltet Ihr Euch mit größter Eile zum Schrein von Remulos begeben. Benutzt das Schmuckstück am Schrein und sprecht dann dort mit Tajarri; sie ist eine der vertrauenswürdigsten Aufseherinnen der Mondlichtung.\n\nIhr habt nur eine gewisse Zeitspanne für diese Aufgabe zur Verfügung, und Ihr könntet in Konkurrenz zu anderen Druiden stehen, die ebenfalls nach Schmuckstücken suchen. Geistiges wie körperliches Geschick wird für Euren Erfolg unabdingbar sein.\n\nViel Glück, {name}.", sourceObjective = "Sucht ein Schreinschmuckstück im See von Elune'ara und bringt es zum Schrein von Remulos im Nordwesten der Mondlichtung. Wenn Ihr dort seid, benutzt das Schreinschmuckstück.\n\nIhr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen.", completion = "Na so was, es sieht so aus, als hätte erneut ein {class} die Prüfung des Sees erfolgreich abgeschlossen! Gut gemacht... sehr gut.\n\nWie ich schon sagte ist mein Name Tajarri. Es ist meine Pflicht und mein Privileg, Moonglade und insbesondere diesem Schrein als Aufseherin zu dienen. Bewahrer Remulos leitet den Zirkel des Cenarius in seinem Bemühen an, das Gleichgewicht der Natur zu bewahren, und dieser Schrein dient als ständiges Zeichen der Anerkennung dessen. Indem Ihr das Schmuckstück hier benutzt habt, dient es als eine anerkennende Geste für die Wichtigkeit dieses Ortes im Zirkel.", sourceObjectiveStatus = "unverified-source-field" }
quests[29] = { id = 29, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung des Sees", description = "Als Eure erste Prüfung müsst Ihr in den Tiefen des Sees von Elune'ara nach einem Schreinschmuckstück suchen. Es zerfällt schnell, daher solltet Ihr Euch mit größter Eile zum Schrein von Remulos begeben. Benutzt das Schmuckstück am Schrein und sprecht dann dort mit Tajarri; sie ist eine der vertrauenswürdigsten Aufseherinnen der Mondlichtung.\n\nIhr habt nur eine gewisse Zeitspanne für diese Aufgabe zur Verfügung, und Ihr könntet in Konkurrenz zu anderen Druiden stehen, die ebenfalls nach Schmuckstücken suchen. Geistiges wie körperliches Geschick wird für Euren Erfolg unabdingbar sein.\n\nViel Glück, {name}.", sourceObjective = "Sucht ein Schreinschmuckstück im See von Elune'ara und bringt es zum Schrein von Remulos im Nordwesten der Mondlichtung. Wenn Ihr dort seid, benutzt das Schreinschmuckstück.\n\nIhr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen.", progress = "Um die Prüfung des Sees abzuschließen, müsst Ihr das Schreinschmuckstück im Umkreis des Schreines benutzen. Solange Ihr das nicht getan habt, bleibt Eure Prüfung unvollständig und Ihr riskiert einen Fehlschlag.", completion = "Na so was, es sieht so aus, als hätte erneut ein {class} die Prüfung des Sees erfolgreich abgeschlossen! Gut gemacht... sehr gut.\n\nWie ich schon sagte ist mein Name Tajarri. Es ist meine Pflicht und mein Privileg, Moonglade und insbesondere diesem Schrein als Aufseherin zu dienen. Bewahrer Remulos leitet den Zirkel des Cenarius in seinem Bemühen an, das Gleichgewicht der Natur zu bewahren, und dieser Schrein dient als ständiges Zeichen der Anerkennung dessen. Indem Ihr das Schmuckstück hier benutzt habt, dient es als eine anerkennende Geste für die Wichtigkeit dieses Ortes im Zirkel.", sourceObjectiveStatus = "unverified-source-field" }
quests[30] = { id = 30, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung des Seelöwen", description = "Für die zweite Prüfung benötigt Ihr die zwei Hälften, aus denen der Anhänger des Seelöwen besteht. Die eine Hälfte bezieht ihre Kraft aus der Beweglichkeit des Seelöwen-Aspektes beim Gleiten durchs Wasser; die andere Hälfte bezieht ihre Kraft aus der unglaublichen Ausdauer des Seelöwen-Aspektes. Druiden bedienen sich dieser beiden Eigenschaften gleichermaßen, um den Aspekt ihrer Wassergestalt zu verkörpern.\n\nSprecht mit den Bewohnern der Mondlichtung, um herauszufinden, wo sich die Teile befinden könnten, und bringt beide hierher, um sie miteinander zu vereinen. Bringt den Anhänger zu Dendrite Sternenschauer, wenn Ihr ihn geschaffen habt.", sourceObjective = "Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserbelastbarkeit. Sprecht mit den Einwohnern der Mondlichtung, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.\n\nFormt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.\n\nBringt den zusammengefügten Anhänger zu Dendrite Sternenschauer im Dorf Nachthafen auf der Mondlichtung.", progress = "Habt Ihr Euren Anhänger geschaffen, auf dass ich ihn mir ansehen kann, {name}? Falls Ihr Hilfe beim Aufspüren der Teile braucht, bittet am besten die örtliche Bevölkerung um Hinweise. Ihr werdet dabei nicht nur finden, was Ihr sucht, sondern habt außerdem noch einen guten Grund, dieses wunderbare und heilige Tal zu erforschen.", completion = "Ihr habt die Prüfung des Seelöwen erfolgreich beendet, {name}... Glückwunsch.\n\nJede Teilaufgabe bei der Beschaffung des Anhängers zeigt, dass man sowohl Beweglichkeit als auch Ausdauer benötigt, um in Harmonie mit dem agieren zu können, was Ihr unter Wasser tun wollt. Keine der Eigenschaften kann ohne die andere existieren, und beide können nicht erreicht werden ohne Euren Willen, den Aspekt des Seelöwen in Euch aufzunehmen.\n\nMerkt Euch diese Lektionen gut und verlasst Euch auf sie, wenn Ihr Eure Wassergestalt erworben habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31] = { id = 31, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wassergestalt", description = "Ihr habt die notwendigen Lektionen gemeistert, die alle jungen Druiden lernen, bevor sie einen Wasseraspekt annehmen können. Kehrt jetzt zu Eurem Lehrer Turak Runentotem nach Donnerfels zurück. Zeigt ihm Euren Anhänger und beweist ihm damit, dass Ihr bereit seid zu lernen, was er Euch lehren kann. Er wird Eure Ausbildung abschließen und Euch ermöglichen, eins mit dem Wasser zu werden.\n\nAuf Wiedersehen. Wir werden uns wieder sprechen.", sourceObjective = "Kehrt nach Donnerfels zurück und zeigt Turak Runentotem den Anhänger des Seelöwen.", progress = "Eure Rückkehr nach Thunder Bluff kommt nicht überraschend, doch ich werde einen Beweis dafür benötigen, dass Ihr die Lektionen in Moonglade gelernt habt, bevor ich Euch Eure Wassergestalt lehre.\n\nHabt Ihr den Anhänger des Seelöwen?", completion = "Sehr beeindruckend, {name}. Eure Vorfahren wären erfreut über Euren Fortschritt! Ihr seid bereit, Eure Wassergestalt zu erlernen, und ich habe das Vergnügen, sie Euch zu lehren.\n\nAußerdem übergebe ich Euch als Anerkennung Eurer Leistungen während der beiden Prüfungen diesen Gegenstand. Ich hoffe, Ihr werdet ihn als eine wertvolle Ergänzung Eurer Ausrüstung als Beschützer der Natur und Bewahrer des Gleichgewichts ansehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32] = { id = 32, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Silithiden", description = "Hier ist Euer Bericht. Ihr solltet damit zu jemandem gehen, der ausreichend Kenntnis von solchen Dingen hat.\n\nIch kenne da einen Trollgelehrten mit Namen Zilzibin Tomtom. Er hat viel Zeit mit dem Studium der Lebensformen verbracht, die in der Ökologie von Azeroth einzigartig sind, und er ist noch dazu Historiker! Wenn Euch jemand helfen soll herauszufinden, was genau diese Bedrohung ausmacht, und wie sie zu stoppen ist, gebt ihm diesen Bericht. Hilfe können wir gar nicht genug haben.\n\nZil lebt in einem Haus auf der zweiten Ebene der Gasse in Orgrimmar.", sourceObjective = "Bringt den Bericht nach Orgrimmar zu Zilzibin Tomtom.", progress = "Es tut mir Leid, ich kenne Euch nicht... aber so wie es aussieht, habt Ihr zumindest schon von mir gehört. Nun, wie kann ich Euch helfen? Habt Ihr etwas für mich?", completion = "Dieser Bericht... Ich habe mich schon zuvor mit diesen Bestien beschäftigt. Fizzledowser hat gut daran getan, dies und Euch zu mir zu schicken.\n\nDiese Kreaturen werden die Tanariswüste schnell verzehren; sie stellen so ziemlich die größte Bedrohung dar, der wir uns je gegenübersehen werden. Macht Euch mit diesem Namen vertraut, {name}: Silithid. Die hier erwähnten Insekten sind die Silithid und sie sind das Werkzeug einer der größten Bedrohungen, der sich die Horde und die Allianz gegenübersehen.\n\nWenn wir nur früher schon klug genug gewesen wären, das zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33] = { id = 33, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wölfe an der Grenze", description = "Was auch immer diese Wölfe sich eingefangen haben, es geht nicht weg. Jeden Tag tauchen weitere kranke Wölfe auf. Es tut mir in der Seele weh, dass jemand diese Schöpfungen der Natur in meinem Namen töten muss, aber wir müssen die erkrankten jungen Wölfe erledigen, bevor die lokale Ansteckung zu einer Epidemie wird.\n\nTötet erkrankte junge Wölfe im Tal und bringt mir ihre Pelze als Beweis Eurer Tat.", sourceObjective = "Bringt Eagan Pelzschneider, den Ihr vor der Abtei von Nordshire findet, 8 Pelze von erkrankten Wölfen.", progress = "He, {name}, Ich kriege langsam Hunger. Habt Ihr das zähe Wolfsfleisch bekommen?", completion = "Ihr wart aber fleißig! Ich kann es kaum erwarten, dieses Wolfsfleisch aufs Feuer zu bringen.\n\nIch habe hier ein paar Sachen, die Euch vielleicht gefallen könnten - greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[34] = { id = 34, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ungebetener Gast", description = "Mein Garten ist schon wieder zertrampelt und verwüstet worden. Und ich weiß genau, was für ein Tier das getan hat. Das war dieser elende Eber, der, den Marschall Marris seit einer Weile immer \"Stopfwanst\" nennt.\n\nJetzt kann ich die Narzissen erst nächsten Herbst wieder anpflanzen. Hin! Alle hin, und das nur wegen dieses einen gefährlichen Ebers. Bereitet dieser Plage ein Ende! Zeigt mir seinen Hauer und ich werde Euch nur zu gern belohnen. Die meiste Zeit scheint er damit zu verbringen, in den Feldern südwestlich von Seenhain nach Futter zu suchen, doch gelegentlich verirrt er sich auch hierher und in meinen Garten.", sourceObjective = "Martie Jainrose aus Seenhain möchte, dass Ihr Stopfwanst tötet. Bringt ihr den Hauer des Ebers zum Beweis.", progress = "Treibt Stopfwanst noch immer sein Unwesen, oder ist es Euch gelungen, Seenhain ein für alle Mal von dieser Plage zu befreien?", completion = "Endlich hat die Bedrohung ein Ende! Ich danke Euch, {name}, Ihr habt mir einen großen Dienst erwiesen. Dieses Jahr wird mein Garten herrlich blühen!", sourceObjectiveStatus = "unverified-source-field" }
quests[35] = { id = 35, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Sorgen", description = "Falls Ihr befürchtet, dass die Gerüchte über das Auftauchen von Murlocs wahr sein könnten, dann tut das Folgende: Begebt Euch zur östlichen Brücke von Elwynn und sprecht mit Wache Thomas. Er ist seit einer Woche an der Brücke stationiert und wird deswegen wissen, wie es in der Gegend aussieht.\n\nBringt mir seinen Bericht.", sourceObjective = "Marschall Dughan möchte, dass Ihr mit Wache Thomas sprecht.", completion = "Ja, es haben sich Murlocs in und an den Flüssen und Bächen des östlichen Elwynn niedergelassen. Wir wissen nicht, warum sie hergekommen sind, aber sie sind aggressiv und zumindest halbintelligent.", sourceObjectiveStatus = "unverified-source-field" }
quests[36] = { id = 36, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westfalleintopf", description = "Ich hätte nie gedacht, dass jemals der Tag kommen würde, an dem ich den Hof verlasse. Aber in den Feldern wimmelt es nur so von Dieben und es ist hier für uns viel zu gefährlich geworden. Sobald Bauer Brauenwirbel den Wagen repariert hat, machen wir uns auf den Weg.\n\nKönntet Ihr mir vielleicht einen Gefallen tun? Ich schreibe Euch schnell mein Rezept für Westfalleintopf auf. Seid so nett und bringt es Salma Saldean; sie wohnt auf dem Hof dort hinten. Ihr findet den Hof der Saldeans gleich hinter der Gabelung der Straße.", sourceObjective = "Verna Brauenwirbel möchte, dass Ihr ihr Rezept für Westfalleintopf bei Salma Saldean abliefert.", progress = "Ich werde die Verna Furlbrow sehr vermissen! Ich nehme nicht an, dass Ihr ihr auf dem Weg hierher begegnet seid?", completion = "Die Verna ist immer so ein liebes Mädchen gewesen! Wir werden sie hier in Westfall vermissen, aber ganz ehrlich und nur unter uns, sie ist ja eigentlich ein Stadtkind und deswegen wird sie sich in Stormwind pudelwohl fühlen. Aber genug getratscht! Jetzt können wir Westfall-Eintopf kochen!", sourceObjectiveStatus = "unverified-source-field" }
quests[37] = { id = 37, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach den vermissten Wachen", description = "Vor ein paar Tagen haben wir zwei Wachen, Rolf und Malakai, losgeschickt, damit sie entlang des Flusses Nachforschungen anstellen, aber bisher sind sie noch nicht zurückgekehrt. Damit ich meinen Bericht fertig schreiben kann, muss ich wissen, was den beiden Männern zugestoßen ist.\n\nSucht den Fluss in Richtung Norden ab und seht zu, dass Ihr die Wachen findet... oder ihre Überreste...", sourceObjective = "Wache Thomas möchte, dass Ihr den Fluss in Richtung Norden nach Rolf und Malakai, den beiden vermissten Wachen, absucht.", completion = "Vom Leichnam selbst ist nicht mehr viel zu erkennen. Doch in der Nähe findet Ihr ein Medallion, in das die Worte \"Malakai Stone, Soldat\" eingeprägt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[38] = { id = 38, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westfalleintopf", description = "Wollt Ihr mir dabei helfen, Westfalleintopf zu kochen? Dann bringt mir die folgenden Zutaten: \n\n 3 Stücke sehniges Geierfleisch\n 3 Geiferzahnschnauzen \n 3 Murlocaugen \n 3 Okraschoten", sourceObjective = "Salma Saldean möchte 3 Stücke sehniges Geierfleisch, 3 Geiferzahnschnauzen, 3 Murlocaugen und 3 Okraschoten.", progress = "Dann bringt mir die folgenden Zutaten: \n\n 3 Stücke sehniges Geierfleisch\n 3 Geiferzahnschnauzen \n 3 Murlocaugen \n 3 Okraschoten", completion = "Das Okra wird die Brühe schön eindicken. Und jetzt geben wir nur noch das sehnige Geierfleisch, ein paar Murlocaugen und diese leckeren Geiferzahnschnauzen dazu. Und fertig! Ich möchte, dass Ihr für all Eure Hilfe den ersten Schwung Westfall-Eintopf bekommt, {name}. Hier, nehmt!", sourceObjectiveStatus = "unverified-source-field" }
quests[39] = { id = 39, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zustellung von Thomas' Bericht", description = "Berichtet Marschall Dughan, dass Malakai und Rolf ums Leben gekommen sind, und teilt ihm auch mit, dass wir die Murlocs in Ost-Elwynn mit unserer derzeitigen Truppenstärke hier nicht unter Kontrolle halten können.\n\nIch weiß, dass wir nicht viele überzählige Männer haben, aber vielleicht findet Dughan ja doch jemanden.", sourceObjective = "Erstattet Marschall Dughan in Goldhain Bericht.", completion = "Hmm... das sind beunruhigende Neuigkeiten. Unsere Reihen sind ohnehin schon ausgedünnt, und dass wir jetzt auch noch Rolf und Malakai verloren haben, macht die Lage noch schlimmer.\n\nWenn sich die Dinge nicht bald ändern, dann wird in ein paar Tagen sogar Goldhain umkämpft sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[40] = { id = 40, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr aus dem Wasser", description = "Eine neue Gefahr bedroht den Wald von Elwynn, {name}! Murlocs kommen die Bäche und Flüsse im östlichen Elwynn hinaufgeschwommen, vertreiben die Fische und greifen einfache Leute an!\n\nIch habe Marschall Dughan bereits gewarnt, aber der macht sich größere Sorgen wegen der Gnolle und der Banditen. Er ist nicht überzeugt davon, dass die Murlocs eine Gefahr darstellen.\n\nBitte sprecht mit Dughan, {name}, und bringt ihn dazu, dass er Verstärkung in den Osten schickt!", sourceObjective = "Remy \"Zweifach\" möchte, dass Ihr in Goldhain mit Marschall Dughan sprecht.", completion = "Ja, ich habe mit Remy darüber gesprochen. Er ist ein guter Händler und ich respektiere ihn, aber alle Berichte von Murlocs im Osten waren bisher bestenfalls bruchstückhaft.\n\nIch nehme Eure Sorgen zur Kenntnis, aber solange ich nicht einen zuverlässigen Bericht aus berufener militärischer Quelle erhalte, der bestätigt, dass die Murlocs tatsächlich eine Bedrohung darstellen, können wir es uns nicht leisten, weitere Soldaten nach Osten zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[45] = { id = 45, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rolfs Schicksal", description = "Als Ihr die Gegend weiter absucht, findet Ihr die Abdrücke von Füßen mit Schwimmhäuten, die entlang dem Ufer des Steinhügelsees nach Osten führen. In der Ferne könnt Ihr im Osten gerade noch so ein Murlocdorf ausmachen.\n\nVielleicht fand Rolfs Leben dort sein Ende...", sourceObjective = "Durchsucht das Murlocdorf nach Rolf - oder nach Anzeichen für seinen Tod.", completion = "Um den Hals trägt der Leichnam ein Medaillon aus Metall, auf dem die Worte \"Rolf Hartford, Soldat\" stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46] = { id = 46, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld auf die Murlocs", description = "Die Armee von Sturmwind hat ein Kopfgeld auf die Murloclauerer und Murlocfutterwühler ausgesetzt, die sich in Elwynn herumtreiben. Erlegt sie und bringt mir ihre zerrissenen Murlocflossen, dann wird die Armee von Sturmwind Euch ansehnlich belohnen\n\nDie Murlocs haben am Steinhügelsee nördlich von hier ein Dorf errichtet und ein weiteres ihrer Dörfer befindet sich im Süden, wo der Fluss sich teilt.", sourceObjective = "Bringt 8 zerrissene Murlocflossen zu Wache Thomas, den ihr an der östlichen Brücke von Elwynn findet.", progress = "Wie läuft die Jagd, {name}?", completion = "Habt Ihr die Flossen? Ausgezeichnet! Marshal Dughan ist besorgt wegen der Murlocbedrohung in Ost-Elwynn und ich würde ihm gern berichten können, dass wir die Lage langsam unter Kontrolle bekommen.\n\nMit Euren Taten habt Ihr uns dabei geholfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47] = { id = 47, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tauschhandel mit Goldstaub", description = "Manchmal haben die Kobolde in dieser Gegend Goldstaub dabei. Das Zeug könnte ich wirklich gut gebrauchen. Bringt mir etwas davon und ich mache Euch den besten Preis in der Stadt... den besten Preis in der Stadt!\n\nDie Kobolde halten sich in der Tiefenschachtmine im Süden und im Bereich der Jaspismine im Nordosten auf.", sourceObjective = "Bringt 10 Einheiten Goldstaub nach Goldhain zu Remy \"Zweifach\". Goldstaub findet Ihr bei den Kobolden im Wald von Elwynn.", progress = "Psst! Habt Ihr den Goldstaub für mich... für mich?", completion = "Danke für den Goldstaub, {name}. Hier habt Ihr Euer Geld und hier habt Ihr noch eine kleine... Zugabe von Freunden von mir. Das könnte Euch vielleicht noch nützlich werden... nützlich werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[48] = { id = 48, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldbrauner Samt", description = "Weit im Süden, wo die Lianen sich ranken\nLiegt versteckt ein Brunnen, in dem fast versanken\nDie wertvollen Wasser, so rein und so helle - \nBringt mir Wasser von der Heiligen Quelle.", sourceObjective = "Bringt Schnapsbart Donnerbräu Wasser von der Heiligen Quelle.", progress = "Hicks und Hurra, Wollt Ihr's nochma'?\n\nWeit im Süden, wo die Lianen sich ranken,\nLiegt versteckt ein Brunnen, in dem sie fast versanken\nDie wertvollen Wasser, so rein und so helle - \nBringt mir Wasser von der Heiligen Quelle.", completion = "Hicks und Hurra!", sourceObjectiveStatus = "unverified-source-field" }
quests[49] = { id = 49, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldbrauner Samt", description = "Lang schon vermiss ich die Lieb meines Lebens\nGoldbraun und samtig, doch noch wart ich vergebens\nBringt mir, dann vergeht jeder Zorn\nJe einen Sack Gerste, Roggen und Korn.", sourceObjective = "Schnapsbart Donnerbräu möchte einen Sack Gerste, einen Sack Roggen und einen Sack Korn haben.", progress = "Nochma'? Na klar!\n\nLang schon vermiss ich die Lieb meines Lebens,\nGoldbraun und samtig, doch noch wart ich vergebens.\nBringt mir, dann vergeht jeder Zorn,\nJe einen Sack Gerste, Roggen und Korn.", completion = "Hicks und Hurra!", sourceObjectiveStatus = "unverified-source-field" }
quests[50] = { id = 50, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldbrauner Samt", description = "Die Maische anrühren, das ist mein Wille\nDoch fehlt mir dann auch noch eine Destille\nFür diese brauch ich ein starkes Metall\nBringt mir Echtsilber, das ist gut in dem Fall!", sourceObjective = "Schnapsbart Donnerbräu braucht Echtsilber.", progress = "Wollt Ihr's noch mal hören? Dann lasst Euch nicht stören!\n\nDie Maische anrühren, das ist mein Wille,\nDoch fehlt mir dann auch noch eine Destille\nFür diese brauch ich ein starkes Metall\nBringt mir Echtsilber, das ist gut in dem Fall!", completion = "Hicks und Hurra!", sourceObjectiveStatus = "unverified-source-field" }
quests[51] = { id = 51, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldbrauner Samt", description = "Noch ist er nicht fertig, doch schon frisch gebrannt\nJetzt wird als Nächstes der Meiler bemannt\nUm den Whisky zu filtern. Drum bringt mir den Ast\nEines Bergahorns - wenn Ihr könnt, ohne Rast!", sourceObjective = "Bringt Schnapsbart Donnerbräu den Ast eines Bergahorns.", progress = "Soll ich's noch mal sagen? Ihr müsst mich nur fragen!\n\nNoch ist er nicht fertig, doch schon fertig gebrannt.\nJetzt wird als Nächstes der Meiler bemannt, \nUm den Whisky zu filtern. Drum bringt mir den Ast\nEines Bergahorns - wenn Ihr könnt, ohne Rast!", completion = "Hicks und Hurra!", sourceObjectiveStatus = "unverified-source-field" }
quests[52] = { id = 52, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenzschutz", description = "Seid gegrüßt, {name}. Je weiter wir uns von Goldhain entfernen, umso reizbarer sind die wilden Tiere. Und das Holzfällerlager des Osttals wird beinahe ständig von Wölfen und Bären angegriffen.\n\nWir könnten hier draußen wirklich Eure Hilfe gebrauchen.", sourceObjective = "Tötet 8 Streuner und 5 junge Waldbären und kehrt dann zu Wache Thomas an der östlichen Brücke von Elwynn zurück.", progress = "Habt Ihr die Wölfe und Bären schon getötet, von denen ich sprach?", completion = "Vielen Dank für Eure Hilfe, {name}. Im Wald muss es irgendetwas geben, das die Tiere so angriffslustig macht.\n\nWas auch immer es sein mag, ich hoffe, es bleibt dort!", sourceObjectiveStatus = "unverified-source-field" }
quests[53] = { id = 53, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldbrauner Samt", description = "Das Getränk, das ich braue, das reine und klare\nWird goldbraun und samtig im Laufe der Jahre\nDoch ehe er fertig, der Whisky, der weiche\nBraucht's noch ein Fass aus verkohlter Eiche.", sourceObjective = "Bringt Schnapsbart Donnerbräu ein verkohltes Eichenbündel.", progress = "Soll ich's noch mal singen? Ihr müsst mich nicht zwingen!\n\nDas Getränk, das ich braue, das reine und klare,\nWird goldbraun und samtig im Laufe der Jahre.\nDoch ehe er fertig, der Whisky, der weiche,\nBraucht's noch ein Fass aus verkohlter Eiche.", completion = "Im Fasse gealtert, gefiltert durch Kohle,\nRinnt er durch die Kehle zu jedermanns Wohle.\nSo lasset uns trinken und prosten mit dem Gebräu.\nAuf Euch und auf mich, Grimbooze Donnerbräu!", sourceObjectiveStatus = "unverified-source-field" }
quests[54] = { id = 54, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung in Goldhain", description = "{name}, Ihr habt bewiesen, dass Ihr als {class} Euch um die Sicherheit von Nordhain sorgt. Nun erhaltet Ihr die Aufgabe, Euch auch dem Schutz des umliegenden Waldes von Elwynn zu widmen.\n\nWenn Ihr Euch dieser Aufgabe stellen wollt, dann nehmt diese Papiere, die bei Marschall Dughan in Goldhain abgeliefert werden müssen. Goldhain liegt an der südlichen Straße, hinter den Grenztoren.", sourceObjective = "Liefert Marschall McBrides Dokumente bei Marschall Dughan in Goldhain ab.", progress = "Ihr bringt Nachricht von McBride? Im Vergleich zum Wald von Elwynn ist Nordhain das reinste Paradies. Wir wollen doch mal sehen, was Marshal McBride so zu berichten hat...\n\nGebt mir doch bitte seine Papiere.", completion = "Oha, hier steht, dass Ihr in den Rang des kommissarisch ernannten Deputys der Marshals von Stormwind erhoben worden seid. Herzlichen Glückwunsch.\n\nUnd viel Erfolg bei der Arbeit - Elwynn sicher zu machen ist kein Spaziergang, zumal der größte Teil der Armee sonstwo zugange ist und sonstwas für irgendwelche Adligen macht!\n\nEs ist schon schwer, in diesen dunklen Zeiten den Überblick über die Politik zu behalten...", sourceObjectiveStatus = "unverified-source-field" }
quests[55] = { id = 55, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morbent Teufel", description = "Morbent Teufel hält sich in seinem Unterschlupf verborgen, dem Haus, das hoch oben auf dem Hügel im Osten über dem Friedhof von Rabenflucht thront. Doch seine Zeit in diesem Land neigt sich dem Ende entgegen...\n\nSetzt Morbents Bann gegen ihn ein. Das wird seine schützenden Zauber machtlos machen.\n\nErschlagt ihn. Erschlagt ihn und errettet uns von seiner Verderbtheit. Werdet zum Instrument meiner Rache und damit <zum Helden/zur Heldin> des Dämmerwalds!", sourceObjective = "Verwendet Morbents Bann gegen Morbent Teufel, tötet Morbent Teufel und bringt Morbents Bann anschließend zu Sven in dessen Lager zurück.", progress = "Ist Morbent Fel geschlagen?!", completion = "Morbent Fel ist besiegt. Die dunklen Reiter sind immer noch frei, aber das, worauf ich wider besseres Wissen gehofft hatte, ist zumindest zu einem kleinen Teil eingetreten.\n\nIhr habt das Unmögliche vollbracht und Eure Taten werden auf alle Zeit in der Überlieferung des Dämmerwalds weiterleben.\n\nGeht, {name}. Und vielleicht bringt Euch das Schicksal eines Tages zurück zu mir...", sourceObjectiveStatus = "unverified-source-field" }
quests[56] = { id = 56, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtwache", description = "Als Kommandantin der Nachtwache habe ich geschworen, die Bürger von Dunkelhain zu beschützen. Sturmwind hat alle offiziell ernannten Wachen von ihren Posten hier abgezogen; damit sind wir uns selbst überlassen.\n\nWenn Ihr glaubt, der Aufgabe gewachsen zu sein, könnten wir Eure Hilfe wirklich gebrauchen! Helft der Nachtwache und wagt Euch in den Friedhof \"Stille Gärten\", der ein Stückchen südlich von Dunkelhain liegt. Tötet dort 8 Skelettkieger und 6 Skelettmagier. Der Bedrohung durch die Untoten muss ein Ende gemacht werden!", sourceObjective = "Kommandantin Althea Schwarzhaupt aus Dunkelhain möchte, dass Ihr 8 Skelettkrieger und 6 Skelettmagier tötet.", progress = "Wie ich sehe, seid Ihr zurück, {name}. Wenn Ihr Euch für die Nachtwache als nützlich erweisen wollt, dann kehrt zu mir zurück, sobald Ihr 8 Skelettkrieger und 6 Skelettmagier getötet habt.", completion = "Ausgezeichnet, {name}. Für Eure Dienste an ganz Dunkelhain sollt Ihr gut belohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[57] = { id = 57, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtwache", description = "Ich habe berichtet bekommen, dass im Wald eine wahre Untotenplage ausgebrochen ist, {name}. Wenn Ihr Euch der Aufgabe gewachsen fühlt, dann macht Euch auf den Weg zum Friedhof von Rabenflucht und erschlagt 15 dieser abscheulichen Skelettscheusale und 15 Skelettschrecken. Außerdem sollen im Friedhof \"Stille Gärten\", der sich ein Stückchen südlich von Dunkelhain befindet, Skelette gesehen worden sein. Die Untoten müssen aus dem Dämmerwald vertrieben werden!", sourceObjective = "Kommandantin Althea Schwarzhaupt aus Dunkelhain möchte, dass Ihr 15 Skelettscheusale und 15 Skelettschrecken tötet.", completion = "Die Bewohner von Dunkelhain sind Euch zu Dank verpflichtet, {name}. Ihr habt bewiesen, dass Ihr der Nachtwache ein wertvoller Verbündeter seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[58] = { id = 58, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtwache", description = "Die Lage in Rabenflucht ist noch immer sehr bedenklich. Die Sicherheit von Dunkelhain liegt in Euren Händen, {name}. Ich habe einfach nicht genug Behüter, um die Sicherheit in der Stadt zu gewährleisten. Deswegen müsst Ihr Euch erneut nach Rabenflucht aufmachen und das östliche Mausoleum von den Seuchenverbreitern säubern, die sich dort breit gemacht haben. Tötet 20 von ihnen!", sourceObjective = "Kommandantin Althea Schwarzhaupt aus Dunkelhain möchte, dass Ihr im östlichen Mausoleum von Rabenflucht 20 Seuchenverbreiter tötet.", completion = "Im Namen der Bewohner von Dunkelhain und als Anführerin der Nachtwache danke ich Euch, {name}, für Euren Mut und Eure Hingabe. Möge das Licht über all Euren Wegen leuchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[59] = { id = 59, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstung aus Tuch und aus Leder", description = "Als Dank für Eure Gewitztheit und Euren Mut gebe ich Euch hier einen Gutschein, den Ihr gegen ein Rüstungsteil eintauschen könnt. Bringt den Gutschein ins Holzfällerlager des Osttals zu Sara Roderwald. Wenn Ihr ihr den Gutschein gebt, dann stellt sie die Rüstung für Euch her. Und wenn Ihr sie habt, tragt sie zur Verteidigung von Elwynn, {name}.\n\nIhr findet das Holzfällerlager des Osttals im Osten jenseits von Wache Thomas' Posten.", sourceObjective = "Gebt Sara Roderwald den Rüstungsgutschein der Armee von Sturmwind.", progress = "Ich bin von der Armee von Stormwind beauftragt, ihre Soldaten mit Rüstung aus Tuch und aus Leder auszustatten.\n\nWenn Ihr einen Gutschein für mich habt, dann stelle ich gern etwas für Euch her.", completion = "Ja, einen solchen Gutschein meinte ich. Danke! Bitte sucht Euch das Stück aus, das Ihr möchtet.\n\nIch wünsche Euch viel Glück auf Eurem Weg als {class}. Und möge diese Rüstung Euch gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[60] = { id = 60, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koboldkerzen", description = "Guten Tag, <werter Herr/werte Dame>! Hättet Ihr einen Moment Zeit für mich?\n\nMein Bruder und ich führen in Sturmwind eine Apotheke und ich bin hier, weil ich große Kerzen suche, ihres Wachses wegen. Könnt Ihr mir vielleicht helfen?\n\nGroße Kerzen könnt Ihr von Kobolden bekommen - und ich habe Gerüchte gehört, dass Kobolde sich in den Minen von Elwynn eingenistet haben: in der Tiefenschachtmine im Süden und in der Jaspismine im Osten. Ich schlage vor, dass Ihr Euch an einem dieser Orte auf die Suche nach Kerzen begebt.", sourceObjective = "Bringt 8 große Kerzen nach Goldhain zu William Pestle.", progress = "Habt Ihr schon die Kerzen gesammelt?", completion = "Ihr habt wohl eifrig Kobolde gejagt, hmm? Danke für die Kerzen, {name}. Hier habt Ihr Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[61] = { id = 61, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung nach Sturmwind", description = "In Sturmwind wartet mein Bruder Morgan auf die Lieferung der Kerzen. Ich habe selbst nicht die Zeit, um mich auf die Reise zu begeben, aber wenn Ihr ihm die Lieferung überbringen wollt, so wird er Euch gut bezahlen.\n\nIch habe die Kerzen schon fertig verpackt. Ihr findet Morgan in unserem Geschäft im Handelsdistrikt von Sturmwind. Es heißt Pestles Apotheke.", sourceObjective = "Bringt Williams Lieferung in den Handelsdistrikt von Sturmwind zu Morgan Pestle.", progress = "Ah, eine Lieferung von meinem Bruder? Ausgezeichnet! Heute ist mir das Glück wirklich gewogen!", completion = "Hier habt Ihr Eure Bezahlung. Und wenn Ihr schon einmal hier seid, schaut Euch ruhig um! Ich bin sicher, dass wir den einen oder anderen Trank oder sonst irgendetwas haben, dass Euch von Nutzen wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[62] = { id = 62, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiefenschachtmine", description = "Die Mine in Nordhain ist nicht die einzige, mit der es Probleme gibt. Berichten zufolge ist auch die Tiefenschachtmine im Wald von Elwynn zu einem Tummelplatz für Kobolde geworden.\n\nErforscht die Mine, bestätigt diese Berichte und kehrt dann zu mir zurück. Die Mine liegt fast genau südlich von Goldhain, zwischen den Höfen der Steinfelds und der Maclures.", sourceObjective = "Erforscht die Tiefenschachtmine und kehrt dann nach Goldhain zu Marschall Dughan zurück.", completion = "Das sind allerdings schlechte Nachrichten. Was kommt als Nächstes, Drachen?!? Wir werden wohl unsere Patrouillen rund um die Mine verstärken müssen. Habt Dank für Eure Bemühungen, {name}. Und wartet einen Moment... Ich habe vielleicht noch eine andere Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[63] = { id = 63, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "An der Küste des Silberwalds befindet sich westlich des Grabmals ein Schrein, der von der Seuche besudelt ist. Die Geister dort sprechen nicht länger zu unserem Volk und es ist jetzt an Euch, die Manifestation dort zu besiegen und den Teich zu säubern.\n\nNehmt die Armschienen des Elementars und gebt sie zusammen mit den verbleibenden Tropfen von Brines Trank in die Kohlenpfanne. Das sollte ausreichen, um einen reinen Geist zu beschwören, mit dem Ihr kommunizieren könnt.\n\nBringt mir einen Beweis dafür, dass Ihr die Tat vollbracht habt, dann belohne ich Euch mit Eurem Totem.", sourceObjective = "Besiegt die verderbte Wassermanifestation und legt die Armschienen der verderbten Manifestation und die verbleibenden Tropfen reinsten Wassers im Silberwald auf die Kohlenpfanne von Immerquell.", progress = "Die Kohlenpfanne wirft immer noch das Licht der Umgebung zurück und die Flammen flackern leise, als Ihr näher herantretet.\n\nDie in diesen Bergen vorherrschende Verderbnis scheint sich hier noch nicht ausgebreitet zu haben und abgesehen von den fehlenden Komponenten scheint die Kohlenpfanne bereit dafür zu sein, dass jemand das Ritual zur Beschwörung einer gesäuberten Wassermanifestation durchführt.", completion = "Ihr legt die Armschienen des Elementars auf die Kohlenpfanne, dann gießt Ihr die verbleibenden Tropfen von Brines Trank in die Flammen. Die Flüssigkeit knistert, als sie mit den Flammen in Berührung kommt, und Ihr beginnt, die einfachen Worte zu rezitieren, die Islen Euch gelehrt hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[64] = { id = 64, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das vergessene Erbstück", description = "Es war fürchterlich! Verna hat mich aufgeweckt, als sie draußen auf dem Feld so einen Radau gehört hat. Das ganze Feld war voller Rowdys! Wir sind in solcher Eile aufgebrochen und da hab ich vergessen, meine Taschenuhr einzupacken. Die Uhr hat mir Vernas Vater an unserem Hochzeitstag geschenkt und es wird mir fast schlecht, wenn ich dran denke, dass diese Diebe sie jetzt haben. Ich hab die Taschenuhr im Kleiderschrank in unserem Haus liegen lassen. Haltet nach dem Kürbisfeld im Westen Ausschau, dann kommt Ihr zu unserem Hof - Ihr könnt ihn gar nicht verfehlen. Wenn Ihr mir meine Uhr wiederbringen würdet, wäre ich Euch sehr dankbar.", sourceObjective = "Bauer Brauenwirbel möchte, dass Ihr seine Taschenuhr holt. Sie befindet sich im Kleiderschrank des Bauernhauses auf der Kürbisfarm im Westen.", progress = "Ich nehm nicht an, dass Ihr meine Uhr gekriegt habt, oder?", completion = "Meine Uhr! Oh, danke, danke vielmals, werter Herr! \n\nWir sind nur arme Bauern und wir haben unser Land verloren, aber nehmt doch bitte dies als Zeichen unseres Dankes.", sourceObjectiveStatus = "unverified-source-field" }
quests[65] = { id = 65, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bruderschaft der Defias", description = "Die Bruderschaft der Defias nennt sich die Bande von Schuften, von der die braven Leute von Westfall aus dem Land vertrieben werden. Ihr müsst für mich diese Bande bespitzeln. Wir müssen erfahren, wer der Kopf der Gruppe ist und wo sie ihr Versteck hat. In Seenhain findet Ihr im Gasthaus einen Schurken namens Wiley, der mir noch einen Gefallen schuldet.\n\nBegebt Euch nach Seenhain im Rotkammgebirge, östlich von Elwynn, und findet heraus, was Ihr könnt.", sourceObjective = "Gryan Starkmantel möchte, dass Ihr in Seenhain mit Wiley sprecht.", completion = "So, Stoutmantle hat Euch geschickt, hm? Na ja, dem schulde ich noch was.", sourceObjectiveStatus = "unverified-source-field" }
quests[66] = { id = 66, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Letzte Nacht verspürte ich in meinem Geist eine schreckliche Erschütterung. Ich wusste, dass sich meine Enkelin Alyssa in großer Gefahr befand. Ich befragte die Karten und aus ihnen starrte mich die Fratze des Todes höhnisch an.\n\nIch begab mich auf eine lange Reise durch eine dunkle Trance und schließlich gelang es mir, einen Hinweis auf dieses schreckliche Geheimnis zu erhaschen. Ein Name erschloss sich mir, der Name Stalvan.\n\nSucht den Amtmann im Rathaus auf und schaut, ob Ihr nicht mehr über diese Person herausfinden könnt. Ich fürchte um unser aller Leben.", sourceObjective = "Sucht Amtmann Daltry im Rathaus von Dunkelhain auf.", completion = "Madame Eva hat Euch also geschickt...", sourceObjectiveStatus = "unverified-source-field" }
quests[67] = { id = 67, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Stalvan, hm? Lasst mich im Stadtverzeichnis nachsehen.\n\nStalvan... Stalvan... mal sehen. Ah, hier ist es! Ich habe hier einen Eintrag über einen gewissen Stalvan Dunstmantel. Die letzte bekannte Adresse ist die Schule in Mondbruch. Liebe Güte, das nenne ich veraltet!\n\nWürdet Ihr mir einen Gefallen tun? Falls Ihr zufällig nach Mondbruch kommt, dann lasst es mich wissen, wenn Ihr an neue Informationen über diese Person geraten solltet. Ich habe meine Unterlagen gern auf dem neuesten Stand.", sourceObjective = "Begebt Euch zur Schule in Mondbruch und bringt Amtmann Daltry alle neuen Informationen über Stalvan Dunstmantel.", completion = "Quietschend öffnet sich die alte Schließkiste...", sourceObjectiveStatus = "unverified-source-field" }
quests[68] = { id = 68, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "In der alten Schließkiste findet Ihr einen verstaubten, nie abgeschickten Brief.", sourceObjective = "Bringt Amtmann Daltry den verstaubten, nie abgeschickten Brief.", progress = "Ah, ich erinnere mich an Euch. Ihr hattet Euch doch nach diesem Stalvan erkundigt. Habt Ihr gefunden, wonach Ihr gesucht hattet?", completion = "Interessant. Also hat sich der Bursche doch einige Zeit lang in Moonbrook aufgehalten. Es ist etwas seltsam, dass der Brief nie zugestellt wurde. Nun, wie dem auch sei, ich werde das Verzeichnis aktualisieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[69] = { id = 69, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Ach du liebes bisschen! Das ist mir beim ersten Mal ja glatt entgangen! Hier im Verzeichnis steht beim Eintrag für diesen Stalvan direkt unter der ersten Adresse noch eine weitere, die zum Teil durchgestrichen ist. Es scheint, als wäre er zum Gasthaus Zur Höhle des Löwen drüben in Goldhain unterwegs gewesen. Vielleicht solltet Ihr dort nachfragen, {name}.", sourceObjective = "Begebt Euch zum Gasthaus Zur Höhle des Löwen und fragt dort nach, ob jemand schon einmal den Namen Stalvan gehört hat.", completion = "Stalvan? Kommt mir irgendwie bekannt vor...", sourceObjectiveStatus = "unverified-source-field" }
quests[70] = { id = 70, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Den Namen Stalvan hab ich schon mal gehört... Ach, jetzt fällt's mir wieder ein.\n\nVor vielen Jahren betrat an einem stürmischen Abend ein Bote dieses Haus, der Unterkunft für die Nacht suchte. Es war noch nicht ganz Mitternacht, da kam der Mann schreiend die Treppe heruntergerannt. Er war bleich wie der Tod vor Angst. Nur mit seinem Nachtgewand bekleidet verschwand er im Regen.\n\nIn der Eile vergaß er seine Briefe in der Truhe oben und kam nie zurück, um sie abzuholen. Es ist ein Brief dabei von diesem Stalvan, den Ihr erwähntet, adressiert an den Kanaldistrikt in Sturmwind. Ihr dürft ihn gern haben.", sourceObjective = "Holt Stalvans niemals zugestellten Brief aus der Truhe und liefert ihn im Kanaldistrikt von Sturmwind ab.", progress = "Was habt'n Ihr da, hm? Lasst mich das mal sehen...", completion = "Ihr habt vielleicht Nerven, dass Ihr das hierher bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[71] = { id = 71, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung an Thomas", description = "Nun habt Ihr beide Medaillons. Bringt sie an die Brücke zu Wache Thomas, damit er erfährt, welches Schicksal seine beiden Kameraden erlitten haben.", sourceObjective = "Bringt die Medaillons von Rolf und Malakai zu Wache Thomas an die östliche Brücke von Elwynn.", progress = "Hallo, {name}. Habt Ihr herausgefunden, was aus Rolf und Malakai geworden ist?", completion = "Damit bestätigt Ihr meine Befürchtungen, {name}. Die Murlocs sind eine Bedrohung, die wir nicht länger ignorieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[72] = { id = 72, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Mein Vater war der Verwalter des Besitzes, lange bevor ich es wurde. Nach dem Massaker war er derjenige, der das Blut aufwischen und aufräumen musste. Aber das tut nichts zur Sache.\n\nDie letzten Gelder aus dem Flintridge-Fonds sind versiegt und jetzt müssen die letzten Stücke aus dem Familienbesitz versteigert werden. Daran sind nur diese Steuereintreiber schuld. Aber wenn Ihr wirklich dringend mehr erfahren wollt, dann dürft Ihr diesen Kram hier gern durchsehen. Wer weiß, was Ihr findet.", sourceObjective = "Durchsucht die verpackten Besitztümer nach Hinweisen.", completion = "Langsam schiebt Ihr den Deckel von der Kiste...", sourceObjectiveStatus = "unverified-source-field" }
quests[74] = { id = 74, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "In der Kiste findet Ihr verschiedene Dinge: muffige Erbstücke, ein Familienportrait, einige Jagdtrophäen und ein paar alte Bücher. Fast schon am Boden der Kiste findet Ihr unter einer Keramikvase eine zerrissene Tagebuchseite.", sourceObjective = "Die zerrissene Tagebuchseite, die Ihr gefunden habt, gibt Euch den nächsten Hinweis.", progress = "Was habt Ihr denn da? Ich kann es nicht sehen. Ich habe sehr schwache Augen. Gebt es mir bitte in die Hand.", completion = "Ich kann kaum lesen, was da steht, aber die Handschrift erinnert mich an etwas, das ich mal gesehen habe, bevor meine Sehkraft so nachgelassen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[75] = { id = 75, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Als ich hier eingezogen bin, stand oben schon eine Truhe mit Pergamenten darin. Kurz nach meinem Einzug habe ich sie mir einmal angesehen, aber bald darauf konnte ich nur noch verschwommen sehen und da hab ich's dann gelassen. \n\nTut einem alten, halb blinden Mann einen Gefallen und seht Euch selbst mal in der Kiste oben um, ob Ihr vielleicht etwas findet, das Euch bei Eurer Suche nach diesem Stalvan weiterhelfen kann. Ich bin mir ziemlich sicher, dass da eine verblasste Tagebuchseite dabei ist, die Euch interessieren müsste. Bringt sie mir und ich werde sehen, was ich tun kann, um Euch zu helfen.", sourceObjective = "Marschall Haggard möchte, dass Ihr in der Kiste oben nach der verblassten Tagebuchseite sucht.", progress = "Habt Ihr die Seite gefunden, von der ich sprach, {name}?", completion = "Da ist sie ja!", sourceObjectiveStatus = "unverified-source-field" }
quests[76] = { id = 76, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jaspismine", description = "Dank Euch wissen wir jetzt, dass Kobolde sich in der Tiefenschachtmine eingenistet haben. Jetzt brauchen wir noch einen Späher, der die weiter entfernte Jaspismine untersucht.\n\nErforscht die Jaspismine und bestätigt mir, ob sich dort tatsächlich Kobolde aufhalten. Die Mine erreicht Ihr, indem Ihr der Straße nach Osten folgt, bis Ihr zum Turm von Azora kommt. Wenn Ihr Euch am Turm nach Norden wendet, dann findet Ihr die Mine im Vorgebirge.", sourceObjective = "Erforscht die Jaspismine und kehrt dann nach Goldhain zu Marschall Dughan zurück, um ihm Bericht zu erstatten.", progress = "Seid gegrüßt, {name}. Was habt Ihr zu berichten? Habt Ihr die Jaspismine ausgekundschaftet?", completion = "Kobolde in der Jaspismine, sagt Ihr? Verflucht noch eins! Die Lage wird von Minute zu Minute schlimmer!\n\nVielen Dank für Euren Bericht, {name}. Aber ich wünschte mir, Ihr hättet bessere Nachrichten gebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[77] = { id = 77, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schwierige Situation", description = "Ich besitze Originalverpackungsmaterial für die Welle, die Dran Droffers will. Ich werde Euch dabei helfen, die Welle für Maltons ungehobelten Vater zu verpacken... für einen Unkostenbeitrag in Höhe zweier weiterer Flaschen besagter Welle. Sie befinden sich in Kisten, die Ihr in dem verlassenen Stützpunkt der Horde in der Nähe vom Lauerfels findet.\n\nDas heißt, dass es eine anstrengende Aufgabe wird. Ihr werdet bei den Ruinen stinkende Schleime und Schlamme vorfinden; angeblich werden sie von einer Art Oberschlamm geführt. Beschafft trotzdem die Welle und kehrt hierher zu mir zurück, um sie zu verpacken.", sourceObjective = "Holt 10 Flaschen Hinterländer Honigwein aus den Kisten, die sich rund um den verlassenen Stützpunkt der Horde am Lauerfels befinden.", progress = "Ich nehme an, Eure Ankunft in unserem Lager dient der Lieferung der Wellenflaschen, die wichtiger Bestandteil der anstehenden Aufgabe sind, nicht wahr?", completion = "Das habt Ihr hervorragend gemacht, {name}! Ich bin froh, dass Ihr genug Voraussicht gezeigt und das Bouquet der Welle nicht verletzt habt. Es gibt nichts Schlimmeres, als wenn das Bouquet der Welle unnötig erschüttert wird.\n\nEs dauert einen Moment, die Magie um diese wertvolle Fracht zu wirken. Eigentlich ist ja gar keine Magie im Spiel; ich habe einfach nur einige leere Verpackungen für Hinterland-Honigwelle. Unser kleiner Trick wird diese Flaschen in einen alkoholischen Schatz von hohem Alter verwandeln.\n\nNun denn - auf dass es großartiger Schnaps werde!", sourceObjectiveStatus = "unverified-source-field" }
quests[78] = { id = 78, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Ich kenne jemanden, der Euch vielleicht helfen könnte. Damals, als ich noch die Wachen von Sturmwind kommandierte, haben wir immer in der Taverne Zum roten Raben in Dunkelhain gesessen und etwas getrunken. Smitts, der Gastwirt dort, kannte sich mit den örtlichen Lehren ziemlich gut aus. Zeigt ihm diese Seite, mal sehen, was er dazu zu sagen hat.", sourceObjective = "Bringt die verblasste Tagebuchseite zu Schankwart Smitts nach Dunkelhain im Dämmerwald.", progress = "Marshal Haggard hat Euch geschickt? Warum habt Ihr das nicht gleich gesagt? \n\nAch ja, der gute alte Haggard. Der arme Kerl wird über kurz oder lang stockblind werden. Aber egal, zeigt mir mal, was Ihr da habt.", completion = "Beim Licht! Aber sicher erkenne ich die Handschrift.", sourceObjectiveStatus = "unverified-source-field" }
quests[79] = { id = 79, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Ich habe die Geschichten um diesen Stalvan jahrelang verfolgt. Als vor ein paar Jahren diese Adligen, die hier zu Besuch waren, ermordet wurden, hab ich Haggard bei seinen Nachforschungen begleitet. Ich habe damals diese schlammverschmierten Seiten gefunden, aber es ist uns nie gelungen, die Handschrift mit diesem Verrückten in den Wäldern in Verbindung zu bringen. Eure Spur der Beweise zeigt aber, dass er schuldig ist. Bringt dies sofort zu Kommandant Schwarzhaupt und sagt ihr, was Ihr entdeckt habt!", sourceObjective = "Bringt Kommandant Schwarzhaupt die schlammverschmierte Seite.", progress = "Nun, {class}, ich hoffe, das, was Ihr mir da bringt, taugt auch etwas. Zeigt es mir und erzählt mir, was es damit auf sich hat. Aber beeilt Euch ein bisschen, beim Licht! Denn die Verteidigung von Dunkelhain ist mein wichtigstes Anliegen; ich habe einfach nicht die Zeit, mich bei meinen Ermittlungen in Sackgassen zu stürzen!", completion = "Ihr habt Euch ja richtiggehend als Detektiv betätigt, und das als {class}. Respekt!", sourceObjectiveStatus = "unverified-source-field" }
quests[80] = { id = 80, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Ich beobachte diesen Widerling Stalvan jetzt schon eine ganze Weile. Aber wenn diese Seite tatsächlich von seiner Hand geschrieben wurde, dann beweist das seine Schuld ohne den letzten Zweifel.\n\nSo lange, wie Amtmann Daltry das Stadtverzeichnis jetzt schon verwaltet, ist er ein wahrer Experte darin geworden, Handschriften zu identifizieren. Zeigt ihm diese Seite und stellt fest, ob die Schrift dieselbe ist wie diejenige der Unterschrift im Verzeichnis.", sourceObjective = "Zeigt Amtmann Daltry die blutbefleckte Tagebuchseite.", progress = "Ihr seid ja schon wieder da, {name}! Was gibt es diesmal?", completion = "Aber ja! Die Handschrift auf dieser Seite ist tatsächlich dieselbe wie die der Unterschriften im Verzeichnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[81] = { id = 81, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weinlieferung", description = "Ich habe zusätzliche Vorsichtsmaßnahmen getroffen und nicht nur Drans verpackte Welle in dem Fass sicher untergebracht, sondern auch die zusätzlichen Wellenflaschen, die er klaut. Auch wenn ich nicht viel von Dran halte, so gibt es doch nichts Schlimmeres als ein durchgeschütteltes Wellenbouquet. Bitte, bitte, keine Ursache.\n\nBringt jetzt Euer Fass zu Dran Droffers in seinem Kramladen in Orgrimmar. Entbietet meine besten Grüße bitte auch Malton und lasst ihn wissen, dass uns sein Besuch eine große Ehre wäre, falls es ihn jemals nach einem feinen Getränk und noch feineren Trinkkumpanen gelüstet.", sourceObjective = "Liefert das Fass nach Orgrimmar an Dran Droffers.", progress = "Wenn Ihr nicht hier seid, um etwas zu kaufen, und auch nicht, um etwas abzuliefern, dann verschwendet Ihr meine Zeit! Es wäre für Euch besser, Ihr hättet diese Welle!", completion = "Tja, dann schauen wir mal, was in diesem Fass ist!\n\nJa, ja, sieht aus als wäre alles da. Hier ist Euer Unkostenbeitrag für das Paket, Ihr habt gute Arbeit geleistet. Ich werde das Fünffache der Unkosten herausholen, wenn ich das Zeug an die Taverne verkaufe! Har, har!\n\nDiese zusätzlichen Flaschen Hinterland-Honigwelle werde ich für eine besondere Gelegenheit aufbewahren. Ich werde am besten etwas davon mit Champagner vermischt trinken. Ich nenne das... Champelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[82] = { id = 82, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkundung des Giftigen Unterschlupfes", description = "Tja, diese Berichte über die Käfer... wir wissen, dass sie die Teiche trocken legen, die sich dort befanden, wo sich der Giftige Unterschlupf befindet. Was wir NICHT wissen, ist, na ja, alles andere.\n\nWir müssen als Erstes herausfinden, wer unser Feind ist! Begebt Euch bitte in den Giftigen Unterschlupf und besorgt ein paar Stücke dieser Tierwesen. Holt fünf von diesen Teilen von den dortigen Centipaar und bringt sie dem Alchemisten Stößelbruch zur Untersuchung. Wenn er sich damit beschäftigt, werden wir schon herausfinden, worum es sich handelt!", sourceObjective = "Bringt fünf Centipaarinsektenteile vom Giftigen Unterschlupf nach Gadgetzan zum Alchemisten Stößelbruch.", progress = "Ihr seid Unterfeldmesser {name}, nicht wahr? Macht schnell, denn wir befinden uns hier in einer schrecklichen Lage! Habt Ihr die Insektenteile, wie Fizzledowser gesagt hat?!", completion = "Gute Arbeit... ich werde jetzt mit der Analyse dieser Dinger beginnen! Eines kann ich Euch aber direkt sagen... es handelt sich hier um keine mir bekannte Insektenform. Es scheint fast so, als würden diese Käfer von einer fremden Macht kontrolliert oder so was.\n\nIhr müsst auf der Stelle mit Fizzledowser sprechen; anscheinend gibt es einen Notfall, bei dem er Eure Hilfe benötigt. Ich bin mir nicht sicher, aber ich glaube, es geht um weitere Käfer in der Tanariswüste!", sourceObjectiveStatus = "unverified-source-field" }
quests[83] = { id = 83, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rote Leinenwaren", description = "Die Mitglieder der Defias in Nordhain tragen Masken aus Sackleinen, die Masken der Defias in Elwynn dagegen sind aus gutem Leinen, aus dem ich Qualitätsleinenwaren herstellen kann.\n\nBringt mir rote Leinenkopftücher, dann stelle ich daraus etwas für Euch her.\n\nDie Mitglieder der Defias haben Lager, die sich über ganz Elwynn verteilen.", sourceObjective = "Bringt 6 rote Leinenkopftücher ins Holzfällerlager des Osttals zu Sara Roderwald.", progress = "Ich habe fast kein Leinen mehr, {name}. Bringt Ihr mir welches?", completion = "Ah ja, das sind schöne Kopftücher, obwohl der Stoff ein wenig rau ist...\n\nHier, bitte schön!", sourceObjectiveStatus = "unverified-source-field" }
quests[84] = { id = 84, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Billy", description = "Hier, bitte schön. Und wenn Ihr Billy die Pastete gebt, dann sagt ihm, ich hoffe, er erstickt daran!", sourceObjective = "Bringt die Schweinebauchpastete zu Billy Maclure in den Weinbergen der Maclures.", progress = "Aaah... Ich bin am Verhungern! Habt Ihr die Pastete für mich, {name}?", completion = "Mmmm, lecker! Diese Pastete ist perfekt!\n\nIch glaube, langsam kommt mein Gedächtnis wieder...", sourceObjectiveStatus = "unverified-source-field" }
quests[85] = { id = 85, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Halskette", description = "Ich habe meine Halskette verloren und ich glaube, dieser Tunichtgut Billy Maclure hat sie genommen! Normalerweise treibt er sich immer wie eine kleine Ratte in den Weinbergen der Maclures östlich von hier herum. \n\nBringt mir meine Halskette zurück, wenn Ihr das Herz einer alten Witwe erfreuen wollt.", sourceObjective = "Sprecht mit Billy Maclure.", completion = "Ihr habt was verloren? Also ich hab keine Kette genommen, denn ich bin kein Dieb!\n\nIch weiß vielleicht, wer's war, aber... <grins>... ich hab einfach zu viel Hunger, um drauf zu kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86] = { id = 86, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pastete für Billy", description = "Wenn ich 'ne Pastete kriegen würde, dann könnte ich Euch vielleicht sagen, wer die Kette hat. Ach, und wisst Ihr was? Diese alte Dame Bernice auf dem anderen Hof da macht ganz tolle Schweinebauchpasteten. \n\nWenn Ihr ihr ein paar Brocken Eberfleisch von den Ebern bringt, die immer um unsere Höfe herumstromern, und ihr sagt, dass es für einen guten Zweck ist, dann backt sie Euch vielleicht eine Pastete.", sourceObjective = "Bringt 4 Brocken Eberfleisch zu Tantchen Bernice Steinfeld auf den Hof der Steinfelds.", progress = "Ich halte es nicht für richtig, den frechen Jungen, der meine Kette überhaupt erst gestohlen hat, dafür auch noch zu füttern, aber wenn es sein muss, damit ich mein Eigentum wiederbekomme, dann soll es eben so sein.\n\nHabt Ihr das Eberfleisch?", completion = "Das Fleisch von wilden Ebern ist zwar zäh, aber wenn man es lange genug köcheln lässt, dann wird eine ganz vorzügliche Pastete daraus!", sourceObjectiveStatus = "unverified-source-field" }
quests[87] = { id = 87, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldzahn", description = "Ich hab in der Nähe von der Tiefenschachtmine gespielt und da hab ich, glaub ich, die Kette von der alten Dame fallen ge... äääh, gesehen. Fragt mich nicht, wie die dahin gekommen ist, ich war's nicht!\n\nNa egal, jedenfalls hab ich diesen großen Kobold gesehen, der hatte einen Goldzahn und der hat die Kette aufgehoben und ist in die Mine gerannt. Wenn Ihr diesen Kobold findet, dann findet Ihr auch die Halskette, ehrlich! Ich schwör's!", sourceObjective = "Bringt Berenices Halskette auf den Hof der Steinfelds zu Tantchen Berenice Steinfeld.", progress = "Hallo, {name}. Habt Ihr meine Halskette gefunden?", completion = "Oh, Ihr habt sie tatsächlich gefunden! Danke, danke, mein Lieber!\n\nHier, nehmt dies. Es hat meinem Mann gehört und er sagte immer, dass es Glück brächte. Wenn er es doch nur auf seinem letzten Feldzug nicht vergessen hätte! *schnief*", sourceObjectiveStatus = "unverified-source-field" }
quests[88] = { id = 88, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prinzessin muss sterben!", description = "Die Brackbrunns haben ein Schwein, eine Sau namens Prinzessin, die schon viele Preise gewonnen hat. Dass dieses Tier so riesig geworden ist, das kommt nur daher, dass es immer hier herübergeschlichen kommt und mein Gemüse frisst!\n\nUnd deswegen muss Prinzessin sterben, bevor sie wieder unsere Felder heimsucht! Bringt mir ihr Halsband zum Beweis, dass Ihr die Sau abgestochen habt, dann gebe ich Euch etwas, das Euch für Euren Aufwand entschädigt.\n\nIhr findet Prinzessin normalerweise bei Brackbrunns Kürbisbeet, noch hinter dem Hof der Maclures und von dort aus im Osten gesehen. Ich hoffe, Ihr erwischt die Sau, bevor sie wieder hungrig wird und hierher kommt!", sourceObjective = "Tötet Prinzessin, nehmt ihr Halsband an Euch und bringt es zu Mutter Steinfeld auf den Hof der Steinfelds.", progress = "Habt Ihr sie schon gesehen? Habt Ihr sie erwischt?", completion = "Welch ein Glück! Dieses Schwein war schon so groß, dass es bestimmt bald unsere gesamte Ernte gefressen hätte! Ich danke Euch, {name}.\n\nNun, könnt Ihr mit einem dieser Dinge hier etwas anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[89] = { id = 89, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Immerruhbrücke", description = "Während der letzten Invasion der Orcs waren wir gezwungen, unser Eisen einzuschmelzen, um Kugeln, Schwerter und Rüstungen herzustellen. Wir haben Sturmwind benachrichtigt, dass wir eine neue Lieferung Materialien benötigen. Aber eine Bande von Rotkammgnollen hat die Karawane überfallen und sich dann in die Hügel hinter Seenhain zurückgezogen.\n\nJetzt gehen uns langsam die Vorräte aus, die wir brauchen, um die Brücke wieder aufzubauen. Wenn Ihr mir 5 Eisenspitzen und 5 Eisennieten bringt, {name}, dann sollt Ihr dafür belohnt werden. \n\nUnd jetzt an die Arbeit!", sourceObjective = "Bringt 5 Eisenspitzen und 5 Eisennieten nach Seenhain zu Großknecht Oslow.", progress = "Diese Brücke wird sich nicht selber bauen! Also wo sind diese Eisenspitzen und Eisennieten?", completion = "Gute Arbeit, {name}. Dieses Material wird den Brückenbau ganz enorm beschleunigen. Die kleine Schönheit hier wird im Handumdrehen repariert sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[90] = { id = 90, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewürzter Wolfskebab", description = "Gewürzter Wolfskebab ist eine Spezialität des Hauses! Natürlich kann ich Euch welchen machen. Aber ich brauche erst die Zutaten dafür. Bringt mir 10 magere Wolfflanken sowie Würzkräuter aus Sturmwind. Hier im Wald streifen so viele Wölfe herum, da werdet Ihr kein Problem haben, an die Wolfflanken zu kommen, da bin ich mir sicher. Und für die Kräuter sucht ihr am besten Felicia Gump in ihrem Blumenladen im Kanaldistrikt von Sturmwind auf.", sourceObjective = "Beschafft Euch 10 magere Wolfflanken und Würzkräuter aus Sturmwind und kehrt dann zu Küchenchef Grual nach Dunkelhain zurück.", progress = "Habt Ihr die 10 mageren Wolfflanken schon zusammen? Und was ist mit den Kräutern von Felicia aus Stormwind?", completion = "Gut gemacht, {name}! Ich wünsche Euch guten Appetit bei dieser echten Spezialität, dem gewürzten Wolfskebab!", sourceObjectiveStatus = "unverified-source-field" }
quests[91] = { id = 91, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gesetz des Solomon", description = "Ein Feind Sturmwinds hat sich im östlichen Vorläufer des Rotkammgebirges niedergelassen. Dieser verderbte Schurke bedient sich des Übernatürlichen, um unsere Stadt und ihre Einwohner in Angst und Schrecken zu versetzen. Er betreibt sein übles Geschäft unter dem Namen Morganth.\n\nMorganth kontrolliert jetzt den Schattenfellklan. Die Gnolle tun alles, was er ihnen befiehlt. Wie es das Gesetz von Seenhain vorsieht, steht auf die Unterstützung eines im Königreich gesuchten Verbrechers die Todesstrafe.\n\nDiese abscheulichen Gnolle verdienen den Tod!\n\nGebt 10 Schattenfellanhänger bei mir ab, dann erhaltet Ihr eine Belohnung.", sourceObjective = "Bringt 10 Schattenfellanhänger ins Rathaus von Seenhain zu Büttel Conacher.", progress = "Gebt 10 Schattenfellanhänger bei mir ab, dann erhaltet Ihr eine Belohnung.", completion = "Das Gericht von Seenhain weiß Euren Einsatz für die Gerechtigkeit zu schätzen, {name}. Indem Ihr die Gesetze des Königreichs durchgesetzt habt, habt Ihr auch der Gerechtigkeit in diesem Land einen Sieg verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[92] = { id = 92, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotkammgulasch", description = "Ich würde liebend gern Rotkammgulasch für Euch kochen. Aber es gibt da ein kleines Problem. Erst kürzlich musste ich während des Orcaufstands eine ganze Brigade von Soldaten der Armee von Sturmwind verpflegen. Jetzt ist meine Vorratskammer leer. Aber wenn Ihr mir die Zutaten besorgt, dann mache ich das gern für Euch.\n\nBringt mir einfach 5 Stücke zähes Kondorfleisch, 5 große Geiferzahnschnauzen und 5 Portionen knuspriges Spinnenfleisch.", sourceObjective = "Küchenchefin Breanna aus Seenhain möchte 5 Stücke zähes Kondorfleisch, 5 große Geiferzahnschnauzen und 5 Portionen knuspriges Spinnenfleisch.", progress = "Ich brauche immer noch 5 Stücke zähes Kondorfleisch, 5 große Geiferzahnschnauzen und 5 Portionen knuspriges Spinnenfleisch.", completion = "Gut gemacht, {name}. Und so schöne Exemplare noch dazu! Dafür bekommt Ihr hier auch die köstliche Spezialität, die als Rotkammgulasch bekannt ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[93] = { id = 93, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwärzliche Krebsküchlein", description = "Ich verrate Euch ein kleines Geheimnis: Schwärzliche \"Krebs\"-Küchlein werden eigentlich aus Spinnenbeinen gemacht! Ich weiß, das ist irgendwie eklig, aber die Küchlein schmecken lecker, ein bisschen scharf und eignen sich ganz ausgezeichnet zum Knabbern. Wenn Ihr mir einige klebrige Spinnenbeine bringt, dann zaubere ich euch ein paar.\n\nIch habe gehört, dass sich Giftweberspinnen ausgezeichnet dafür eignen - sie haben ihr Nest im Norden, zwischen dem Vorgebirge und dem Fluss.", sourceObjective = "Beschafft 6 klebrige Spinnenbeine und bringt sie nach Dunkelhain zu Küchenchef Grual.", progress = "Seid gegrüßt, {name}. Habt Ihr die klebrigen Spinnenbeine schon zusammen?", completion = "Ah ja, da habt Ihr ja ein paar nette Beinchen eingesammelt! So, jetzt muss ich die nur noch mit meiner hochgeheimen Gewürzmischung würzen - wehe, Ihr schaut! - und sie dann noch ein bisschen in der Pfanne braten...\n\nDie schwärzlichen Krebsküchlein sind meine Spezialität, deswegen verrate ich das Rezept nicht. Aber hier habt Ihr das Rezept für ein Gericht, das fast genauso gut schmeckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[94] = { id = 94, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wachsames Auge", description = "Mein Widersacher Morganth ist ein böser Magier von großer Macht, der im Turm von Ilgalar im Rotkammgebirge lebt. Ich habe eine Methode entwickelt, mit der ich ihn ausspionieren kann: Mit dem Auge von Azora ist es mir möglich, ihn von weitem zu sehen.\n\nDoch um seine Gedanken zu erforschen... ja, dazu benötige ich noch weitere Hilfe.\n\nWenn Ihr gewillt seid, dies zu tun, dann bringt meine Glyphe von Azora zum Turm von Ilgalar. Legt sie auf die Löwenstatue in der Nähe des Turms.\n\nSobald dieses getan ist, wird die Macht von Azora mir Visionen von Morganths zukünftigen Plänen gewähren.", sourceObjective = "Bringt die Glyphe von Azora zur Löwenstatue in der Nähe des Turms von Ilgalar im Rotkammgebirge.", progress = "Die Löwenstatue steht schon seit Jahrzehnten hier und bewacht einsam und allein den berüchtigten Turm von Ilgalar.\n\nAm Sockel der Statue befindet sich eine Vertiefung, wo ein Edelstein oder eine Glyphe eingesetzt werden könnte...", completion = "Ihr legt die Glyphe von Azora auf den Stein. Auf magische Weise verbindet die Glyphe sich mit der Statue - und als dies geschehen ist, hört Ihr plötzlich Theocritus' Stimme aus ihr ertönen:\n\nSeid Euch meiner Dankbarkeit gewiss, {name}, mein junger Freund. Ihr habt jetzt die Möglichkeit, durch diese Glyphe mit mir zu sprechen - es ist gut möglich, dass ich in Zukunft weitere Aufgaben für Euch habe. Aber erst muss ich die Gedanken meines Widersachers studieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[95] = { id = 95, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Svens Rache", description = "Früher arbeitete ich auf einem der Höfe im Südosten... bis einmal in meiner Abwesenheit Dunkle Reiter vom Gebirgspass der Totenwinde herunterkamen, meinen Hof überfielen und meine Familie abschlachteten.\n\nAls ich zurückkehrte, sah ich eine schattenhafte Gestalt, die sich bei meiner Scheune herumtrieb und dort etwas vergrub. Sie floh, ehe ich sie erreichen konnte, und ich hatte keine Zeit, mich mit ihr aufzuhalten, da ich den Dunklen Reitern dicht auf den Fersen war. Und so habe ich nie entdeckt, was die Gestalt dort versteckte.\n\nWenn Ihr herausfinden könntet, was jene schattenhafte Gestalt dort vergrub, dann wäre ich Euch dankbar. Das Versteck befindet sich hinter dem alten Baumstumpf in der Nähe meiner Scheune.", sourceObjective = "Begebt Euch zu Svens Hof und findet heraus, was hinter dem alten Baumstumpf vergraben wurde.", completion = "Ihr seht einen Haufen eilig aufgeschütteter Erde: Es scheint, als habe jemand etwas verstecken wollen und nicht viel Zeit gehabt, um dies zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[96] = { id = 96, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Nehmt Splitter. Nehmt Splitter und gebt Leben.\n\nGebt Leben und versteht. Versteht, Wasser ist Leben... Verderbnis beendet Leben.\n\nIhr schützt und gebt Leben mit der Macht des Wassers.", sourceObjective = "Bringt den Splitter des Wassers zu Islen Wasserdeuter am Tidustritt im Brachland.", progress = "Ihr seid zurückgekehrt. Ausgezeichnet!\n\nWie war Eure Reise nach Silberwald? Wart Ihr lange unterwegs?\n\nEs ist schwer für mich, festzustellen, ob Ihr Erfolg hattet oder nicht, denn ein so großer Teil des Landes ist bereits verderbt. Der Gestank der Verderbnis legt sich über alles Gute, das Ihr dort getan haben mögt. Doch die kleinen Erfolge sind manchmal genauso wichtig wie die großen. Die Läuterung des Wassers war höchst bedeutsam für Euch, nein, für alle Schamanen.", completion = "Dies ist der Beweis, um den ich Euch gebeten hatte. Ihr habt Eure Sache gut gemacht, {name}.\n\nIch freue mich, dass ich die Erste bin, die Euch gratuliert, und dass ich Euch dies geben kann - Euer Wassertotem.\n\nVerwendet es klug - und viel Glück.\n\nBis zu Eurer nächsten Prüfung wird es noch eine Weile dauern, also lernt Eure Lektionen sorgfältig bis dahin. Reines Wasser kann nicht nur Verletzten das Leben zurückgeben, sondern hat auch andere vielfältige Wirkungen. Ich schlage vor, Ihr sucht einen Schamanenlehrer auf, wenn Ihr die Zeit dafür habt. Dort könnt Ihr vielleicht noch weitere Zauber lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[97] = { id = 97, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Kommandant Schwarzhaupt muss unverzüglich erfahren, dass die Handschriften identisch sind, {name}! Ihr Verdacht hat sich also bestätigt.", sourceObjective = "Berichtet Kommandant Schwarzhaupt die Neuigkeiten.", completion = "Ich wusste es! Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[98] = { id = 98, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Stalvan Dunstmantel hat ein Leben der Verworfenheit gelebt und unschuldige Opfer starben von seiner Hand. Zweifellos hat er noch zahllose andere Verbrechen begangen und nun wird Dunkelhain von diesem Wahnsinnigen bedroht. Das Licht allein weiß, welche schmutzigen Pläne er jetzt ausheckt. Deswegen brauche ich Eure Hilfe, {class}. Begebt Euch zu seiner Hütte ein kleines Stück nördlich der Stadt und schaltet Stalvan ein für alle Mal aus.\n\nSobald die Tat vollbracht ist, begebt Euch zu Madame Eva und zeigt Ihr den Ring seiner Familie. Schließlich war es ihre Vorahnung, die zu dieser entsetzlichen Entdeckung führte. Doch jetzt kann ganz Dunkelhain dank ihr wieder ruhiger schlafen.", sourceObjective = "Tötet Stalvan Dunstmantel und zeigt Madame Eva den Ring seiner Familie.", progress = "Ja, {name}?", completion = "Ich weiß es bereits, {name}: Stalvan ist tot. Ich spürte, wie eine Woge der Hoffnung durch den verseuchten Wald ging. Nun ist der Dämmerwald für alle Zeiten von Stalvans Blutdurst befreit. Meine Freude wird getrübt durch den Gedanken an all diejenigen, die diesem schrecklichen Monster zum Opfer gefallen sind. Doch wie dem auch sei. Ihr, {class}, seid mutig und geschickt und ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[99] = { id = 99, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arugals Torheit", description = "Je mehr ich über Arugals Magie erfahre, umso mehr wächst meine Verachtung für diesen jämmerlichen Narren. Bald werde ich meine Studien zu seiner so genannten 'Arznei' beendet haben.\n\nMein Wissen wird vollständig sein, sobald ich herausgefunden habe, welche Verzauberung die seltsamen Zustände in Lohenscheit verursacht. Tagsüber scheinen die Arbeiter dort ganz gewöhnliche Menschen zu sein. Doch sobald die Sonne untergeht, verwandeln sich die Dorfbewohner in Mondzornworgs.\n\nIch muss Energie aus den verzauberten Fesseln ziehen, die Arugal auf sie gewirkt hat. Bringt mir 6 verzauberte Lohenscheitfesseln, {name}.", sourceObjective = "Bringt Dalar Morgenweber 6 Lohenscheitfesseln zum Grabmal.", progress = "Habt Ihr die Pyrewood-Fesseln schon sichergestellt, {name}?", completion = "Euere Hartnäckigkeit ist lobenswert. Dank des Wissens, das zu beschaffen Ihr mir geholfen habt, wird Arugal untergehen und seine leichtsinnige Magie zunichte gemacht werden. Meinen Beifall, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[100] = { id = 100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Noch während die Zauberformel, die Ihr gesprochen habt, verhallt, zuckt ein Meer von Lichtern um Euch herum auf. Das Zischen der Wassertropfen, die mit den Flammen in Berührung kommen, lässt nach und Eure überreizten Sinne spüren, wie die verderbten Geister in Eurer Nähe vernichtet werden.", sourceObjective = "Sprecht mit der schwachen Wassermanifestation am nördlichen Gezeitenstrom im Silberwald.", completion = "Dank Euch. Dank den Schamanen.\n\nDie Verderbnis weicht, aber das Leben schwindet weiter. Es ist an den Schamanen, Leben zu schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[101] = { id = 101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Totem des Gegenschlages", description = "Nun, da übernatürliche Mächte den Wald durchziehen, besteht ganz zweifellos die Notwendigkeit, sich zu schützen, {name}. Leise flüstern mir die Winde von einer großen Gefahr, die auf Euch lauert und der Ihr Euch in nicht allzu ferner Zukunft gegenübersehen werdet.\n\nAuch <ein tapferer/eine tapfere:c> {class} wie Ihr sollte sich schützen. Falls Ihr dies wünscht, so bringt mir 10 Ghulfangzähne, 10 Skelettfinger und 5 Phiolen Spinnengift. Dann stelle ich Euch ein Totem des Gegenschlages her und belege es mit einem Zauber, durch den es all denjenigen schadet, die gegen Euch Gewalt anwenden wollen.", sourceObjective = "Bringt 10 Ghulfangzähne, 10 Skelettfinger und 5 Phiolen Spinnengift nach Dunkelhain zu Madame Eva.", progress = "Bringt 10 Ghulfangzähne, 10 Skelettfinger und 5 Phiolen Spinnengift nach Dunkelhain zu Madame Eva. Ich werde Euch ein Totem des Gegenschlages herstellen und es mit einem Zauber belegen, durch den es all denjenigen schadet, die gegen Euch Gewalt anwenden wollen.", completion = "Das war sehr klug von Euch, {name}. Dieses Totem des Gegenschlages wird Euch gegen das Böse beschützen, das in ganz Azeroth und darüber hinaus lauert. Wenn Ihr Euch bedroht fühlt, dann haltet dieses Totem hoch und fühlt Euch von seiner magischen Aura getröstet. Seid tapfer, edler {class}. Ihr werdet allen Mut brauchen, den Ihr aufbringen könnt, denn ich sehe viel Blutvergießen in Eurer Zukunft.", sourceObjectiveStatus = "unverified-source-field" }
quests[102] = { id = 102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Patrouille durch Westfall", description = "Sturmwind hat uns im Stich gelassen. Der üble Gestank der Verderbtheit weht über die Ebenen von Westfall. Dies war und ist mein Heimatland und ich werde die Bürger, die sich zum Bleiben entschlossen haben, nicht verlassen. Wir, die wir früher Bauern waren, werden Widerstand leisten.\n\nEure Aufgabe, so Ihr sie denn annehmt, wird es sein, im Grasland von Westfall auf Patrouille zu gehen. Spürt die widerwärtigen Gnolle auf, die augenscheinlich mit den Dieben aus den Todesminen zusammenarbeiten, und tötet sie. Bringt mir 8 Gnolltatzen und ich werde Euren Mut zu belohnen wissen.", sourceObjective = "Bringt 8 Gnolltatzen auf die Späherkuppe zu Hauptmann Danuvin.", progress = "Habt Ihr bereits 8 Tatzen dieser verräterischen Gnolle erlangt?", completion = "Gut gemacht, {name}. Wenn tapfere Abenteurer wie Ihr selbst weiter Seite an Seite mit der Volksmiliz kämpfen, ist es durchaus möglich, dass Westfall wieder zu der reichen Kornkammer werden könnte, die es einmal war. Bitte nehmt dies in Anerkennung Eurer unermüdlichen Anstrengungen entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[103] = { id = 103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewahrer der Flamme", description = "Die Nacht, in der die Familie des Leuchtturmwärters starb, war schrecklich. Hilflos musste ich mit ansehen, wie Trübauge der Alte den Angriff befehligte. Doch was geschehen ist, ist geschehen. Nun sorge ich mich vor allem um das Leben der Seeleute, die das große Meer besegeln und deren Schiffe den trügerischen Felsen vor der Küste gefährlich nahe kommen. Da hier niemand mehr lebt, der die Flamme bewacht, obliegt die Verantwortung nun mir.\n\nHelft mir dabei, die Fackel am Leuchten zu erhalten, und bringt mir 5 Fläschchen Öl von den Erntemonstern.", sourceObjective = "Bringt 5 Fläschchen Öl zu Kapitän Grausohn beim Leuchtturm von Westfall.", progress = "Ohne Öl wird die Flamme nicht lange brennen, {name}.", completion = "Ein Hoch auf Eure Tapferkeit, {class}. Die Felsen entlang der Küste von Westfall werden dank Eurer harten Arbeit wieder hell erleuchtet sein. Die Fackel wird viele Leben retten, solange sie weiterbrennt.\n\nAn eben diesem Strand starb ich einen sinnlosen Tod. Jetzt, nach meinem Tod, ist es meine Bürde, sicherzustellen, dass niemand anderes dasselbe Schicksal erleiden muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[104] = { id = 104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung an der Küste", description = "Als ich auf den Felsen mein Leben aushauchte, hatte ich keine Ahnung, was das Leben nach dem Tode für mich bereithalten würde. In jener Nacht war der Leuchtturm erloschen, weil Trübauge der Alte die Familie des Leuchtturmwärters vertrieben hatte. Die Familie kehrte zurück und zündete die Flamme wieder an, doch Trübauge brachte die willensschwächeren Murlocs dazu, den Leuchtturm noch einmal mit ihm zusammen anzugreifen. Beim zweiten Mal hatte die Familie nicht so viel Glück. Vor meinen Augen starben sie alle, ohne sich wehren zu können.\n\nTötet Trübauge den Alten, wenn Ihr ihn am Ufer seht, und bringt mir eine seiner Schuppen, dann werdet Ihr eine Belohnung erhalten.", sourceObjective = "Bringt Kapitän Grausohn am Leuchtturm von Westfall eine Schuppe von Trübauge dem Alten.", progress = "Habt Ihr der Bedrohung namens Old Murk-Eye schon den Garaus gemacht? Er ist gesehen worden, wie er an der Küste von Westfall umherstreifte.\n\nKehrt zu mir zurück, sobald das garstige Ungeheuer tot ist.", completion = "Also ist Murk-Eye, dieser garstige Heide, endlich tot. Gut gemacht, {name}. Durch Eure Hand ist ein Leben beendet worden, doch vielleicht wurden gerade durch diese Tat viele weitere Leben gerettet. So gefährlich das große Meer auch ist, diese Nacht wird es dank Eurer heldenhaften Tat ein wenig sicherer sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[105] = { id = 105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weh dir, Andorhal", description = "Endlich ist die Zeit gekommen Andorhal anzugreifen und den Lich, der die Stadt kontrolliert, zu vertreiben.\n\nDer Lich - Araj der Beschwörer - herrscht von innerhalb der Ruinen der Stadt aus. Er wird von zahlreichen Angehörigen der Geißel bewacht, die über die Überreste des Stadtzentrums wachen, auch sein Gefolge an Leibwächtern ist ausgezeichnet. Ihr werdet einige Verbündete brauchen, um auch nur einen Hauch von einer Chance zu haben, ihn stellen zu können.\n\nVernichtet Araj, {name}, und bringt mir einen Splitter seines Phylakteriums als Beweis!", sourceObjective = "Bringt den Splitter von Arajs Phylakterium zu Hochexekutor Derrington ins Bollwerk in den westlichen Pestländern.", progress = "Ihr habt Euren Auftrag erhalten, {name}. Habt Ihr einen Splitter vom Phylakterium des Lichs als Beweis, dass die Tat vollbracht ist?", completion = "Ihr habt es geschafft! Araj... der Lich ist endlich besiegt!\n\nIhr habt der Horde heute einen gewaltigen Dienst erwiesen, {name}. Eure Tapferkeit und Hartnäckigkeit sind ein Beispiel dafür, was es heißt, ein wahrer Held zu sein. Bitte - nehmt dies als ein Zeichen für alle, die Euch sehen, auf dass sie wissen, dass Ihr für die Horde einen unsterblichen Sieg errungen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[106] = { id = 106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Junge Liebende", description = "Oh, ein Fluch lastet auf mir! Mein Herz gehört Tommy Joe Steinfeld, aber unsere Familien sind aufs Ärgste miteinander verfeindet. Daher kann ich mich nicht mit ihm treffen, obwohl ich mich doch so sehr danach sehne, sein geliebtes Gesicht zu sehen!\n\nBitte nehmt diesen Brief und gebt ihn Tommy Joe. Normalerweise hält er sich am Fluss im Westen des Hofs der Steinfelds auf, das ist auch von hier aus genau westlich.", sourceObjective = "Gebt Tommy Joe SteinfeldMaybells Liebesbrief.", progress = "Was habt Ihr? Maybell ist der einzige Lichtstrahl in meinem trüben Leben. Schnell, lasst mich ihren Brief sehen!", completion = "Ach! Ich kann es nicht ertragen, dass wir getrennt sind. Ich muss sie unbedingt sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[107] = { id = 107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht an William", description = "Ich möchte wetten, William Pestle hat einen Trank, der unsere beiden Liebenden zusammenbringen kann.\n\nHier, bringt William diese Nachricht. Er wohnt im Gasthaus Zur Höhle des Löwen in Goldhain.", sourceObjective = "Bringt Oma Steinfelds Nachricht zu William Pestle.", progress = "Ihr habt da eine Nachricht von \"Oma\" Stonefield, hm? Ich habe Mildred schon seit Jahren nicht mehr gesehen! Ich frage mich, was so wichtig ist, dass sie mir schreibt...", completion = "Maybell und Tommy Joe, diese armen Kinder, haben mein ganzes Mitgefühl. Ich kann mich noch gut daran erinnern, wie ich mich einst fühlte, als ich selbst noch jung und verliebt war...\n\nEs muss doch etwas geben, das ich tun kann, um ihnen zu helfen! Lasst mich einen Moment nachdenken...", sourceObjectiveStatus = "unverified-source-field" }
quests[109] = { id = 109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Gryan Starkmantel", description = "Es scheint mir, {class}, als hättet Ihr schon etliche Kämpfe überstanden. Falls Ihr das noch nicht getan habt, solltet Ihr Euch bei Gryan Starkmantel melden. Er ist der Anführer der Volksmiliz, die es sich zur Aufgabe gemacht hat, das Ackerland von Westfall zu beschützen. Ich möchte wetten, er könnte Eure Hilfe gebrauchen. Normalerweise findet man ihn im Steinturm auf der Späherkuppe, ein kleines Stückchen von der Straße weg, mitten in Westfall.", sourceObjective = "Sprecht mit Gryan Starkmantel. Normalerweise findet man ihn im Steinturm auf der Späherkuppe, ein kleines Stückchen von der Straße weg, mitten in Westfall.", completion = "Ah, mein Freund hat Euch also zu mir geschickt? Wie nett. \n\nNun, das Königshaus von Stormwind hat unsere Sache aufgegeben. Jetzt ist es an der Volksmiliz, das Land von der Verderbnis zu befreien. Wenn Euch unsere Sache interessiert, so würde ich Eure Fertigkeit im Kampf gern im Namen der Freiheit einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[110] = { id = 110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insektenteil-Analyse", description = "Ich werde einige Zeit brauchen, um Kieselschliffs Feldmesserausrüstung durchzusehen... und seine persönlichen Angelegenheiten zu regeln. Mein Bauch sagt mir, dass dies nicht der letzte Verlust ist, den wir durch die Käfer hinnehmen müssen.\n\nGeht bitte zu Alchemist Stößelbruch, um zu sehen, ob er etwas mit den Insektenteilen anfangen konnte, die wir ihm geschickt haben. Wenn sie fertig sind, bringt sie mir.", sourceObjective = "Begebt Euch nach Gadgetzan zu Alchemist Stößelbruch und erkundigt Euch nach der Analyse der Insektenteile.", completion = "Ja, ich habe die Ergebnisse direkt vor mir. Sie sind... gelinde gesagt, beunruhigend.\n\nUnser Anfangsverdacht, dass die Käfer durch eine äußere Macht kontrolliert werden, war wohl richtig. Falls das zutrifft, dann haben wir es nicht nur mit einer sehr starken unbekannten Macht zu tun, sondern auch noch mit einer bösartigen. Diese Käfer wurden in absolut verheerende Wesen verwandelt. Ich habe so etwas noch nie gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[111] = { id = 111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Oma", description = "Bitte sprecht mit meiner Großmutter, {name}. Wenn irgendjemand einen Weg weiß, wie ich mit Maybell zusammen sein kann, dann ist sie das.\n\nIhr findet sie in unserem Haus, östlich von hier.", sourceObjective = "Sprecht mit Oma Steinfeld.", completion = "Solange die Feindschaft zwischen unseren Familien besteht, sehe ich keine gemeinsame Zukunft für Tommy Joe und Maybell... Aber vielleicht können wir sie ja wenigstens für kurze Zeit zusammenbringen.\n\nHmm, was kann man da machen...", sourceObjectiveStatus = "unverified-source-field" }
quests[112] = { id = 112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach dem Tang", description = "Ich könnte einen Unsichtbarkeitsschnaps für Maybell brauen, damit sie sich aus den Weinbergen der Maclures fortstehlen und Tommy Joe sehen kann. Aber um den Schnaps herzustellen, brauche ich etwas Kristalltang.\n\nDieser Tang wächst zwar normalerweise im Meer, aber manchmal wird er auch von den Murlocs gesammelt. Geht und schaut, ob die Murlocs am Kristallsee welchen haben. Der Kristallsee liegt ein kleines Stück östlich von Goldhain.", sourceObjective = "Bringt 4 Kristalltangwedel nach Goldhain zu William Pestle.", progress = "Habt Ihr den Kristalltang? Ich bin mir sicher, Maybell kann es kaum erwarten, zu ihrem Verehrer zu kommen.", completion = "Ihr habt den Tang bekommen. Ausgezeichnet! Wartet noch einen kleinen Moment, während ich den Trank braue...", sourceObjectiveStatus = "unverified-source-field" }
quests[113] = { id = 113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insektenteil-Analyse", description = "Der Leitende Feldmesser Rutenwünschels muss diesen Bericht sofort sehen. Eigentlich muss jeder, der lesen kann, diesen Bericht sehen. Wir stehen einer großen und ernsten Bedrohung gegenüber, die nicht nur Tanaris und Gadgetzan, sondern das ganze südliche Kalimdor betrifft, wenn wir nichts unternehmen. Möglicherweise ist sogar ganz Azeroth gefährdet. Dieses Ding macht nicht den Eindruck, als würde es das Interesse verlieren.\n\nLasst Rutenwünschels ein Duplikat des Berichts anfertigen, den Ihr dann an Eure Verbündeten verteilen könnt. Jeder muss von dieser Bedrohung erfahren!", sourceObjective = "Bringt den Bericht nach Gadgetzan zum Leitenden Feldmesser Rutenwünschels. Lasst Euch von ihm eine Kopie des Berichts geben, wie Alchemist Stößelbruch gefordert hat.", progress = "Na, Unterfeldmesser {name}, hat der alte Pestlezugg diesen Bericht schon fertig?", completion = "Vielen Dank für die Überbringung des Berichts, Unterfeldmesser {name}, hier ist Eure Bezahlung für den gewissenhaften Dienst an der Gadgetzan Water Company.\n\nIch bin zwar normalerweise nicht begeistert von dem Gedanken, unsere wertvollen Informationen einfach so an diejenigen weiterzugeben, die anderenfalls gutes Geld dafür bezahlen würden, aber ich kenne Pestlezugg jetzt schon etliche Jahre. Wenn er empfiehlt, jeden darüber zu informieren, dann soll es so sein. Gebt mir einen Augenblick und ich werde Euch eine Kopie erstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[114] = { id = 114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flucht", description = "Bringt der jungen Maybell diesen Unsichtbarkeitsschnaps. Seine Wirkung sollte so lange anhalten, dass sie Tommy Joe besuchen kann.", sourceObjective = "Bringt Maybell Maclure den Unsichtbarkeitsschnaps.", progress = "Habt Ihr Tommy Lee meinen Brief überbracht? Was hat er gesagt?", completion = "Ach du liebe Zeit! Ich fühle mich schuldig, weil ich meine Familie täuschen muss, aber meine Gefühle für Tommy Joe sind einfach zu stark. Ich kann sie nicht ignorieren.\n\nIch danke Euch, {name}. Ich werde den Schnaps trinken, sobald ich eine Möglichkeit dazu habe, und mich zu meinem Liebsten schleichen.\n\nUnd Ihr... bitte nehmt dies.", sourceObjectiveStatus = "unverified-source-field" }
quests[115] = { id = 115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenmagie", description = "Von den Orcs des Schwarzfelsklans wurden zur Unterstützung ihrer Angriffe auf das Rotkammgebirge Schattenzauberer rekrutiert, die von einer dunklen Macht erfüllte Vorrichtungen mit sich führten - Mitternachtskugeln. Diese Kugeln haben den Verteidigern vom Rotkammgebirge schwere Verluste zugefügt und es ist von äußerster Wichtigkeit, dass wir diese dämonbesudelten Gegenstände aus dem Konflikt entfernen.\n\nDurchsucht erschlagene Schattenzauberer des Schwarzfels nach Mitternachtskugeln und bringt sie mir. Ich werde die Kugeln dann vernichten lassen, denn ohne sie wäre die Welt ein wesentlich besserer Ort.", sourceObjective = "Bringt 3 Mitternachtskugeln nach Seenhain zu Marschall Marris.", progress = "Wie verläuft Euer Kampf gegen die Schattenzauberer? Habt Ihr die Mitternachtskugeln gefunden?", completion = "Ich danke Euch, {name}. Ich werde diese Kugeln umgehend ihrer Beseitigung zuführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[116] = { id = 116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trockene Zeiten", description = "Mir werden hier gerade die Vorräte knapp, {name}. Alle Flaschen sind fast leer, und die letzte Schnapslieferung hätte schon längst hier eintreffen sollen. Die Orcinvasion ist einfach die Hölle.\n\nVielleicht könnt Ihr Euch ja für mich an die Arbeit machen?\n\nIhr müsst für mich bei Schnapsbart Donnerbräu in den Hügeln von Westfall ein Fässchen Donnerbräu Lagerbier besorgen, ebenso ein Fässlein Merlot aus Sturmwind, eine Flasche Fusel aus Dunkelhain und einen Schlauch mit süßem Rum aus Goldhain. Bringt mir all diese Dinge, dann werde ich dafür sorgen, dass Ihr belohnt werdet.", sourceObjective = "Barkeeper Daniels aus Seenhain braucht ein Fässchen Donnerbräu Lagerbier, ein Fässlein Merlot, eine Flasche Fusel und einen Schlauch mit süßem Rum.", progress = "Ihr müsst für mich bei Grimbooze Donnerbräu in den Westfall-Hügeln ein Fässchen Donnerbräu Lagerbier besorgen, ebenso ein Fässlein Merlot aus Stormwind, eine Flasche Fusel aus Dunkelhain und einen Schlauch süßen Rum aus Goldhain. Bringt mir all diese Dinge, dann werde ich dafür sorgen, dass Ihr belohnt werdet.", completion = "Sehr gute Arbeit, {name}! Ich weiß sehr wohl, welch weite Wege Ihr zurücklegen musstet, um diese beeindruckende Batterie an geistigen Getränken zu beschaffen. Aber meine Kunden haben endlich wieder Grund zur Zufriedenheit. \n\nMeine Frau ist eine ausgezeichnete Näherin. Bitte nehmt als Dank für Eure Dienste diesen von ihr gefertigten Umhang an.", sourceObjectiveStatus = "unverified-source-field" }
quests[117] = { id = 117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerbräu", description = "Ihr müsst eilen, <mein Freund/Madame>, sollt nicht ruhen, noch rasten\nDenn für unser Lagerbier lohnt sich's zu hasten\nEs schmeckt allen Männern, es schmeckt allen Frauen\nDoch ich brauche noch Hopfen, um das Bier zu brauen.", sourceObjective = "Bringt Schnapsbart Donnerbräu 5 Hopfen, damit er sein besonderes Bier brauen kann.", progress = "Ihr müsst Euch jetzt eilen, sollt nicht ruhen, noch rasten, \ndenn für unser Lagerbier lohnt sich's zu hasten.\nEs schmeckt allen Männern, es schmeckt allen Frauen, \ndoch ich brauche noch Hopfen, um das Bier zu brauen.", completion = "Malz und Hefe, Gerste und Hopfen \nUnd unser Bier wird zum edelsten Tropfen. \nIhr braucht nicht zu bitten, ich geb Euch das Gebräu: \nHier habt Ihr Lagerbier vom alten Donnerbräu!", sourceObjectiveStatus = "unverified-source-field" }
quests[118] = { id = 118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis für Hufeisen", description = "Ich habe so viel Eisen dafür verwenden müssen, die Wachen von Sturmwind auszurüsten, dass ich nicht mehr genug Eisen übrig habe, um die Pferde im Stall zu beschlagen!\n\nBringt diese Nachricht zu Schmied Argus nach Goldhain. Darin erkläre ich ihm mein Problem und bitte ihn um eine Lieferung Hufeisen.", sourceObjective = "Bringt Verners Nachricht zu Schmied Argus nach Goldhain im Wald von Elwynn.", progress = "Wie meint Ihr? Verner hat Euch geschickt, sagt Ihr? Na, dann gebt mir seine Nachricht. Und SPRECHT LAUTER!", completion = "Hehe, der alte Verner braucht also ein paar Hufeisen, wie?", sourceObjectiveStatus = "unverified-source-field" }
quests[119] = { id = 119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Verner", description = "Gut, er soll seine 50 Hufeisen haben.\n\nHier sind sie, schön in eine Kiste verpackt und bereit zum Abmarsch. Sagt Verner, dass es ein Vergnügen war, mit ihm Geschäfte zu machen, und sagt ihm, dass er unbedingt die Nachricht lesen soll, die ich ihm an die Kiste geheftet habe!", sourceObjective = "Kehrt zu Verner Gutmark nach Seenhain im Rotkammgebirge zurück. Gebt ihm die Kiste mit Hufeisen.", progress = "Oh, gut, Ihr seid zurück! Habt Ihr die Hufeisen bekommen?", completion = "Vielen Dank, das hilft mir wirklich weiter.\n\nAber was haben wir denn da? Der Kiste liegt eine Nachricht bei, die hat wohl Argus mitgeschickt... WAS? Argus will, dass ich ihn BEZAHLE? Pah!\n\nNa gut, jedenfalls danke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[120] = { id = 120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaft nach Sturmwind", description = "Wir leben in schwierigen Zeiten, {class}. Unsere Ortschaft ist einer ständigen Belagerung ausgesetzt. Wenn wir keine Verstärkung bekommen, ist unsere Niederlage so gut wie besiegelt. Die Botschaft, die ich Euch nun anvertrauen werde, ist von äußerster Wichtigkeit. Bringt diesen Bericht unverzüglich zu General Marcus Jonathan nach Sturmwind. Sobald Ihr die Nachricht abgeliefert habt, kehrt umgehend zu mir zurück und überbringt mir alle Neuigkeiten, ganz gleich, ob gut oder schlecht. \n\nDoch nun eilt!", sourceObjective = "Magistrat Solomon hat Euch einen Bericht übergeben, der bei General Marcus Jonathan in Sturmwind abgeliefert werden muss. Der Richter möchte, dass Ihr zu ihm zurückkehrt, sobald Ihr die Nachricht zugestellt habt.", progress = "Was bringt Ihr mir da?", completion = "Rührt Euch, {class}.\n\nMagistrat Solomon ist ein guter Anführer, und seine Worte haben großes Gewicht für mich. Ich werde um eine Audienz beim König ersuchen und ihm die Lage verdeutlichen. Versichert dem guten Richter, dass er sich der Unterstützung der Armee von Stormwind gewiss sein kann. Ich werde Verstärkung entsenden, sobald Seine Majestät den Befehl dazu gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[121] = { id = 121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaft nach Sturmwind", description = "Während ich auf Antwort vom König warte, möchte ich, dass Ihr diesen Brief zu Magistrat Solomon bringt. \n\nWeggetreten, {class}!", sourceObjective = "Bringt General Marcus Jonathans Antwortschreiben nach Seenhain zu Magistrat Solomon.", progress = "Sendet der General Nachricht? Ist Verstärkung unterwegs?", completion = "Ich danke Euch für die Zeit, die Ihr aufgewendet habt, {class}. Für Eure Dienste an Seenhain und Stormwind belohne ich Euch mit diesen Münzen.\n\nWenn Ihr mich jetzt entschuldigen wollt, diese Depesche stellt mich vor ein gewisses Rätsel. Irgendetwas stimmt in unserem Königreich nicht. Ich fürchte, dies ist erst der Anfang des Kampfes, nicht dessen Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[122] = { id = 122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauchschuppen", description = "Ich brauche einige Bauchschuppen von schwarzen Großdrachenwelpen, damit ich die Hufeisen bezahlen kann, die Argus mir aus Goldhain geschickt hat. Wenn Ihr mir 6 solcher Schuppen besorgt, dann kann ich mit einem Teil davon Argus bezahlen - und habe dann immer noch einen Rest übrig, aus dem ich etwas für Euch herstellen kann.\n\nSchwarze Großdrachenwelpen fliegen häufig über das Gebiet südlich von Seenhain, aber sie wandern auch gern herum. Haltet einfach die Augen offen und jagt sie, wenn Ihr sie seht.", sourceObjective = "Sammelt 6 Welpenbauchschuppen von schwarzen Großdrachenwelpen ein und bringt sie ins Rotkammgebirge zu Verner Gutmark.", progress = "Ich weiß, dass dieser Gierhals Argus jemanden schicken wird, um die Schuppen für ihn einzutreiben, wenn ich sie ihm nicht bald von mir aus gebe. Habt Ihr die Schuppen schon gefunden?", completion = "Danke! So werde ich meine Schulden Argus gegenüber los.", sourceObjectiveStatus = "unverified-source-field" }
quests[123] = { id = 123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sammler", description = "Bei der Notiz handelt es sich um eine Tabelle mit Daten und Zeiten, zu denen jemand, der in der Notiz nur als \"der Sammler\" bezeichnet wird, je eine Lieferung Gold aus den Minen des Waldes von Elwynn erhalten soll.\n\nAus dem Plan geht hervor, dass sich der Sammler anscheinend in der Nähe von Brackbrunns Kürbisbeet in Ost-Elwynn aufhält.\n\nDas klingt, als sei es wichtig. Ihr solltet Marschall Dughan in Goldhain davon berichten.", sourceObjective = "Begebt Euch zu Marschall Dughan nach Goldhain und gebt ihm den Zeitplan des Sammlers.", progress = "Was?!? Schon seit Monaten arbeiten unsere Leute nicht mehr in den Minen von Elwynn!\n\nZeigt mir mal diese Notiz, die Ihr da habt...", completion = "Hm... Ich habe von diesem \"Sammler\" schon gehört, aber ich weiß nicht, für wen er arbeitet. Vielen Dank für diesen Zeitplan. Er wird uns dabei helfen, das Rätsel zu lösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[124] = { id = 124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bellen der Gnolle", description = "Als ob Orcangriffe nicht genug wären! Jetzt schleichen auch noch Gnollschläger und Gnollmystiker auf dem Hügelkamm nördlich von meinem Stall herum und fallen meine Pferde an, wenn diese sich auch nur etwas zu weit vom Stall entfernen...\n\nWenn Ihr diese Gnolle beseitigen könntet, wären meine Pferde und ich Euch sehr dankbar.", sourceObjective = "Tötet 10 Schläger der Rotkammgnolle und 8 Mystiker der Rotkammgnolle und kehrt anschließend zu Verner Gutmark zurück.", progress = "Meine Pferde sind immer noch nervös und nachts höre ich immer noch dieses verfluchte Wolfsgeheul. Bitte tut etwas gegen diese Gnolle, {name}!", completion = "Danke für all Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[125] = { id = 125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorenen Werkzeuge", description = "Ich könnte hier wirklich etwas Hilfe gebrauchen, {name}. Jetzt, wo die Stadt belagert wird, bekommen wir hier nur schwer Nachschub. Meine Werkzeuge sollten mit dem Karren von Goldhain aus angeliefert werden, aber die Brücke wurde in die Luft gejagt. Also legten wir die Werkzeuge in ein Boot, aber die Orcs beschossen es mit einem Katapult und trafen auch noch. Na, und bei meinem Pech ist mein Werkzeugkasten natürlich geradewegs bis auf den Grund des Sees gesunken.\n\nWenn Ihr mir meinen Werkzeugkasten wiederbeschafft, {name}, dann soll es Euer Schaden nicht sein.", sourceObjective = "Großknecht Oslow aus Seenhain möchte, dass Ihr seinen Werkzeugkasten vom Grunde des Immerruhsees heraufholt.", progress = "Habt Ihr meine Werkzeuge finden können?", completion = "Das habt Ihr gut gemacht, {name}! Ich hätte nie gedacht, dass ich diese Werkzeuge jemals wiedersehen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[126] = { id = 126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheul in den Hügeln", description = "Die Gnolle sind immer noch da draußen, {name}. Ich kann sie bellen hören, wenn sie in den Hügeln oberhalb von Seenhain jagen. Und das Geheul eines Gnolls ist lauter als das aller anderen - das von Jauler, ihrem Anführer.\n\nTötet Jauler und vertreibt sein Rudel in alle vier Winde! Bringt mir seine Tatze zum Beweis.\n\nAber seid vorsichtig! Dieser Gnoll ist nicht umsonst der Anführer seines Rudels. Er ist kein einfacher Köter...", sourceObjective = "Bringt Jaulers Tatze nach Seenhain zu Verner Gutmark.", progress = "Jauler ist gefährlich, {name}. Wenn Ihr Euch ihm noch nicht gewachsen fühlt, dann verstehe ich das.", completion = "Nochmals danke für Eure Hilfe. Die Armee von Stormwind ist so sehr mit den Orcs beschäftigt, dass sie nicht genügend Truppen hat, um das Rotkammgebirge vor kleineren Bedrohungen wie den Gnollen zu beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[127] = { id = 127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischhandel", description = "Der Immerruhsee ist für seinen gefleckten Sonnenfisch berühmt. Die Nachfrage nach diesen Fischen ist enorm hoch - und ich habe bald keine mehr vorrätig!\n\nBringt mir 10 Stück, dann werden wir uns schon handelseinig werden. Und wenn Ihr nicht selbst angeln möchtet oder könnt - na ja, vielleicht bekommt Ihr die Fische ja von den Murlocs!", sourceObjective = "Bringt 10 gefleckte Sonnenfische nach Seenhain zu Dockmeister Baren.", progress = "Ihr habt wohl'n paar Sonnenfische für mich, hm?", completion = "Schön, mit Euch Geschäfte zu machen, Kumpel!", sourceObjectiveStatus = "unverified-source-field" }
quests[128] = { id = 128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld auf den Schwarzfelsklan", description = "Der Schwarzfelsklan muss vernichtet werden. Der Feind ist in unser Land eingedrungen. Diese Berge unterliegen der Oberhoheit des Königs von Sturmwind. Aus bestimmten Quellen haben wir erfahren können, dass die Anführer jeder Einheit im Klan \"Helden\" genannt werden. Ihr findet sie in ihrem Lager im Norden, ein kleines Stück westlich von der Straße, die in die brennende Steppe führt.\n\nMagistrat Solomon möchte diese garstigen Bestien tot sehen. Erschlagt 15 Helden des Schwarzfels und kehrt zu mir zurück.", sourceObjective = "Tötet 15 Helden des Schwarzfels, dann erhaltet Ihr von Wache Howe aus Seenhain eine Belohnung.", completion = "Wie ich sehe, habt Ihr tapfer gegen den Blackrockklan gekämpft, {class}. Ihr habt unserem Ort wahrlich einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[129] = { id = 129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein geschenktes Mittagessen", description = "Könntet Ihr mir einen Gefallen tun? Ich habe für Wache Parker ein Mittagessen gemacht, aber er ist gerade auf Patrouille unterwegs... Er ist groß und stark und noch dazu eine Wache von Sturmwind, also kann er auf sich selbst aufpassen, aber ich bin nur eine kleine Stadtbewohnerin - für mich ist das da draußen viel zu gefährlich!\n\nWenn Ihr ihm also sein Mittagessen bringt und anschließend wieder herkommt, dann bekommt Ihr auch ein Mittagessen von mir - umsonst! Parker patrouilliert die Straße, die in den Dämmerwald führt.", sourceObjective = "Bringt Parkers Mittagessen zu Wache Parker. Er ist auf der Straße nach Dunkelhain auf Patrouille.", progress = "So, Darcy hat mir ein Mittagessen geschickt, wie? Sie hat wirklich ein gutes Herz. Na, dann mal her damit!", completion = "Vielen Dank, das Essen hatte ich jetzt wirklich nötig. Seenhain gegen die Orcs und Gnolle zu beschützen strengt ganz schön an.", sourceObjectiveStatus = "unverified-source-field" }
quests[130] = { id = 130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besuch im Kräuterladen", description = "Könnt Ihr Darcy ein paar Blumen von mir bringen, wenn Ihr wieder zu ihr geht? Die Blumen bekommt Ihr im Kräuterladen von Seenhain, am westlichen Ende des Ortes.\n\nAber wenn Ihr die Blumen holt, dann sagt Martie, der Kräuterkundigen, nicht, für wen sie bestimmt sind oder wer Euch beauftragt hat, ja?", sourceObjective = "Sprecht mit der Kräuterkundigen des Rotkammgebirges, Martie Jainrose.", completion = "Ihr braucht einen Blumenstrauß? Ihr seid noch nicht sehr lange in der Stadt - habt Ihr Euch etwa schon eine Liebste angelacht?\n\nIch weiß, es gehört sich nicht, so neugierig zu sein, aber ich finde es einfach schön, dass Liebe in der Luft liegt... vor allem in gefährlichen Zeiten wie diesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[131] = { id = 131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narzissen für eine Dame", description = "Hier habt Ihr Euren Blumenstrauß. Ich habe Narzissen für Euch ausgesucht. Narzissen sind meine Lieblingsblumen.", sourceObjective = "Gebt Darcy den Narzissenstrauß.", progress = "Da seid Ihr ja wieder, {name}. Hat Parker das Mittagessen geschmeckt, das ich ihm geschickt habe?", completion = "Die Blumen sind wunderschön! Ich kann es kaum erwarten, sie ins Wasser zu stellen.\n\nAber wartet mal... das sind ja die Lieblingsblumen von Martie! Parker hat Euch doch wohl nicht etwa zu diesem missgünstigen Drachen geschickt, um die Blumen zu besorgen! Ihr habt ihr doch hoffentlich nicht gesagt, für wen die waren, oder? Falls doch, dann würde es mich nicht wundern, falls Martie die Blumen irgendwie vergiftet hätte.\n\nAber da könnt Ihr ja nichts dafür. Vielen Dank - und hier habt Ihr auch Euer Essen.", sourceObjectiveStatus = "unverified-source-field" }
quests[132] = { id = 132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bruderschaft der Defias", description = "Was ich Euch jetzt erzähle, könnte mich das Leben kosten. Die Bande der Defias plant irgendwas Großes. Das Letzte, was ich gehört habe, war, dass sie mit unterschiedlichen Gnollen, Kobolden und sogar Goblins zusammenarbeiten.\n\nBringt Starkmantel diese Nachricht. Darin steht alles, was ich zu dem Thema sagen kann.", sourceObjective = "Bringt Wileys Nachricht nach Westfall zu Gryan Starkmantel.", progress = "Schön, dass Ihr zurück seid, {name}. Was hatte Wiley zu seiner Verteidigung zu sagen?", completion = "Pah! Ich hätte den Halunken verfaulen lassen sollen, als ich die Chance dazu hatte. Aber diese Informationen sind von äußerster Wichtigkeit. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[133] = { id = 133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ghulbildnis", description = "Ich wohne so weit weg von der Stadt und dem Schutz, den sie bietet, dass es ein Wunder ist, dass die Ghule und die wandelnden Toten mich noch nicht aufgefressen haben! Tatsächlich hat erst gestern ein Rudel Knochenkauer gegen die Wände meines Hauses gehämmert.\n\nIch möchte ein Bildnis herstellen - eine Art \"Vogelscheuche\", nur für Ghule. Dafür brauche ich ein paar Ghulrippen. Die bekommt Ihr von Fleischfressern, Knochenkauern, Hirnfressern, Verfaulten und Seuchenverbreitern.\n\nWenn Ihr mir die Rippen beschafft, bezahle ich Euch in barer Münze.", sourceObjective = "Sammelt 7 Ghulrippen und bringt sie zu Calvinius in seiner Hütte.", progress = "Ich glaube, hinter dem Haus treibt sich ein Rudel Ghule herum - je schneller ich das Bildnis aufstelle, desto besser! Habt Ihr die Ghulrippen für mich?", completion = "Ah, danke! Die sind genau richtig für mein Vorhaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[134] = { id = 134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerdiebe", description = "Vor ein paar Wochen wurde ich von einer Bande Ogern angegriffen, als ich draußen Kräuter sammelte, ziemlich weit von meinem Haus entfernt. Ich lief davon und musste eine Kiste mit wertvollen Werkzeugen und Kräutern zurücklassen.\n\nNachdem sie mich vertrieben hatten, stolzierten die Oger zurück zum Ogerhort im südlichen Dämmerwald. Ich bin mir sicher, dass meine Kiste irgendwo in der Nähe des Hügels sein muss.\n\nBitte, {name}, beschafft mir diese Kiste wieder, denn sie fehlt mir sehr.", sourceObjective = "Bringt Calvinius' Kiste zu Calvinius.", progress = "Habt Ihr meine Kiste? Wenn ja, dann gebt sie mir schnell, ich bitte Euch!", completion = "Dank dem Toten- ähm, ich danke EUCH, {name}! Ihr habt Euch Eure Belohnung mehr als verdient.\n\nAha! Oh Glück! Glückliche Nächte können kommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[135] = { id = 135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bruderschaft der Defias", description = "Ich möchte zu gern wissen, was Wiley meinte, als er die Steinmetze erwähnte. Vielleicht ist ihm da nur etwas rausgerutscht. Könnten die Defias irgendwas mit den Steinmetzen zu tun haben? Nur ein Mann weiß das mit Sicherheit: Mathias Shaw, Kopf von SI:7. Zeigt ihm Wileys Nachricht und stellt fest, ob er noch etwas zu diesem immer verzwickter werdenden Rätsel beitragen kann. Falls Ihr Probleme habt, Shaw zu finden, seht in der Kaserne in der Altstadt nach.", sourceObjective = "Bringt Wileys Nachricht nach Sturmwind zu Mathias Shaw.", progress = "Was wollt Ihr von mir? Ich bin ein viel beschäftigter Mann...", completion = "Diese Angelegenheit ist vermutlich komplizierter, als Stoutmantle ahnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[136] = { id = 136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Sanders' versteckter Schatz", description = "Wenn Ihr das hier lesen tut, dann heißt das, dass der alte Käpt'n Sanders in den Fluten begraben is'. Also tut mein Schatz jetz' Euch gehör'n, Ihr braucht bloß den Hinweisen folgen. \n\nErst müsst Ihr ma' meine Schließkiste finden. Wahrscheinlich is' die jetz' da an der Westküste von Westfall in der Nähe von dem Schiffswrack schon halb im Sand verschwunden. 's gibt da an der Küste massig Schiffswracks, aber bloß einen rostigen Anker. Wenn Ihr den Anker finden tut, dann habt Ihr auch meine Schließkiste gefunden. Da müsst ihr reingucken, denn da steht der nächste Hinweis drin.", sourceObjective = "Findet Käpt'n Sanders Schließkiste und durchsucht sie, um den nächsten Hinweis zu erhalten.", completion = "Langsam und quietschend öffnet sich die Schließkiste. Erst scheint es, als bestünde ihr Inhalt allein aus Wasser und Sand. Aber halt! Ein kleiner Krebs huscht heraus, der einen Hinweis auf den Schatz in seinen Scheren trägt!", sourceObjectiveStatus = "unverified-source-field" }
quests[138] = { id = 138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Sanders' versteckter Schatz", description = "Der Hinweis auf den Schatz lautet folgendermaßen: Gut gemacht, Kumpel! Jetz' müsst Ihr Euch imma nach Ost'n halten. Östlich von der Straße die Steilhänge hoch. Schaut Euch nach so 'nem ollen verfallenen Kamin nahe bei der Straße um. Dort findet Ihr'n altes Fass mit Eurem nächsten Hinweis drin.", sourceObjective = "Findet das alte Fass in der Nähe des verfallenen Kamins und durchsucht es nach Eurem nächsten Hinweis.\n\nBereitgestellter Gegenstand:", completion = "Gut gemacht! Das war der nächste Schritt auf der Schatzsuche.", sourceObjectiveStatus = "unverified-source-field" }
quests[139] = { id = 139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Sanders' versteckter Schatz", description = "Als Ihr das Fass durchsucht, findet Ihr ein weiteres Stück Pergament. Darauf steht: Also, von dem Fass dort müsst Ihr Euch nach Norden halten tun. Un' dann geht Ihr immer der Nase nach schnurstracks geradeaus, bis Ihr den leeren Henkelkrug sehen tut, der da irgendwo bei so 'ner einzeln stehenden Windmühle oben auf dem Steilhang über dem Meer liegt. Wenn Ihr Euch bei dem Henkelkrug umguckt, dann findet Ihr vielleicht sogar, was Ihr sucht.", sourceObjective = "Durchsucht den leeren Henkelkrug neben der Windmühle nach dem nächsten Hinweis.\n\nBereitgestellter Gegenstand:", completion = "Ihr seid bei Eurer Schatzsuche auf dem richtigen Weg!", sourceObjectiveStatus = "unverified-source-field" }
quests[140] = { id = 140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Sanders' versteckter Schatz", description = "Und tatsächlich, ganz unten, fast am Boden des alten Henkelkruges findet sich der nächste Hinweis auf Sanders Schatz. An manchen Stellen ist die Tinte verwischt und das Papier riecht nach Whisky, aber zum Teil kann man den Text noch lesen: Jetz', wo Ihr mein'n alten Whiskykrug gefunden habt, habt Ihr den Schatz schon so gut wie in der Tasche. Von der Flasche aus müsst Ihr Euch einfach nach Westen halten und runter zum Strand geh'n. Und dann heißt es schwimmen! Schwimmt schnurstracks nach Westen, bis Ihr an der Insel seid, da wo meine Schatztruhe drauf is'!", sourceObjective = "Findet Käpt'n Sanders Truhe und öffnet sie. Darin befindet sich Eure Belohnung.\n\nBereitgestellter Gegenstand:", completion = "Die Scharniere der alten Truhe sind rostig, aber sie funktionieren noch. Ihr brecht die Truhe auf und nehmt die Beute heraus.\n\nHerzlichen Glückwunsch!", sourceObjectiveStatus = "unverified-source-field" }
quests[141] = { id = 141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bruderschaft der Defias", description = "Die Gilde der Steinmetze wurde von einem Mann namens Edwin van Cleef geführt. Van Cleef war dafür verantwortlich, dass Sturmwind wieder aufgebaut wurde, nachdem die Orcs es im Ersten Krieg dem Boden gleichgemacht hatten. Anscheinend waren van Cleef und seine Leute nicht zufrieden damit, wie der König sie behandelte, nachdem der Wiederaufbau vollendet war. Das könnte den einen oder anderen Sachverhalt erklären.\n\nIch habe Eurem Meister in Westfall einen ausführlicheren Bericht geschrieben. Bringt ihn sofort zu ihm!", sourceObjective = "Bringt Shaws Bericht nach Westfall zu Gryan Starkmantel.", progress = "Konnte Meister Shaw etwas Licht auf die Dinge werfen?", completion = "Edwin van Cleef... dieser Name ist mir wohl bekannt. Ein so talentierter und fleißiger Mann soll zu einem solchen Schurken geworden sein?... Der Gedanke erschreckt mich und ich brauche weitere Beweise, ehe ich das glaube.", sourceObjectiveStatus = "unverified-source-field" }
quests[142] = { id = 142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bruderschaft der Defias", description = "Wir müssen herausfinden, wo genau sich das Versteck der Defias befindet. {name}, meine Späher berichten mir, dass ein Bote der Defias auf der Straße zwischen Mondbruch, dem Goldküstensteinbruch und dem Jangoschacht gesehen worden ist. Ich möchte, dass Ihr ihn fangt. Wenn er Widerstand leistet, tötet ihn und bringt mir alles, was er bei sich trägt.", sourceObjective = "Spürt den Boten der Defias in Westfall auf und bringt die Nachricht, die er bei sich hat, zu Starkmantel.", progress = "Habt Ihr irgendetwas erfahren können, {name}? Habt Ihr den Boten gefunden?", completion = "Dies beweist allerdings eindeutig, dass van Cleef das Kommando hat. Jetzt müssen wir nur noch herausfinden, wo die Bande der Defias sich versteckt hält.\n\nWährend Ihr fort wart, gab es hier einen Glücksfall. Wir haben einen Dieb gefasst, der Saldeans Wagen stehlen wollte. Er hat versprochen, uns zu dem Versteck zu führen, wenn wir im Gegenzug sein Leben verschonen. Ich möchte, dass Ihr den Verräter schützt, damit er uns das Versteck zeigen kann. Kehrt zu mir zurück, sobald Ihr den Ort gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[143] = { id = 143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaft nach Westfall", description = "Irgendetwas stimmt mit der Armee von Sturmwind nicht. Sie hätte längst mit einem größeren Aufgebot hier sein müssen. Doch Zeit ist ein Luxus, den wir nicht haben. Ich werde nicht dabeistehen und tatenlos zusehen, wie die Bewohner von Seenhain ihr Leben geben. Nein. Ich muss versuchen, von anderer Stelle her Hilfe zu gewinnen. Ich habe gehört, dass sich in Westfall eine Volksmiliz gebildet hat.\n\nBringt dieses Hilfegesuch ihrem Anführer, Gryan Starkmantel. Vielleicht können Starkmantels Männer uns hier unterstützen, bis der König Verstärkung schickt.", sourceObjective = "Magistrat Solomon möchte, dass Ihr sein Hilfegesuch nach Westfall zu Gryan Starkmantel bringt.", progress = "Seid gegrüßt, {class}! Welcher Anlass führt Euch zur Volksmiliz?", completion = "Werter Bote, Ihr habt Eurem Meister wohl gedient.", sourceObjectiveStatus = "unverified-source-field" }
quests[144] = { id = 144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaft nach Westfall", description = "Es schmerzt mich, Magistrat Solomons Schreiben zu lesen. Offensichtlich hat er von dem Krieg, der hier in Westfall tobt, keine Ahnung. Sonst wäre er nicht so naiv, Hilfe von der Miliz zu erwarten. Wenn Sturmwind nicht auch uns im Stich gelassen hätte, dann hätte es keinen Grund gegeben, die Miliz ins Leben zu rufen.\n\nBringt Eurem Herrn im Rotkammgebirge diese Antwort, {class}. Und lasst ihn wissen, dass mir das Herz schwer wird, wenn ich an all die tapferen Leute denke, die ihr Leben verloren haben.", sourceObjective = "Kehrt mit Gryan Starkmantels Antwort zu Magistrat Solomon zurück.", progress = "Dürfen wir die Volksmiliz bald erwarten? Lassen Lord Stoutmantles Nachrichten Gutes erhoffen?", completion = "Ich muss schon sagen, dies klingt überhaupt nicht gut. Ich wusste nicht, dass die Lage, in der Stoutmantle sich befindet, der unseren hier in Seenhain nicht unähnlich ist. Was kann nur so wichtig sein, dass es die Armee von Stormwind davon abhält, dem Volk, das sie beschützen soll, zu Hilfe zu eilen? Aber ich sollte nicht laut grübeln.\n\nHier, Bote. Nehmt diese Münzen als Bezahlung für Eure Verdienste um die Stadt entgegen. Es wäre möglich, dass ich Eure Hilfe ein weiteres Mal benötige.", sourceObjectiveStatus = "unverified-source-field" }
quests[145] = { id = 145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaft nach Dunkelhain", description = "Ein weiteres Mal brauche ich Eure Hilfe. Ich habe an Lord Schwarzhaupt geschrieben und ihn gebeten, seine gut ausgebildete Nachtwache hierher zu schicken, damit diese bei der Verteidigung von Seenhain hilft. Es ist von ausnehmender Wichtigkeit, dass diese Nachricht ihn so bald wie möglich erreicht. Doch Ihr müsst äußerste Vorsicht walten lassen. Schwarzhaupt ist der Bürgermeister von Dunkelhain, und das liegt im Herzen des Dämmerwalds. Entfernt Euch nicht von der Straße.", sourceObjective = "Magistrat Solomon möchte, dass Ihr einen Brief zu Lord Schwarzhaupt nach Dunkelhain bringt.", progress = "Es scheint mir, als wäret Ihr weit gereist, {class}. Was ist Euer Begehr hier in Dunkelhain?", completion = "Ich danke Euch, dass Ihr die lange Reise hierher unternommen habt. Dies sind wirklich wichtige Informationen.", sourceObjectiveStatus = "unverified-source-field" }
quests[146] = { id = 146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaft nach Dunkelhain", description = "Wenn mir Magistrat Solomon nicht persönlich bekannt wäre, würde ich sagen, der Mann hat den Verstand verloren. Die Nachtwache nach Seenhain schicken, weil Sturmwind die Hilfe verweigert? Die Nachtwache wurde gegründet, weil Sturmwind uns verließ, als diese elende Magie langsam das Land überzog. Wenn ich meine Nachtwache jetzt fortschicke, dann würde diese Stadt vom Bösen überrannt werden, noch ehe die Wachen den Waldrand erreicht hätten.\n\nBringt Eurem Meister in Seenhain dieses Antwortschreiben.", sourceObjective = "Kehrt mit Lord Schwarzhaupts Antwortschreiben zu Magistrat Solomon zurück.", progress = "Ah, gut, Ihr seid von Eurem Botengang zurück. Kann ich den Marshal informieren, dass die Nachtwache von Dunkelhain hierher unterwegs ist?", completion = "Beim Licht! Die Armee von Stormwind hat sich aus Westfall zurückgezogen und die Wache beschützt Dunkelhain nicht mehr? Hier ist Verrat im Spiel. Wie konnte dies geschehen? \n\nDoch ich vergaß, Euch für Eure Dienste zu belohnen, {class}. Hier habt Ihr einige Münzen. Und nun entschuldigt mich. Etwas stimmt nicht in Stormwind und ich muss der Sache auf den Grund gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[147] = { id = 147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menschenjagd", description = "Wenn der \"Sammler\" Gold aus unseren Minen entnimmt, dann bestiehlt er das Königreich! Führt den Sammler seiner gerechten Strafe zu und bringt mir den Ring, der in dem Abholplan, den Ihr mir gegeben habt, erwähnt wurde.\n\nIm Abholplan steht, dass der Sammler sich bei Brackbrunns Kürbisbeet versteckt hält. Dort solltet Ihr nach ihm suchen.", sourceObjective = "Findet den \"Sammler\" und tötet ihn, dann kehrt mit dem Ring des Sammlers zu Marschall Dughan zurück.", progress = "Habt Ihr den Sammler gefunden? Konntet Ihr herausfinden, für wen er arbeitet?", completion = "Ihr habt ihn gefunden? Gut gemacht, {name}. Der wird in den Minen von Elwynn nichts mehr \"einsammeln\"!\n\nUnd dieser Ring, den Ihr gefunden habt, ist auch sehr interessant. Es ist ein Gildenring der alten Steinmetzgilde aus Stormwind. Warum hat ein nichtswürdiger Dieb den Ring einer Handwerkergilde in seinem Besitz und warum treibt die Bruderschaft der Defias Geld aus unseren Minen ein?\n\nDas sind schwierige Fragen, und ich hoffe nur, wir werden eines Tages die Antworten darauf finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[148] = { id = 148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung aus Dunkelhain", description = "Ach, was soll ich armer, alter Mann nur machen? Ich brauche einige Vorräte aus Dunkelhain, aber das Dorf ist so weit weg und ich bin so alt und schwach... ich würde die Reise niemals überstehen.\n\nKönnt Ihr nach Dunkelhain reisen und mir etwas Geisterhaarfaden mitbringen? Den bekommt Ihr im Haus von Madame Eva am Dorfplatz von Dunkelhain.", sourceObjective = "Sprecht mit Madame Eva.", completion = "So, Ihr braucht also Geisterhaarfaden, hm? Ich habe leider keinen mehr auf Lager, aber ich kann Euch welchen herstellen - wenn Ihr mir das Geisterhaar besorgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[149] = { id = 149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterhaarfaden", description = "Es gibt da einen armen, traurigen Geist, die blinde Mary, die in einem alten Bauernhaus in den Hügeln südlich von Dunkelhain spukt.\n\nHier, nehmt diesen spektralen Kamm und bittet die blinde Mary, sich die Haare zu kämmen. Bringt mir anschließend den Kamm zurück, dann entnehme ich ihm das Geisterhaar, das ich für den Faden brauche.\n\nUnd seht Euch vor, denn in der Nähe dieses Hauses lauern üble Dinge...", sourceObjective = "Bringt der blinden Mary den spektralen Kamm.", progress = "<Schluchz> Oh bitte, seht mich nicht an! Ich habe mir diese Augen mit meinen eigenen Händen herausgerissen, aber Euren Blick kann ich immer noch spüren!\n\nIch sehe grauenhaft aus! Grauenhaft! Ich flehe Euch an, wendet Euren Blick ab!", completion = "Was ist das? Ein Kamm? Er ist wunderschön! Und er gleitet durch mein Haar, als wäre es nicht so entsetzlich verklebt und strähnig, wie es ist.\n\nAch, wenn ich doch nur einen Spiegel hätte...", sourceObjectiveStatus = "unverified-source-field" }
quests[150] = { id = 150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murlocwilderer", description = "Die Murlocs werden zu einem Problem. Große Gruppen der Fischwesen werfen entlang der Ufer des Immerruhsees Anker und fischen, was das Zeug hält! Sie müssen verschwinden, ehe sie den ganzen See leer gefischt haben.\n\nGeht Murlocs jagen! Bringt mir 8 ihrer Flossen, dann habe ich vielleicht etwas für Euch...", sourceObjective = "Bringt 8 Murlocflossen nach Seenhain zu Dockmeister Baren.", progress = "Habt Ihr die Flossen? Sputet Euch - diese Murlocs müssen vom See vertrieben werden!", completion = "Gut gemacht, {name}. Ich hoffe, diese Murlocs haben Euch nicht zu viele Schwierigkeiten bereitet.\n\nEs ist seltsam, dass man sie so weit vom Meer entfernt sieht. Ich frage mich, ob sie hier sind, weil sie vor etwas davonlaufen...", sourceObjectiveStatus = "unverified-source-field" }
quests[151] = { id = 151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die arme Graumähne", description = "Die arme Graumähne! Das arme Pferd ist völlig entkräftet nach all der Arbeit, die wir ihm aufgebürdet haben. Ich habe es gefüttert, ehe wir den Hof verließen, aber wir haben natürlich nicht damit gerechnet, dass uns der Wagen kaputtgehen würde. Wenn Ihr der Stute ein paar Hände voll Hafer vom Feld bringen könntet, wäre ich Euch dankbar.\n\nIch wette, es lässt sich rund um die Höfe in Westfall etwas Hafer finden; Ihr müsst nur diesen entsetzlichen Maschinen aus dem Weg gehen, die hier alles übernommen haben. Es gibt einige Höfe südwestlich von hier.", sourceObjective = "Verna Brauenwirbel in Westfall möchte, dass Ihr ihr 8 Hände voll Hafer bringt.", progress = "Graumähne kann sich kaum noch auf den Beinen halten. Habt Ihr zufällig etwas Hafer für sie finden können?", completion = "Vielen herzlichen Dank, {name}! Da wird sich die gute Graumähne aber freuen!", sourceObjectiveStatus = "unverified-source-field" }
quests[152] = { id = 152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger an der Küste", description = "Die vielen Schiffswracks entlang der Küste sind Euch ja vermutlich schon aufgefallen. Das große Meer ist überaus tückisch. Die Küste von Westfall muss freigehalten werden, damit die Seeleute sicher sind, wenn sie unsere Ufer erreichen. Aber die Murlocs sind ein Problem.\n\nTötet 7 Gezeitenjäger, 7 Krieger, 7 Orakel und 7 Küstenläufer, dann sorge ich dafür, dass Ihr belohnt werdet.", sourceObjective = "Tötet 7 Gezeitenjäger, 7 Krieger, 7 Orakel sowie 7 Küstenläufer und kehrt dann zu Kapitän Grausohn beim Leuchtturm von Westfall zurück.", progress = "Tötet 7 Gezeitenjäger, 7 Krieger, 7 Orakel und 7 Küstenläufer, dann sorge ich dafür, dass Ihr belohnt werdet.", completion = "Gut gemacht, {name}. Ihr habt ein ziemliches Talent für den Kampf. Dank Euch ist die Küste Westfalls jetzt sicherer als zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[153] = { id = 153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rote Lederkopftücher", description = "Die Defias sind ständig in Bewegung. Ich überwache ihre Aktivitäten jetzt schon seit einiger Zeit. Und dabei habe ich festgestellt, dass viele Bandenmitglieder an den roten Lederkopftüchern zu erkennen sind, die sie tragen.\n\nBringt mir 15 dieser Kopftücher, dann werde ich dafür sorgen, dass Ihr belohnt werdet.", sourceObjective = "Bringt 15 rote Lederkopftücher auf die Späherkuppe zu Späher Galiaan.", progress = "Bringt mir 15 rote Lederkopftücher, ich werde Euch gut dafür bezahlen.", completion = "Gute Arbeit, {race}. Bitte nehmt einen dieser Gegenstände als Bezahlung für Eure harte Arbeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[154] = { id = 154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr mit dem Kamm", description = "NEIN!!!!!\n\nNehmt ihn weg, nehmt diesen Kamm weg!\n\nIch bin ein Monster und niemand wird mich jemals wieder für schön halten!", sourceObjective = "Bringt den Geisterhaarkamm zu Madame Eva nach Dunkelhain.", progress = "Ich kann spüren, dass Ihr die blinde Mary getroffen habt. Habt Ihr auch meinen Kamm?", completion = "Damit kann ich eine Rolle Geisterhaarfaden herstellen und es bleiben sogar noch einige Haare übrig. Hier habt Ihr einige Münzen für diese zusätzlichen Haare.", sourceObjectiveStatus = "unverified-source-field" }
quests[155] = { id = 155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bruderschaft der Defias", description = "Starkmantel denkt also wirklich, <ein/eine:r> {race} wie Ihr könne mich beschützen? Tja, Ihr werdet wohl reichen müssen. Bringt am besten ein paar Freunde mit. \n\nIhr wisst ja, wie's läuft, oder? Ihr haltet mir den Rücken frei und ich bringe Euch zum Versteck der Defias. Aber Ihr solltet besser in meiner Nähe bleiben, denn die Bande der Defias will jetzt meinen Kopf. Wenn die mich mit Euch sehen, werden sie versuchen, mich umzubringen.\n\nSagt mir einfach Bescheid, wenn Ihr und irgendwelche Freunde, die Ihr noch zusammentrommeln könnt, bereit seid loszuziehen.", sourceObjective = "Eskortiert den Verräter der Defias zum Geheimversteck der Defiasbruderschaft. Sobald der Verräter der Defias Euch gezeigt hat, wo sich van Cleef und seine Männer aufhalten, kehrt Ihr mit der Information zu Gryan Starkmantel zurück.", completion = "Ganz ausgezeichnet, {name}! Jetzt, wo wir wissen, wo er sich versteckt, gehört van Cleef so gut wie uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[156] = { id = 156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sammeln von Faulblüten", description = "Wenn Ihr mir ein paar Faulblüten bringt, dann kann ich Euch einen Kessel Zombiesaft brauen.\n\nFaulblüten wachsen an seltsamen Orten. Vor allem, habe ich gehört, findet man sie in den Schädeln von Skelettschrecken und Skelettscheusale - nicht, dass ich selbst schon mal nah genug dran war, um nachzusehen!\n\nDer Friedhof von Rabenflucht ist voll von diesen Skeletten. Wenn Ihr die auf Eurer Suche nach den Faulblüten auch noch dezimiert, dann schlagt Ihr zwei Fliegen mit einer Klappe, und ganz Dunkelhain wäre Euch dankbar.", sourceObjective = "Sammelt 8 Faulblüten und bringt sie nach Dunkelhain zu Schankwart Smitts.", progress = "Hallo, {name}. Habt Ihr die Faulblüten für mich?", completion = "Oh gut, Ihr habt die Faulblüten bekommen. Und ich werde Althea Ebonlocke von der Nachtwache erzählen, dass Ihr etliche Skelette getötet habt.\n\nDie Bevölkerung von Dunkelhain zu beschützen, stellt für die Nachtwache eine schwere Aufgabe dar und das Wissen, dass es auch andere gibt, die die Flut der Unwesen einzudämmen helfen, ist für sie eine willkommene Nachricht.", sourceObjectiveStatus = "unverified-source-field" }
quests[157] = { id = 157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abliefern des Fadens", description = "Hier ist Euer Faden, {name}. Man kann tausend Dinge damit machen, zum Beispiel böse Geister binden oder unbelebte Gegenstände mit Leben erfüllen.", sourceObjective = "Bringt Calvinius den Geisterhaarfaden in seine Hütte nördlich des Friedhofs von Rabenflucht.", progress = "Ich brauche den Geisterhaarfaden, um ihn quer über meine Tür und meine Fenster zu spannen. Das hält unliebsame Geister fern. Habt Ihr ihn für mich besorgt?", completion = "Wunderbar! Das ist gerade richtig...\n\nHier, bitte, mein guter {name}, nehmt dies als Bezahlung für Eure ehrenhafte Tat.", sourceObjectiveStatus = "unverified-source-field" }
quests[158] = { id = 158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zombiesaft", description = "Ich brauche eine Flasche eines bestimmten Schnapses, und zwar Zombiesaft. Schankwart Smitts aus der Taverne Zum roten Raben in Dunkelhain sollte welchen haben.\n\nUnd bitte sputet Euch, {name}. Die Nächte sind kalt und ich brauche den Schnaps, um meine Adern wieder mit Feuer zu erfüllen!", sourceObjective = "Sprecht mit Schankwart Smitts.", completion = "Ihr braucht etwas Zombiesaft, wie? Hmm, das Zeug ist ziemlich stark - ich werde nicht oft danach gefragt.", sourceObjectiveStatus = "unverified-source-field" }
quests[159] = { id = 159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saftlieferung", description = "Hier habt Ihr Euren Zombiesaft...\n\n... aber passt mir mit dem Zeug auf. Es ist stark genug, um die Toten zu erwecken!", sourceObjective = "Bringt Calvinius den Zombiesaft in seine Hütte.", progress = "Ich brauche den Zombiesaft, um mich in diesen dunklen, kalten Nächten warm zu halten. Habt Ihr ihn für mich besorgt?", completion = "Seid tausendmal bedankt, {name}! Ihr erwärmt das Herz eines alten Mannes mit Eurer Naiv... ääh... mit Eurer Freundlichkeit!\n\nHier, bitte schön, mein Freund, nehmt dies als ein Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[160] = { id = 160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Brief für den Bürgermeister", description = "Bringt diese Nachricht zu Ello Schwarzhaupt, dem Bürgermeister von Dunkelhain.\n\nEr und ich sind alte Freunde, und wenn er den Zettel liest und herausfindet, was Ihr für mich getan habt... dann freut er sich bestimmt genauso sehr, wie ich das tue! Hahahaha!", sourceObjective = "Bringt Calvinius' Brief zu Ello Schwarzhaupt, dem Bürgermeister von Dunkelhain.", progress = "Calvinius...? Ich kenne niemanden dieses Namens. Ihr sagt, Ihr habt einen Brief für mich von diesem Calvinius?\n\nNa, dann lasst mal sehen...", completion = "<Ello sieht sich den Brief an...>\n\nWas für eine Sprache ist das? Sie sieht uralt aus... ich kann sie nicht lesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[161] = { id = 161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dunkle Bedrohung", description = "Falls mein Verdacht sich bestätigt, ist dies eine Art Sprengpulver. Es muss von einem Sprengstoffexperten analysiert werden, damit wir genau wissen, mit was wir es hier zu tun haben. Ashlan Schmunzelstein wurde dem Regiment zugeteilt, das Dun Modr und den Thandolübergang bewachen soll. Ihr müsst für mich eine schwierige und gefahrvolle Reise auf Euch nehmen, {name}.\n\nReist durch das Algaz-Tor, folgt der Straße durch das Sumpfland und sucht Schmunzelstein in Dun Modr auf. Folgt meinem Rat: Bleibt auf den Straßen und lasst Euch nicht zum Anhalten bewegen!", sourceObjective = "Chefingenieur Hinderweir möchte, dass Ihr das sonderbar riechende Pulver zu Ashlan Schmunzelstein, dem Sprengstoffexperten, bringt. Er befindet sich in Dun Modr im Sumpfland.", progress = "Habt Ihr was gesagt, Jungchen? Ich kann nix hören außer dem verdammten Dröhnen in den Ohren. Sagt mal, was habt Ihr denn da?", completion = "Ah ja, also da hat der Olle Hinderweir verdammt Recht, dass er sich Sorgen macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[162] = { id = 162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Silithiden", description = "Ihr solltet mit diesem Bericht zu jemandem gehen, der ausreichend Kenntnis von solchen Dingen hat.\n\nIch kenne da diese Nachtelfengelehrte namens Gracina Glaubensmacht. Sie hat viel Zeit mit dem Studium der Lebensformen verbracht, die in der Ökologie von Azeroth einzigartig sind, und sie ist noch dazu Historikerin! Wenn Euch jemand dabei helfen soll herauszufinden, was genau diese Bedrohung ausmacht, und noch viel wichtiger, wie sie zu stoppen ist, gebt ihr den Bericht. Wir werden die Hilfe brauchen.\n\nDas Letzte, was ich hörte, war, dass sie im Tempel des Mondes in Darnassus lebt.", sourceObjective = "Bringt den Bericht über Insektenanalyse nach Darnassus zu Gracina Glaubensmacht.", progress = "Friede und Gelassenheit sei mit Euch, Fremdling. Warum habt Ihr mich heute aufgesucht?", completion = "Dieser Bericht... wir Nachtelfen kennen den Schrecken, der hier erwähnt wird. Fizzledowser hat gut daran getan, dies und Euch zu mir zu schicken.\n\nDiese Kreaturen werden die Tanariswüste schnell verzehren; sie stellen so ziemlich die größte Bedrohung dar, der wir uns je gegenübersehen werden. Macht Euch mit diesem Namen vertraut, {name}: Silithid. Die hier erwähnten Insekten sind die Silithid und sie sind das Werkzeug einer der größten Bedrohungen, der sich die Horde und die Allianz gegenübersehen.\n\nWenn wir nur früher schon klug genug gewesen wären, das zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[163] = { id = 163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabenflucht", description = "Irgendetwas stimmt nicht in Rabenflucht, {name}. Calor schwört, dass jemand - oder etwas - in den Gebäuden dort umgeht. Zwei Nächte in Folge hat er jetzt schon gesehen, wie sich die Schatten bewegten, und in der Nacht vorher habe er Licht in einem der Fenster gesehen, sagte er.\n\nWenn Euch, wie Ihr sagt, die Sicherheit des Dämmerwalds am Herzen liegt, dann findet heraus, welches Monster in Rabenflucht umgeht.", sourceObjective = "Findet heraus, was in Rabenflucht umgeht.", completion = "Nein! Bitte tötet mich nicht! Ich bin's doch nur... Jitters! Sie sind überall... Ich kann ihnen nicht entkommen! Monster in Rabenflucht? N-n-n-nein... das kann gar nicht sein. Nur der harmlose Jitters.", sourceObjectiveStatus = "unverified-source-field" }
quests[164] = { id = 164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung an Sven", description = "Kennt Ihr Sven? Das ist mal ein Mann, der das Werk des Lichtes vollbringt! Er und seine Anhänger haben ein Lager am nordwestlichen Rand des Dämmerwalds.\n\nLeider sind sie so wenige, dass noch nicht einmal ein einziger Mann abkömmlich ist, um Vorräte aus der Stadt zu holen. Würdet Ihr diese Vorräte bei ihm abliefern?", sourceObjective = "Liefert die Vorräte an Sven.", progress = "Ihr seht ziemlich robust aus, {class}. Wollt Ihr Euch unserem Kampf anschließen?", completion = "Diese Vorräte werden sich als äußerst nützlich erweisen. Wir wissen die Hilfe der Familie Carevin stets zu schätzen. Hier habt Ihr etwas für Eure Mühe.", sourceObjectiveStatus = "unverified-source-field" }
quests[165] = { id = 165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Einsiedler", description = "Es gab einmal einen alten Mann, der recht häufig in die Stadt kam, um Vorräte einzukaufen, aber ich habe ihn jetzt schon ziemlich lange nicht mehr gesehen. Er lebt draußen in einer Hütte, von der aus man den Friedhof von Rabenflucht überblicken kann, wenn ich mich recht erinnere. Vielleicht solltet Ihr einmal nachsehen gehen, ob dort alles in Ordnung ist.", sourceObjective = "Schaut in der Nähe des Friedhofs von Rabenflucht nach dem alten Mann in der Hütte.", completion = "Elaine Carevin? Hehe, ja, aber natürlich... die Carevins.\n\nDoch, doch, es ist alles in Ordnung, aber es ist inzwischen ziemlich schwer für mich, in die Stadt zu kommen. Die Straßen sind gefährlich und ich werde nicht jünger. Vielleicht könntet Ihr ja einem alten Mann ein paar Gefallen tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[166] = { id = 166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bruderschaft der Defias", description = "Jetzt gibt es für Euch nur noch eine Aufgabe zu erledigen. Edwin van Cleef muss getötet werden. Zwar stimmt es mich traurig, einen Menschen zum Tode zu verurteilen, doch es ist zum Besten des Volkes von Westfall, wenn van Cleef ein für alle Mal aus dem Verkehr gezogen wird. Bringt mir den Kopf des Schurken, sobald die Tat getan ist.", sourceObjective = "Tötet Edwin van Cleef und bringt seinen Kopf zu Gryan Starkmantel.", progress = "Wie läuft die Jagd auf Edwin van Cleef?", completion = "Euer Mut ist bemerkenswert, {name}. Die Volksmiliz dankt Euch für Eure Verdienste um das Volk von Westfall. Van Cleefs Tod bedeutet den Anfang vom Ende für die Bruderschaft der Defias. Hoffentlich wird schon bald wieder Frieden auf den Ebenen unseres schönen Landes herrschen.\n\nIch ziehe den Hut vor Euch, werter Herr!", sourceObjectiveStatus = "unverified-source-field" }
quests[167] = { id = 167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh Bruder...", description = "Wir waren tief unten in einer großen Mine in Westfall, deren Eingang unter einer Scheune in Mondbruch versteckt lag. Keine Ahnung, wo dieses elende Diebesgesindel herkam. Egal, jedenfalls stürzte der Minentunnel über uns ein. Ich hab's nach draußen geschafft, aber die anderen... na ja... von den anderen hat seither niemand mehr etwas gehört.\n\nIhr seht aus, als könntet Ihr vielleicht etwas mehr Glück haben, wenn Ihr dort hineingeht. Wenn Ihr nach meinem Bruder suchen könntet, wäre ich Euch dankbar. Er trug immer sein Forscherliga-Abzeichen bei sich. Wenn Ihr ihn selbst nicht finden könnt, dann würde zumindest das Abzeichen mir etwas Seelenfrieden verschaffen.", sourceObjective = "Bringt Großknecht Distelklettes Abzeichen der Forscherliga nach Sturmwind zu Wilder Distelklette.", progress = "Habt Ihr ein Lebenszeichen von meinem Bruder finden können? Besteht Hoffnung nach all dieser Zeit?", completion = "Also haben meine Befürchtungen sich bestätigt. Mein armer Bruder... Nun, ich danke Euch dafür, dass Ihr dieses Rätsel gelöst habt, selbst wenn die Lösung eine traurige war.", sourceObjectiveStatus = "unverified-source-field" }
quests[168] = { id = 168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Andenken", description = "Viele meiner Freunde starben an jenem schrecklichen Tag, als der Minentunnel einstürzte. Wenn Eure Abenteuer Euch in jenen Abschnitt der Mine in Mondbruch führen sollten, dann haltet doch bitte die Augen offen nach jedem Zeichen, anhand dessen man sie identifizieren könnte. Wenn Ihr zum Beispiel ihre Gewerkschaftsausweise finden solltet, so bringt sie mir, dann sehe ich zu, dass ihre Familien informiert werden und damit wenigstens eine Art Schlussstrich unter diesen schrecklichen Unfall ziehen können.", sourceObjective = "Beschafft 4 Gewerkschaftsausweise und bringt sie nach Sturmwind zu Wilder Distelklette.", progress = "Konntet Ihr einige der Gewerkschaftsausweise meiner alten Kameraden wiederfinden?", completion = "Danke, dass Ihr die Ausweise beschafft habt, {name}. Eure Anstrengungen helfen dabei, dass die Toten nach dieser schrecklichen Tragödie ihren Frieden finden. Ich werde dafür sorgen, dass die Familien benachrichtigt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[169] = { id = 169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Gath'Ilzogg", description = "Gesucht! Gath'Ilzogg, Rädelsführer hinter den Angriffen des Schwarzfelsklans auf Burg Steinwacht und den Überfällen auf die Ortschaft Seenhain. \n\nGath'Ilzogg ist äußerst gefährlich. Berichten zufolge hat er sich in der kürzlich eroberten Burg eingenistet und plant dort die weiteren Verbrechen des Schwarzfelsklans gegen die menschliche Bevölkerung. Die Orcplage muss um jeden Preis eingedämmt werden. Der tapferen Seele, die Magistrat Solomon den Kopf von Gath'llzogg übergeben kann, winkt eine großzügige Belohnung.", sourceObjective = "Erledigt Gath'Ilzogg und bringt seinen Kopf zu Magistrat Solomon in Seenhain, um die Belohnung zu erhalten.", progress = "Was bringt Ihr mir da, {race}?", completion = "Ausgezeichnete Arbeit, {name}! Gath'llzogg führte diese Bestien in die Schlacht und war für den Tod vieler unschuldiger Menschen verantwortlich. Nun haben wir uns gerächt. Dies ist der erste Schritt zur Wiedereroberung der Burg für das Königreich Stormwind!", sourceObjectiveStatus = "unverified-source-field" }
quests[170] = { id = 170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Bedrohung", description = "Ich hoffe, Ihr seid hier, um uns zu helfen, {class}. Nach dem letzten Angriff der Troggs können wir alle Hilfe gebrauchen, die wir kriegen können.\n\nIch habe gehört, die kleinen Biester sind überall im ganzen Land aufgetaucht, und wie es scheint, ist das Eisklammtal keine Ausnahme. Sie sind kreuz und quer in den Hügeln im Südosten und in der Nähe des gefrorenen Sees gesehen worden.\n\nUnd das ist noch nicht alles. Vor ein paar Nächten haben sie unser Lager im Westen angegriffen und überrannt! \n\nWir haben hier zu wenig Leute, <Jungchen/Mädel>, und wir brauchen ein paar starke Arme, die dabei helfen, die Troggs zurückzutreiben.", sourceObjective = "Balir Frosthammer möchte, dass Ihr 6 Troggs der Felsenkiefer und 6 bullige Troggs der Felsenkiefer tötet.", progress = "Zähe kleine Biester, was?", completion = "Wenn die Probleme, die wir hier haben, ein Hinweis darauf sind, was anderswo in unserem Land passiert, dann - bei Magnis Bart! - stehen uns Schwierigkeiten ins Haus! Ich kann nur hoffen, dass der König und der Senat etwas gegen die Bedrohung durch die Troggs unternehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[171] = { id = 171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tageseltern der Allianz", description = "Ihr wart die ganze Zeit so gut zu mir, {name}. Nie hätte ich erwartet, während der Kinderwoche so viel Spaß zu haben! Danke schön. Ich versuche über das, was mir und den anderen passiert ist, nicht traurig zu sein - meine Freunde sagten immer, ich solle über allem Bösen stehen, das in der Welt passiert. Weißt du was? Wenn ich groß bin, möchte ich genauso ein Held sein wie du!\n\nEs macht mich zwar traurig, aber leider muss ich jetzt nach Hause gehen. Lass uns zur Matrone zurückgehen und ihr erzählen, was für <ein wunderbarer/eine wunderbare:r> {race} du bist!", sourceObjective = "Bringt Euren Schützling in das Waisenhaus von Sturmwind zurück, indem Ihr die Pfeife des Menschenwaisenkindes an Waisenmatrone Nachtigall im Kathedralenviertel übergebt.", progress = "Es ist schön Euch wiederzusehen, {name}. Habt Ihr die Euch auferlegten Pflichten, für die Ihr Euch während der Kinderwoche freiwillig gemeldet habt, sorgfältig erfüllt?", completion = "Möge der Himmel Euch segnen, {name}. Ihr habt für Randis mehr getan, als es jemand anderem je in den Sinn gekommen wäre. Vielen Dank - Ihr seid ein funkelnder Stern am Himmel der Allianz.\n\nBitte besucht uns mal wieder, wenn Ihr etwas Zeit habt. Ich weiß, dass Randis sich sehr freuen würde, genauso wie ich.\n\nRandis hatte so viel Spaß mit Euch, {name}. Er hat mich gebeten Euch eines seiner Lieblingstierchen zu geben, damit Ihr Euch stets an ihn erinnert.", sourceObjectiveStatus = "unverified-source-field" }
quests[172] = { id = 172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kinderwoche", description = "Ihr wollt uns tatsächlich hier im Waisenhaus zur Hand gehen? Seid gesegnet, Freund. Eure Unterstützung in der Kinderwoche ist für uns von unschätzbarem Wert.\n\nNehmt diese Pfeife. Sie kann sieben Tage lang verwendet werden - über die ganze Dauer der Kinderwoche hinweg. Durch Benutzung der Pfeife, könnt Ihr mit dem Waisenkind sprechen, auf das Ihr aufpasst. Verwendet sie erneut, um das Kind wieder zu entlassen.\n\nDas Kind ist schon ganz aufgeregt und freut sich darauf Euch kennenzulernen. Worauf wartet Ihr noch {name}, benutzt die Pfeife und trefft Euren Schützling.", sourceObjective = "Benutzt die Pfeife des Orcwaisenkindes um während der Kinderwoche mit Eurem Schützling zu sprechen.\n\nBereitgestellter Gegenstand:", completion = "Zug-zug! Mein Name ist Grunz und ich vermute du suchst nach mir? Ihr seid ein Abenteurer, genauso wie meine Mama und mein Papa. Meine Matrone sagt immer, dass sie ehrenhaft in der Schlacht gefallen sind. Ich bin so glücklich Euch zu treffen!\n\nHoffentlich erleben wir zusammen viele lustige Sachen. Es gibt so viele Sachen, die ich gerne einmal machen würde und die Matrone hat gesagt, dass Ihr diese Woche so etwas wie mein großer Bruder seid. Das finde ich toll!", sourceObjectiveStatus = "unverified-source-field" }
quests[173] = { id = 173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in den Wäldern", description = "Es scheint, als würden dunkle Dinge unaufhaltsam in den Dämmerwald gezogen. Meister Treuwein hat sich der Aufgabe verschrieben, das Böse und die Ketzerei zu vertreiben. Dank unserer Anstrengungen lebt das Volk von Dunkelhain in Sicherheit.\n\nIhr glaubt, Ihr seid würdig, Euch unserer Gruppe anzuschließen?\n\nEinst dachte ich wie Ihr. Die Selbstzufriedenheit der Wache hatte mich meiner Illusionen beraubt und so schloss ich mich Meister Treuwein an. Wenn Ihr Euch beweisen möchtet, so kann dies nicht durch Worte geschehen.\n\nMesst Eure Fertigkeiten an den Schattenwirkern der Nachtheuler im Schattenhain und im verlassenen Obstgarten.", sourceObjective = "Tötet für Calor aus Dunkelhain 6 Schattenwirker der Nachtheuler.", completion = "Ich bin beeindruckt, {name}. Es scheint, als wäret Ihr durchaus fähig, Euch im Kampf zu behaupten. Vielleicht können wir ja eine Aufgabe für Euch finden, die jemanden mit Euren Fähigkeiten etwas mehr herausfordert.\n\nAber es ist schon eigenartig... Es ist, als seien die Worgs plötzlich aus dem Nichts erschienen. Aber es sind ja in letzter Zeit so viele seltsame Kreaturen in unser Land gekommen, da sind auch die Worgs vermutlich nur eine unserer vielen Sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[174] = { id = 174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blick zu den Sternen", description = "Mein Freund Cog, der Gnom, hat mir versprochen, mir beim Bau eines Gerätes zu helfen, mit dem ich in die Sterne blicken kann. Jenseits der Magie existiert eine Wahrheit, mit deren Hilfe sich die seltsame Verwandlung des Waldes erklären lässt.\n\nBringt mir eine Bronzeröhre, die von einem geschickten Ingenieur hergestellt wurde. Wenn man nach Cogs Blaupause geht, ist das der erste Schritt.", sourceObjective = "Viktori Prism'Antras aus Dunkelhain möchte, dass Ihr ihm eine Bronzeröhre bringt.", progress = "Habt Ihr bereits einen geschickten Ingenieur gefunden, der eine Bronzeröhre fertigen kann?", completion = "Diese Röhre ist perfekt, {name}. Das war der erste Schritt!", sourceObjectiveStatus = "unverified-source-field" }
quests[175] = { id = 175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blick zu den Sternen", description = "Laut Cogs Blaupause brauche ich jetzt etwas, mit dem Licht reflektiert werden kann. Ich erinnere mich an eine Frau namens Mary, die hier in der Gegend eine gewisse Bekanntheit erlangte, weil sie immer einen Handspiegel bei sich trug. Vielleicht könnt Ihr diese Mary aufspüren und sie fragen, ob sie ihn uns für unser Vorhaben vielleicht leiht, weil wir ja eine reflektierende Oberfläche brauchen... Ich glaube, sie wohnte früher im südlichen Dämmerwald...", sourceObjective = "Findet Mary und überredet sie, einen Gegenstand mit reflektierender Oberfläche zu Viktoris Projekt beizusteuern.", completion = "Doch, ja, ich besaß früher einen Handspiegel.", sourceObjectiveStatus = "unverified-source-field" }
quests[176] = { id = 176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: \"Hogger\"", description = "Gesucht: Hogger\n\nEin riesiger Gnoll, Hogger, streunt im südwestlichen Elwynn durch den Wald. Er hat bislang alle Versuche, ihn zu fangen, vereiteln können.\n\nDie Armee von Sturmwind hat ein großzügiges Kopfgeld auf den Gnoll ausgesetzt. Kopfgeldjäger, die sich die Belohnung verdienen möchten, sollten einen Beweis für Hoggers Tod bei Marschall Dughan in Goldhain vorlegen.", sourceObjective = "Erschlagt den Gnoll Hogger und bringt seine gewaltige Gnollklaue zu Marschall Dughan.", progress = "Ja, Hogger stellt für mich und meine Männer schon seit längerem ein echtes Problem dar. Habt Ihr mir etwas über die Bestie zu berichten?", completion = "Ha! Gut gemacht! Ich hatte schon befürchtet, niemand würde diesem Monster den Garaus machen!\n\nHier, bitte schön, {name}. Und danke - dieser Gnoll hat mir Kopfschmerzen vom Ausmaß der Blackrockspitze verursacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[177] = { id = 177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blick zu den Sternen", description = "Der Handspiegel war eines meiner wertvollsten Besitztümer bis zu... dem Vorfall. Danach warf ich den Spiegel hinter der Scheune fort. Es gab da einen irrsinnigen Ghul, der sich früher dort hinten herumgetrieben hat. Vielleicht hat der ihn aufgehoben und mitgenommen. Gerüchten zufolge haust die teuflische Bestie im Friedhof \"Stille Gärten\".", sourceObjective = "Nehmt dem irrsinnigen Ghul den Handspiegel der blinden Mary ab und gebt ihn Viktori in Dunkelhain.", progress = "Ich habe Cog die Anfänge unseres Sternenschaugerätes gezeigt. Er war schwer beeindruckt. Habt Ihr zufällig einen Reflektor finden können?", completion = "Ganz phantastisch! Dies ist geradezu perfekt geeignet. Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[178] = { id = 178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbeschaffung für Theocritus", description = "<Ihr hört eine körperlose Stimme:>\n\nIhr müsst nicht erschrecken. Ich bin Theocritus, Hochmagier des Turms von Azora im Wald von Elwynn. Der Anhänger, den Ihr in Händen haltet, ist ein Mittel zur Kommunikation zwischen den Schattenfellgnollen und Morganth, ihrem Meister.\n\nNach langen Monaten der Forschung glaube ich, dass nun auch ich durch diese Anhänger kommunizieren kann. Wenn Ihr diese Nachricht hören könnt, dann war mein Zauber erfolgreich.\n\nBringt mir diesen Anhänger und ich werde Euch für Eure Dienste belohnen.", sourceObjective = "Bringt den verblassten Schattenfellanhänger zu Theocritus, dem Magier. Er befindet sich im Turm von Azora im Wald von Elwynn.", progress = "Ich habe durch einen Anhänger zu Euch gesprochen, sagt Ihr? Hmm... gebt ihn mir, damit ich ihn studieren kann.", completion = "Seid Euch meiner Dankbarkeit gewiss, {name}. Schon vor Wochen sandte ich die Nachricht zu den Schattenfellanhängern aus und hatte bereits an einen Fehlschlag geglaubt. Doch es scheint, als habe der Zauber nach einer erheblichen Verzögerung doch zumindest einige Anhänger erreicht.\n\nMit der Zeit hoffe ich zu lernen, wie man auch einen Angriff durch die Anhänger leiten und damit alle Schattenfellgnolle, die einen solchen Anhänger tragen, bewegungsunfähig machen kann.\n\nDoch bevor dies möglich sein wird, sind leider noch viele Stunden der Forschung vonnöten, fürchte ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[179] = { id = 179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwergenausstatter", description = "Was haben wir denn hier? Ihr seht aus, als könntet Ihr was brauchen, was Euch die Hände warm hält, hm?\n\nIch sag Euch, was da helfen würde: ein paar schöne, warme Handschuhe. Und weil ich so ein netter Kerl bin, geb ich Euch doch gern so ein Paar. Unter einer Bedingung, versteht sich.\n\nIhr müsst mir etwas Wolfsfleisch besorgen. Ist doch 'n guter Handel, oder? Ihr bringt mir etwas Wolfsfleisch und ich sorge dafür, dass Ihr Euch keine Frostbeulen an den Fingern holt. Na, was sagt Ihr?", sourceObjective = "Sten Starkarm hätte gern 8 Stücke zähes Wolfsfleisch.", progress = "Haben Euch die Wölfe Probleme gemacht? Vielleicht solltet Ihr den Klauen und Zähnen und dem, was da sonst noch so alles kratzt und beißt, ausweichen, hm?", completion = "Ah! Großartig. Das Wolfsfleisch ist gerade richtig. Ach, keine Sorge, {name}, ich vergess doch meinen Teil der Abmachung nicht! Hier, davon sollte Euch eins passen.", sourceObjectiveStatus = "unverified-source-field" }
quests[180] = { id = 180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Leutnant Fangor", description = "Gesucht: Leutnant Fangor\n\nBekannter Anführer des Gnollklans der Schattenfelle; arbeitet für Morganth, den Feind der Stadt und des Königreiches. Auf Geheiß von Magistrat Solomon wird der Tod dieses üblen Verräters an Sturmwind gewünscht. Zeigt dem Magistraten seine Tatze zum Beweis, dass er tot ist.", sourceObjective = "Tötet Leutnant Fangor und kehrt mit seiner Tatze zu Magistrat Solomon nach Seenhain zurück.", progress = "Welche Neuigkeiten bringt Ihr vor dieses Gericht?", completion = "Der üble Lieutenant Fangor ist also tot? Endlich sind wir diese abscheuliche Kreatur los. Ihr seid sehr tapfer, {class}. Die Stadt Seenhain dankt Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[181] = { id = 181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blick zu den Sternen", description = "Jetzt brauchen wir nur noch einen weiteren Gegenstand, um das Gerät fertig zu stellen. Laut Cogs Blaupause wird eine Linse oder etwas in der Art benötigt. Die einzige Linse, von der ich weiß, dass sie groß genug wäre, wird sehr schwierig zu beschaffen sein.\n\nEs gibt da einen Oger namens Zzarc'Vul, der im Ogerhort im Süden des Dämmerwalds haust. Wenn Ihr könnt, bringt mir sein Monokel, dann werde ich das als unsere Linse verwenden.", sourceObjective = "Findet Zzarc'Vul im südlichen Ogerhort des Dämmerwalds und bringt sein Monokel zu Viktori nach Dunkelhain.", progress = "Konntet Ihr Zzarc'Vul überzeugen, uns sein Monokel für unser Experiment zu leihen?", completion = "Endlich! Das Sternenschaugerät ist vollendet! Danke, {name}. Jetzt kann ich meine Forschungen fortsetzen...", sourceObjectiveStatus = "unverified-source-field" }
quests[182] = { id = 182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Trollhöhle", description = "Mein Bruder Senir und ich wurden in unterschiedliche Ecken von Dun Morogh entsandt, um dort die von den Trollen ausgehende Gefahr zu untersuchen. Der Senat hat mit den Troggs bereits alle Hände voll zu tun, deswegen kann er keinen weiteren Ärger gebrauchen.\n\nNach allem, was ich gesehen habe, ist die Position der Trolle hier im Eisklammtal nicht sonderlich gut - sie sind vor allem in der südlichen Höhle zu finden. Ich würde sagen, die Armee brauchen wir nicht. Einige starke Arme sollten mehr als ausreichend sein.\n\nMöchtet Ihr vielleicht mithelfen? Ich bin ermächtigt, Euch für Eure Dienste eine Entschädigung anzubieten.", sourceObjective = "Grelin Weißbart möchte, dass Ihr 10 Trollwelpen der Frostmähnen tötet.", progress = "Nach allem, was ich gehört habe, kommen diese Trolle aus dem Frostmaneklan. Leider weiß ich nicht viel mehr über sie, das Euch in irgendeiner Form helfen könnte, {name}.", completion = "Aargh! Diese vom Licht verbrannten Trolle!\n\n<Er atmet tief durch und scheint sich zu beruhigen... ein bisschen zumindest.>\n\nIn der Nacht hat eine Gruppe Trolle mein Tagebuch gestohlen! Ich hätte es besser wissen müssen. Was vertraue ich auch meinem nichtsnutzigen Lehrl...", sourceObjectiveStatus = "unverified-source-field" }
quests[183] = { id = 183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eberjäger", description = "Es geht doch nichts über einen Tag auf der Eberjagd, wie?\n\nNa ja, hier im Eisklammtal gibt es so viele Eber, dass es fast schon keinen Spaß mehr macht. Man muss sie gar nicht mehr reizen. Sie sind schon aggressiv und angriffslustig, ohne dass man nachhilft. Um genau zu sein, streifen in letzter Zeit so viele Eber durch die Gegend, dass es gefährlich für mich geworden ist, auf die Jagd zu gehen.\n\nIch mach's kurz: Wenn Ihr mir dabei helfen könntet, einige der Eber zu töten, dann würde ich das zu schätzen wissen.", sourceObjective = "Talin Kühnauge möchte, dass Ihr 8 kleine Klippeneber tötet.", progress = "Wie läuft die Jagd?", completion = "Ausgezeichnet! Dann kann ich ja jetzt meine... etwas gemächlichere... Jagd wieder aufnehmen. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[184] = { id = 184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brauenwirbels Urkunde", description = "Dies ist eine Besitzurkunde für ein Stück Ackerland in Westfall. Es ist von einem gewissen Theodore Brauenwirbel und seiner Frau Verna unterzeichnet. Auf der Rückseite der Besitzurkunde stehen ein paar hastig hingekritzelte Worte:\n\n\"Wir haben Brauenwirbel etwas bearbeitet und ihm seine Besitzurkunde abgeluchst. Wäre vielleicht ganz nützlich, wenn Ihr Euch auch so eine fälschen wolltet.\n\nUm die Brauenwirbels müssen wir uns jedenfalls keine Sorgen machen. Zuletzt sah ich sie kurz hinter Westfall in einem Wagen mit gebrochener Achse.\"\n\nIhr denkt, die Brauenwirbels hätten ihre Besitzurkunde vielleicht gern zurück...", sourceObjective = "Bringt Brauenwirbels Besitzurkunde zu Bauer Brauenwirbel.", progress = "Ihr habt die Besitzurkunde meines Hofes? Wie schön! Einige Grobiane haben sie vor etlichen Tagen gestohlen... Ich dachte schon, ich würde sie nie wieder sehen!\n\nBitte, gebt sie mir. Wir sind auf dem Weg, Westfall zu verlassen, und so schnell werden wir nicht wiederkommen, aber wenn, dann werden wir diese Dokumente brauchen.", completion = "Vielen, vielen Dank, {name}! Wie schon gesagt, diese Gegend ist kein Ort mehr für ehrliche Leute, aber wenn die Dinge besser werden sollten, dann können wir mit dieser Besitzurkunde unser Land zurückfordern.\n\nIch habe nicht viel, was ich Euch anbieten kann, aber hier: Nehmt das.", sourceObjectiveStatus = "unverified-source-field" }
quests[185] = { id = 185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Tigerjagd", description = "Als ich noch ein kleines Mädchen war, brachte mein Vater mir die Kunst der Tigerjagd bei.\n\nIhr werdet feststellen, dass die jungen Katzen sich wesentlich leichter aufspüren und töten lassen. Deswegen fangen wir auch klein an. Man findet die jungen Tiger oftmals in der Nähe des Expeditionslagers.\n\nÜbt Euch im Fährtenlesen und seht zu, ob Ihr nicht einige der Wildtiere zur Strecke bringen könnt.", sourceObjective = "Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 junge Schlingendorntiger tötet.", completion = "Das habt Ihr gut gemacht, {name}. Ihr seid jetzt bereit, Euch anderen Dingen zu widmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[186] = { id = 186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Tigerjagd", description = "Ihr macht Fortschritte, {class}. Jetzt lasst uns sehen, wie Ihr Euch gegen die ausgewachsenen Katzen anstellt. Tötet diesmal 10 Schlingendorntiger.", sourceObjective = "Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 Schlingendorntiger tötet.", completion = "Ich bin beeindruckt, {class}. Ihr kommt recht gut voran.", sourceObjectiveStatus = "unverified-source-field" }
quests[187] = { id = 187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Tigerjagd", description = "Jetzt werde ich den Einsatz erhöhen und Eure Fähigkeiten wirklich prüfen. Beweist mir, dass Ihr 10 alte Schlingendorntiger töten könnt. Wenn Ihr das schafft, dann seid Ihr bereit für Eure letzte Herausforderung, ehe ich Euch in Meister Nesingwarys Gegenwart <zum Meisterjäger/zur Meisterjägerin> ernenne.\n\nNicht nur sind die alten Schlingendorntiger am schwierigsten zu finden, sie sind auch am schwierigsten zu besiegen.", sourceObjective = "Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 alte Schlingendorntiger tötet.", completion = "Sehr eindrucksvoll. Ich glaube, Ihr seid fast so weit.", sourceObjectiveStatus = "unverified-source-field" }
quests[188] = { id = 188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Tigerjagd", description = "Hier ist die letzte Aufgabe, die ich Euch auferlegen werde. Wir sind schon seit Wochen einer schwer zu fassenden Tigerin auf der Spur. Wir nennen das Tier Sin'Dall. Vielleicht gelingt Euch ja, was noch <kein/keine:r> {race} vor Euch geschafft hat: Spürt Sin'Dall auf und bringt sie zur Strecke. Bringt mir ihre Tatze zum Beweis für Eure Leistung.\n\nAber die Tigerin aufzuspüren, wird nicht leicht sein.", sourceObjective = "Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr Sin'Dall tötet und mit ihrer Tatze zurückkehrt.", progress = "Wie läuft die Jagd auf Sin'Dall?", completion = "Äußerst beeindruckend, das muss ich schon sagen! Ihr seid wahrlich ein Meisterjäger, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[189] = { id = 189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohren der Blutskalpe", description = "Verdammte Trolle! Sie haben im Dschungel schon etliche unserer Agenten getötet und ich habe bereits einige meiner besten Wachen in Scharmützeln mit ihnen verloren. Was das alles kostet! Wie soll ich das nur Baron Revilgaz erklären?\n\nEntschieden handeln... Denk nach, Kebok... Du bist auf den Posten, den du heute hast, nicht durch Rumsitzen gekommen... Ha, ich hab's! Ihr... {name}, richtig? Ihr helft mir doch, oder? Es gibt auch Geld zu verdienen!\n\nFolgender Handel... Ihr bringt mir die Ohren von 15 Trollen der Blutskalpe und ich bezahle Euch gut dafür.", sourceObjective = "Verschafft Euch 15 Ohren der Blutskalpe und bringt sie Kebok in Beutebucht.", progress = "Ihr wart erfolgreich, hoffe ich. Die sind wirklich überall, diese Trolle. Widerliche Kerle.\n\nAch ja, da fällt mir was ein! Sagt es unbedingt auch all Euren Freunden weiter, ja? Wir können viel Hilfe gebrauchen!", completion = "Oh, ausgezeichnet, ganz ausgezeichnet. Das sollte helfen, für den Anfang zumindest...\n\n<Seine Stimme wird leiser und er murmelt irgendetwas von Gewinnspannen und Kosten.>\n\nWas denn? Seid Ihr immer noch da? Belohnung? Oh, ja, richtig... natürlich, hier, nehmt dies... das sollte mehr als genug sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[190] = { id = 190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Pantherjagd", description = "Wenn Ihr zusammen mit dieser Elitegruppe, die Hemet Jr. zusammengestellt hat, an der Jagd teilnehmen wollt, dann müsst Ihr erst beweisen, dass Ihr <ein fähiger Pantherjäger/eine fähige Pantherjägerin> seid. Aber wir fangen ganz einfach an, keine Sorge. Schauen wir mal, wie Ihr Euch beim Töten von 10 jungen Panthern anstellt.\n\nDie Tiere aufzuspüren ist nur die halbe Miete.", sourceObjective = "Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 junge Panther tötet.", progress = "En echter Pantherjäger wäre jetzt da draußen und würde seiner Beute nachstellen. Zeigt etwas Engagement, {class}, und macht, dass Ihr wieder ins Feld kommt.", completion = "Das war ein guter Anfang, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[191] = { id = 191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Pantherjagd", description = "Jetzt seid Ihr bereit, Euch an einen Gegner zu wagen, der eine Nummer schwieriger ist. Wenn Ihr Euch wirklich als würdig erweisen wollt, mit solchen Leuten wie den Großwildjägern zu verkehren, dann müsst Ihr beweisen, dass Ihr 10 Panther töten könnt.\n\nDiese Bestien sind schon etwas zäher. Die lassen sich nicht so leicht erlegen wie die Jungtiere, mit denen Ihr Euch bis jetzt abgegeben habt.", sourceObjective = "Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 Panther tötet.", progress = "Geht und tötet 10 Panther! Zeigt uns, aus welchem Holz Ihr geschnitzt seid!", completion = "Das habt Ihr perfekt durchgeführt, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[192] = { id = 192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Pantherjagd", description = "Jetzt kommt der schwierige Teil. Ein echter Pantherjäger beweist seine Fähigkeiten damit, dass er Schattentatzenpanther erlegt, die tödlichsten Vertreter ihrer Art im ganzen Schlingendorntal. Beweist uns, dass Ihr 10 dieser Bestien zur Strecke bringen könnt.\n\nUnd wenn Ihr glaubt, die seien schwer aufzuspüren, dann wartet nur, bis Ihr versucht, eine von ihnen zu erlegen...", sourceObjective = "Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 Schattentatzenpanther tötet.", progress = "Was macht Ihr denn hier, {name}? Ihr solltet durch das Unterholz kriechen und versuchen, 10 Schattentatzenpanther zu töten! Ich dachte, Ihr hieltet Euch für einen Großwildjäger?", completion = "Ihr habt Eure Sache gut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[193] = { id = 193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Pantherjagd", description = "Ihr habt schon fast bewiesen, dass Ihr die Kunst der Pantherjagd meisterlich versteht. Schon seit längerem pirscht ein Panther namens Bhag'thera durch den Dschungel. Bis jetzt ist er unserer Jagdgesellschaft immer ausgewichen. Seht zu, ob es Euch mit Euren Fähigkeiten gelingt, den großen Bhag'thera zu töten.\n\nBringt mir den Fangzahn von Bhag'thera, dann habt Ihr Euch meinen Respekt redlich verdient!", sourceObjective = "Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr ihm den Fangzahn von Bhag'thera bringt.", progress = "Bhag'thera ist oft so gut wie unauffindbar. Wie läuft die Jagd?", completion = "Der große Bhag'thera ist also tot! Meinen Beifall, {name}. Ihr seid wahrlich ein großer {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[194] = { id = 194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Raptorenjagd", description = "Soso, Ihr glaubt also, Eure Jagdfertigkeiten sind erstklassig? Das lässt sich ganz leicht feststellen. Zieht hinaus in den Dschungel und tötet 10 Schlingendornraptoren. Dann werden wir ja sehen, wie gut Ihr als Großwildjäger wirklich seid.\n\nUnd nein, ich werde Euch nicht sagen, wo Ihr sie finden könnt! Die Viecher aufzuspüren ist Teil der Aufgabe.", sourceObjective = "Hemet Nesingwary Jr. möchte, dass Ihr 10 Schlingendornraptoren tötet.", completion = "Sehr schön gemacht, alter Junge!", sourceObjectiveStatus = "unverified-source-field" }
quests[195] = { id = 195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Raptorenjagd", description = "Jetzt machen wir die Herausforderung ein wenig schwieriger und schauen mal, ob Ihr dem gewachsen seid. Begebt Euch in den Dschungel und erlegt 10 dieser elenden Schmetterschwanzraptoren. Zeigt uns, was Ihr so drauf habt!", sourceObjective = "Hemet Nesingwary Jr. möchte, dass Ihr 10 Schmetterschwanzraptoren tötet.", completion = "Ja, so bekommt man die eine oder andere Jagdtrophäe zusammen, die man sich zu Hause über den Kamin hängen kann! Das war eine gute Jagd, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[196] = { id = 196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Raptorenjagd", description = "Mal sehen, wie Ihr mit der nächsten Herausforderung fertig werdet. Dort draußen treibt sich eine sehr scheue Art von Raptoren herum. Wir nennen sie Dschungelpirscher. Sie sind sehr viel schwieriger aufzuspüren und zu erlegen als die anderen Arten, an denen Ihr Euch bisher versucht habt. Tötet 10 Dschungelpirscher, dann verrate ich Euch, wie Ihr zu einem noch besseren Jagderlebnis kommt.", sourceObjective = "Hemet Nesingwary Jr. möchte, dass Ihr 10 Dschungelpirscher tötet.", completion = "Hoho! Sieh an, wir haben hier einen wahren Raptorentöter! Sehr schön gemacht, alter Junge!", sourceObjectiveStatus = "unverified-source-field" }
quests[197] = { id = 197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Raptorenjagd", description = "Da Ihr Euch im Dschungel als so tatkräftig erwiesen habt, lasst mich Euch von einem wilden Raptor erzählen, den sogar ich nicht erlegen konnte. Ajeck hier nennt diesen verschlagenen Raptor Tethis.\n\nWenn Ihr Euch als <wahrer Meister/wahre Meisterin> erweisen wollt, dann erlegt Tethis und bringt mir seine Kralle. Es wäre eine Leistung, die bisher noch keinem anderen Großwildjäger gelungen ist.", sourceObjective = "Hemet Nesingwary Jr. möchte, dass Ihr Tethis tötet, einen schwer fassbaren, gefährlichen Raptoren des Schlingendorntals.", progress = "Wie läuft die Jagd auf Tethis? Ihr habt sie wohl den ganzen Weg bis hierher ins Lager verfolgt, wie?", completion = "Meister {name}, der Raptorentöter!\n\nKlingt gar nicht schlecht, wie?", sourceObjectiveStatus = "unverified-source-field" }
quests[198] = { id = 198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte für den Gefreiten Thorsen", description = "Hmm. Ja, es gibt tatsächlich etwas, das Ihr tun könntet. Leutnant Doren und seine Leute oben im Norden warten auf ihre turnusmäßige Vorratslieferung von uns.\n\nDie Vorräte wurden noch nicht bei ihnen abgeliefert und jetzt, wo die Trolle ständig angreifen, brauche ich jemanden, der das erledigt. Dorens Lager liegt im Nordwesten der Straße, dort, wo man vom Dämmerwald aus ins Schlingendorntal kommt. Gebt die Vorräte dem Gefreiten Thorsen. Wenn er nicht im Lager ist, dann patrouilliert er südlich davon. Er wird sie in Empfang nehmen und verstauen.\n\nAber dass eines klar ist: Wenn Ihr versagt, dann müsst Ihr mir Ersatz leisten.", sourceObjective = "Liefert die verschiedenen Goblinvorräte bei dem Gefreiten Thorsen ab.", progress = "Ja? Was wollt Ihr? Oh, Vorräte von den Goblins. Seltsam, dass ein {race} das Paket abliefert, normalerweise schicken sie einen ihrer eigenen Leute. Na, egal. Ihr habt die doch wohl hoffentlich nicht angefasst? Gut, gut... Wir wollen ja nicht, dass unseren Minen irgendwas passiert, oh nein.", completion = "Mit diesen Landminen können wir uns gegen diese Bestie Kurzen und seine Männer verteidigen. Danke, dass Ihr sie uns gebracht habt. Wenn Ihr noch weitere Arbeit möchtet, dann kann ich vermutlich etwas finden, was Ihr tun könntet. Dann müsstet Ihr Euch auch nicht mit diesen Goblins abgeben, wie?", sourceObjectiveStatus = "unverified-source-field" }
quests[199] = { id = 199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dunkle Bedrohung", description = "Ihr nehmt eine Probe von dem sonderbar riechenden Pulver.", sourceObjective = "Kehrt zu Chefingenieur Hinderweir zurück und zeigt ihm den Hinweis, den Ihr entdeckt habt.", progress = "Habt Ihr irgendwelche Hinweise finden können, {name}?", completion = "Diese Entdeckung ist alarmierend und das ist noch milde ausgedrückt!", sourceObjectiveStatus = "unverified-source-field" }
quests[200] = { id = 200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buchhalter Herod", description = "Wenn Kurzen Thorsens Geheimnis kennt, dann haben wir einen Spion in unseren Reihen. Wir müssen herausfinden, wie das Geheimnis verraten werden konnte!\n\nThorsens Kontaktperson in Kurzens Lager war der Buchmacher Herod. Herod ist Kurzens Nachschubsoffizier und weiß alles über den Betrieb in Kurzens Truppenlager. Wenn Ihr Herods Unterlagen oder Aufzeichnungen beschaffen könntet, fänden wir vielleicht heraus, wie Thorsen entdeckt werden konnte.\n\nAls wir noch unter Kurzen dienten, war das Büro des Buchmachers im oberen Stock des einzigen zweistöckigen Gebäudes im Lager. Seine Aufzeichnungen sind vermutlich immer noch dort zu finden.", sourceObjective = "Findet Buchmacher Herods Aufzeichnungen.", completion = "Dies sind Buchhalter Herods Notizen und Aufzeichnungen.\n\nDarunter befinden sich: eine Liste mit Vorräten, die hier gelagert werden, Materialanforderungen von Colonel Kurzen sowie verschiedenste Briefe und Korrespondenz.", sourceObjectiveStatus = "unverified-source-field" }
quests[201] = { id = 201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung des Lagers", description = "Ich habe Berichte gehört, nach denen eine Gruppe von Jägern ihr Lager flussaufwärts vom Bergbaucamp der Venture Company am Nazferitisee aufgeschlagen hat. Das wäre mir normalerweise völlig egal, aber ich habe gehört, dass Hemet Nesingwary Jr. einer der Jäger dort sein soll. Das ist zwar absolut unwahrscheinlich, aber... na ja, er hat sehr gute Beziehungen, wenn Ihr wisst, was ich meine, und man kann nie vorsichtig genug sein.\n\nWollt Ihr nicht hin und Euch das Lager einmal anschauen, {name}, und sehen, was die vorhaben?", sourceObjective = "Lokalisiert das Jägerlager und teilt dann Krazek in Beutebucht mit, wo es sich befindet.", completion = "Hmmm, dann waren die Informationen, die ich hatte, also wieder einmal richtig, wie meistens. Interessant. Na, ich denke nicht, dass die Jäger für unsere Unternehmung eine Bedrohung oder einen Störfaktor darstellen, aber vielleicht haben sie ja Bedarf an einigen unserer ausgezeichneten Produkte. Hmmm...", sourceObjectiveStatus = "unverified-source-field" }
quests[202] = { id = 202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Colonel Kurzen", description = "Ihr habt Euren Wert wieder und wieder unter Beweis gestellt und Euer Einfallsreichtum scheint sich mit dem von Kurzen selbst messen zu können. Ihr könntet die Rettung für unseren Rebellentrupp sein... falls Ihr Euch gegen Kurzen stellen und siegen könnt!\n\nEr erteilt die Befehle an seine Männer von tief aus dem Vorratslager heraus. Ihr müsst Euch Zutritt zu dieser Höhle verschaffen, an seinen Verteidigern vorbei, und dann Kurzen und seinen Führungsoffizieren gegenübertreten.\n\nLebt wohl, {name}. All meine Hoffnung, ebenso das Schicksal meiner Männer, ruht in Euren Händen.", sourceObjective = "Tötet 6 von Kurzens Elitesoldaten, 4 von Kurzens Stabschefs und bringt Kurzens Kopf ins Rebellenlager zu Leutnant Doren.", progress = "Wage ich zu hoffen, dass Kurzen und seine Verteidiger tot sind, {name}?", completion = "Ich hatte den Berichten nicht glauben wollen, hatte kaum zu hoffen gewagt, aber Ihr bringt uns jetzt den Beweis... Kurzen und seine Führungsoffiziere sind tot. Ihr habt uns gerettet!\n\nIn diesem Dschungel wimmelt es nur so von den unterschiedlichsten Gefahren, doch keine von ihnen verfügt über die unbarmherzige Intelligenz, die Kurzen eigen war. Jetzt, wo er nicht mehr ist, können wir alle aufatmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[203] = { id = 203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zweite Rebellion", description = "Wir kämpfen einen aussichtslosen Kampf gegen Colonel Kurzen. Nicht nur, dass der Mann ein brillanter Taktiker ist, seine Männer sind uns auch noch zahlenmäßig mindestens 10 zu 1 überlegen! Um überleben zu können, müssen wir seine eigenen, auf Heimlichkeit basierenden Taktiken gegen ihn anwenden.\n\nBetretet sein Lager im Osten und tötet seine Leute. So viele Ihr könnt. Und verschwindet wieder, bevor seine Verstärkung Euch in die Zange nehmen kann.", sourceObjective = "Tötet 15 von Kurzens Dschungelkämpfern.\n\nKehrt ins Rebellenlager zu Unteroffizier Yohwa zurück.", completion = "Gut gemacht. Der Verlust dieser Dschungelkämpfer wird den Druck, dem unser Lager ausgesetzt ist, etwas verringern.\n\nAber wollt Ihr Euch immer noch mit uns zusammentun, jetzt, wo Ihr einen Vorgeschmack darauf bekommen habt, was für einer Streitmacht wir uns gegenübersehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[204] = { id = 204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Medizin", description = "Um überhaupt eine Chance gegen Kurzen zu haben, müssen wir ihm die Möglichkeit nehmen, seine Truppen zu heilen. Er hat um sich eine große Anzahl an Medizinmännern versammelt, die seine Streitkräfte mit Dschungelarzneien heilen und unsere Kämpfer mit Giftfarnextrakt vergiften.\n\nWir brauchen diese Arzneien und Extrakte für uns selbst. Sucht in Kurzens Truppenlager: Seine Medizinmänner und Dschungelkämpfer haben die Arzneien und die Extrakte werden vermutlich irgendwo in den Vorratskisten im Lager verstaut sein.", sourceObjective = "Bringt Unteroffizier Yohwa im Rebellenlager 7 Dschungelarzneien und 1 Giftfarnextrakt.", progress = "Ich warte auf die Arzneien und den Extrakt, {name}.", completion = "Gut gemacht, {name}. Dank dieser Arzneien werden mehr von uns am Leben bleiben und weiterkämpfen können. Und mit dem Extrakt können wir unsere eigenen Arzneien herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[205] = { id = 205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollhexerei", description = "Während ich die Legenden studiere, die Ihr beschafft habt, sammelt bitte für mich die Gerätschaften der bösen Trollmagie. Begebt Euch in das Gebiet der Schädelspaltertrolle, eines zweiten Stammes weit entfernt im Süden, und beschafft Euch dort Fetische der Schädelspalter von ihren Hexendoktoren und Mystikern.", sourceObjective = "Bringt Bruder Nimetz 4 Fetische der Schädelspalter ins Rebellenlager.", progress = "Habt Ihr die Fetische bekommen, {name}? Vielleicht liegt ja in ihnen das Geheimnis von Kurzens Entartung verborgen... Ich muss es wissen!", completion = "Vielen Dank. Ich werde diese Fetische studieren und sehen, ob sie vielleicht das Geheimnis von Kurzens Wandlung zum Bösen in sich tragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[206] = { id = 206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mai'Zoth", description = "Kurzen mag vielleicht tot sein, doch das, was ihn zum Bösen trieb, ist noch am Leben! Mittels meiner Studien habe ich Folgendes entdeckt: Ein Ogermagier namens Mai'Zoth lebt in einem Ogerhort in den östlichen Bergen des Schlingendorntals. Gerüchten zufolge wendet er Magie an, mit deren Hilfe er in die Gedanken anderer eindringen und diese kontrollieren kann, und ich bin mir sicher, dass er es war, der Kurzen verderbt hat.\n\nBleibt Mai'Zoth am Leben, dann beeinflusst er vielleicht noch andere und vielleicht würde dann sogar ein zweiter Kurzen entstehen.\n\nTötet ihn und bringt mir sein Gedankenauge, das Artefakt, mit dem er andere Wesen verdirbt.", sourceObjective = "Bringt das Gedankenauge zu Bruder Nimetz ins Rebellenlager.", progress = "Ich gebe Euch meinen Segen mit auf den Weg. Denn nur Mai'Zoths Bösartigkeit kommt seiner Stärke gleich.", completion = "Ah! Ihr habt es geschafft! Ihr seid ein mächtiger Verbündeter des Guten;, {name}. Möge Eure Kraft niemals schwinden!\n\nIch werde dieses Gedankenauge studieren und versuchen herauszufinden, ob es vielleicht für die Sache des Guten verwendet werden kann. Wenn nicht... dann muss es zerstört werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[207] = { id = 207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis um Kurzen", description = "Colonel Kurzen war einst ein großer, ein edler Mann - ich muss herausfinden, wie es zu seiner Entartung kommen konnte! Es ist möglich, dass er dem Einfluss von Trollmagie unterliegt. Um diesen Verdacht zu bestätigen, muss ich einige ihrer Legenden studieren.\n\nIn den Trollruinen des Schlingendorntals liegen 4 Schrifttafeln versteckt. Ich muss wissen, was auf diesen Tafeln geschrieben steht! Schreibt die Zeichen ab, die Ihr auf den Tafeln findet, und bringt mir die Abschriften.\n\nDie erste Schrifttafel befindet sich in den Ruinen von Bal'lal, die zweite im finsteren Riff und die dritte und vierte Schrifttafel findet Ihr in den Ruinen von Zul'Kunda.", sourceObjective = "Findet die 4 Schrifttafeln und bringt ihre Legenden zu Bruder Nimetz zurück.", progress = "{name}! Habt Ihr die Troll-Legenden? Ich muss ihre Geheimnisse erfahren!", completion = "Ich danke Euch, {name}. Ich werde diese Legenden studieren und versuchen herauszufinden, ob es eine Verbindung gibt zwischen den Trollen und dem Bösen, das Colonel Kurzen befallen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[208] = { id = 208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großwildjagd", description = "{name}, Ihr seid <ein Jäger, der/eine Jägerin> die; unserer Gesellschaft wahrlich würdig ist. Von den Schlachtfeldern von Lordaeron bis in den tiefsten Dschungel hinein habe ich selten jemanden gesehen, der so geschickt mit den Waffen umgegangen ist wie Ihr.\n\nIhr habt die furchterregende Sin'Dall, den schwer fassbaren Bag'thera und die tückische Tethis erlegt. Doch die wahre Trophäe ist der Kopf von König Bangalash. Dieser weiße Tiger ist der Grund, warum ich hier bin. Ich habe schon seit geraumer Zeit ein Auge auf ihn geworfen. Wenn Ihr König Bangalash tötet, dann steht ein für alle Mal fest, dass Euer jägerisches Können von niemandem übertroffen wird.", sourceObjective = "Hemet Nesingwary Jr. möchte, dass Ihr ihm den Kopf von König Bangalash, dem großen weißen Tiger, bringt.", progress = "Ah, wie ich sehe, seid Ihr zurück, alter Junge. Auch mich hat König Bangalash schon oft dazu gebracht, dass ich auf Händen und Füßen ins Lager zurückgekrochen kam. Haltet durch.", completion = "Verdammt gut gemacht! Ausgezeichnet! Glückwunsch, {name}! Ihr wart erfolgreich, wo andere versagt haben.\n\nIch fühle mich geehrt, dass Ihr ein Teil unserer großartigen Jagdgesellschaft hier seid. Niemand wird jemals Euer Können in Bezug auf das Jagen und Fährtenlesen in Frage stellen!\n\nEuch gebührt Beifall, sage ich! Beifall!", sourceObjectiveStatus = "unverified-source-field" }
quests[209] = { id = 209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hauer der Schädelspalter", description = "Es ist teuer und anstrengend, genug Tiger zu töten, um damit den Bedarf an Tigerzähnen für den Export auf die Inseln in den südlichen Meeren decken zu können. Glücklicherweise haben wir eine gewisse Technik entwickelt, mit deren Hilfe wir aus einfachem hornähnlichen Material nicht nachweisbare Fälschungen herstellen können.\n\nErstaunlicherweise eignen sich die Hauer von Schädelspaltertrollen dafür am besten.\n\nUnd bevor Ihr irgendwas sagt - was der Käufer nicht weiß, macht ihn nicht heiß, hab ich nicht Recht? Bringt mir so viele Hauer wie möglich, damit wir mit der monatlichen Lieferung anfangen können!", sourceObjective = "Besorgt 18 Hauer der Schädelspalter und bringt sie zu Kebok.", progress = "Zähe Biester, was? Also, habt Ihr was für mich? Tut mir ja Leid, dass ich so ungeduldig bin, aber die Sache ist mir ein ziemlicher Dorn im Auge, solange sie nicht erledigt ist. Also?", completion = "Ah, gute Arbeit, gute Arbeit! Bäh, Ihr hättet sie ja wohl doch ein bisschen sorgfältiger säubern können, vor allem das... Na, egal, ganz egal! Ich danke Euch, {name}, unsere Unternehmung wird dank Eurer Hilfe zweifellos ihren Ausstoß und ihre Produktivität steigern können! Gut, gut, und nun zu anderen Angelegenheiten...", sourceObjectiveStatus = "unverified-source-field" }
quests[210] = { id = 210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochen mit Krazek", description = "Meistens bin ich es, der hier im Lager kocht. Und das war auch immer ganz schön viel Arbeit, bis ich von einem Goblinhändler in Beutebucht einen mechanischen Kochtopf gekauft habe. Der Topf ist einfach unglaublich. Er hat mir unzählige Stunden Arbeit erspart - bis er kaputtgegangen ist!\n\nKönnt Ihr den Topf dem Goblin zurückbringen, damit er ihn mir repariert? Der Händler heißt Krazek.", sourceObjective = "Bringt Krazeks Spezialtopf zu Krazek, dem Goblin.", progress = "Hallo! Ihr habt etwas für mich?", completion = "Ah ja, das ist einer von Krazeks Spezialtöpfen! Eine geniale Erfindung, aber bisweilen bricht eine Feder oder das Getriebe gerät aus dem Tritt oder so was in der Art. Lasst mich mal sehen, was mit dem hier los ist...\n\nAha! Die Dampfbeschickungsvorrichtung ist völlig verrostet, die Gelenkdichtung ist rissig und dem Fobulator fehlen Zähne. Es wundert mich, dass der Topf in diesem Zustand überhaupt irgendetwas kochen konnte!\n\nOb ich ihn reparieren kann? Natürlich kann ich ihn reparieren!\n\nAber das kostet. So etwas kostet immer, oh ja...", sourceObjectiveStatus = "unverified-source-field" }
quests[211] = { id = 211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weh dir, Andorhal", description = "Endlich ist die Zeit gekommen Andorhal anzugreifen und den Lich, der die Stadt kontrolliert, zu vertreiben.\n\nDer Lich - Araj der Beschwörer - herrscht von innerhalb der Ruinen der Stadt aus. Er wird von zahlreichen Angehörigen der Geißel bewacht, die über die Überreste des Stadtzentrums wachen, auch sein Gefolge an Leibwächtern ist ausgezeichnet. Ihr werdet einige Verbündete brauchen, um auch nur einen Hauch von einer Chance zu haben, ihn stellen zu können.\n\nVernichtet Araj, {name}, und bringt mir einen Splitter seines Phylakteriums als Beweis!", sourceObjective = "Bringt den Splitter von Arajs Phylakterium zu Kommandant Ashlam Ehrenschlag am Zugwindlager in den westlichen Pestländern.", progress = "Ihr habt Euren Auftrag erhalten, {name}. Habt Ihr einen Splitter vom Phylakterium des Lichs als Beweis, dass die Tat vollbracht ist?", completion = "Ihr habt es geschafft! Araj... der Lich ist endlich besiegt!\n\nIhr habt der Allianz heute einen gewaltigen Dienst erwiesen, {name}. Eure Tapferkeit und Hartnäckigkeit sind ein Beispiel dafür, was es heißt, ein wahrer Held zu sein. Bitte - nehmt dies als ein Zeichen für alle, die Euch sehen, auf dass sie wissen, dass Ihr für die Allianz einen unsterblichen Sieg errungen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[212] = { id = 212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kalte Mahlzeit", description = "Eines meiner berühmtesten Gerichte ist gekühlter Basilisk an Limonenvinaigrette. Das Problem ist nur: Das Fleisch lässt sich unmöglich frisch halten und ich muss das Gericht heute Abend anlässlich des Geburtstags eines Edelmannes servieren!\n\nWenn Ihr mir also schnell einen gekühlten Basiliskenschenkel von einem frisch getöteten Kaltaugenbasilisken bringen könnt, dann schulde ich Euch ein Festessen, das eines Königs würdig wäre!\n\nKaltaugenbasilisken streifen durch die Stranddünen im Nordwesten des Schlingendorntals, also habt Ihr eine lange Reise vor Euch. Und macht schnell!", sourceObjective = "Tötet einen Kaltaugenbasilisken, beschafft Euch einen gekühlten Basiliskenschenkel und bringt ihn Angus Stern im Blauen Eremiten.", progress = "{name}! Habt Ihr den Schenkel? Ich muss bald anfangen, ihn zuzubereiten, sonst ist das ganze Bankett ruiniert!", completion = "Ah ja, der eignet sich prächtig! Vielen, vielen Dank!\n\nWenn Ihr mich jetzt entschuldigen wollt, ich muss diesen Schenkel hacken, marinieren und für das Bankett garnieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[213] = { id = 213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindliche Übernahme", description = "Diesmal ist er zu weit gegangen! Schlimm genug, dass Gelriz dabei ist, die von den Handelsbaronen eingesetzten Moguln rauszudrängen, jetzt versucht er auch noch, den berüchtigtsten aller Piraten mit hineinzubringen!\n\nDas lässt Revilgaz sich nicht bieten und er hat mir aufgetragen, das Problem auf meine Weise zu lösen.\n\nWas meine Weise ist? Diebstahl, ganz einfach. Die Geologen der Venture Company in der Nähe des Nazferitisees zeigen ein auffälliges Interesse an den seltsamen blauen Kristallen, die sie bisweilen in den Minen finden. Bringt mir einige Proben dieser Steine von den Geologen; es ist mir völlig egal, was Ihr tun müsst, um an sie heranzukommen.", sourceObjective = "Beschafft 8 gerommelte Kristalle und bringt sie nach Beutebucht zu Kebok.", progress = "Ich brauche diese Steine, {name}, egal, zu welchen Mitteln Ihr greift! Tut es einfach und erspart mir die Details!\n\nWas zählt, ist das Ergebnis, {name}, nicht mehr und nicht weniger.", completion = "Faszinierend. Dass die Kristalle mit dieser Methode gerommelt wurden, kann nur bedeuten, dass die Company sie als eine Art Treibstoff oder Katalysator verwenden will. Viel mehr als das weiß ich auch nicht. Wir werden Proben davon zu Oberchemiker Gigglefont schicken müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[214] = { id = 214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rote Seidenkopftücher", description = "Es ist kein Geheimnis, dass das Markenzeichen der Defiasbande ihre roten Kopftücher sind. Aber wir haben herausgefunden, dass das Material, aus dem diese Kopftücher gemacht sind, den Rang des Bandenmitglieds bezeichnet.\n\nJetzt, wo wir das wissen, möchte ich, dass Ihr so viele hochrangige Mitglieder der Defias eliminiert, wie Ihr könnt. Die Bandenmitglieder mit der höchsten Position findet Ihr zweifellos in van Cleefs Geheimversteck. Wenn Ihr fertig seid, bringt mir 10 rote Seidenkopftücher zum Beweis, dass sie tot sind, dann werde ich Euch belohnen. Viel Glück, {name}.", sourceObjective = "Späherin Riell am Turm auf der Späherkuppe möchte, dass Ihr ihr 10 rote Seidenkopftücher bringt.", progress = "Habt Ihr unser Land etwas sicherer vor der Defiasbande gemacht? Wenn ja, dann zeigt mir 10 rote Seidenkopftücher zum Beweis.", completion = "Gut gemacht, {name}! Im Namen der Volksmiliz verneige ich mich vor Euch angesichts Eures Einsatzes. Bald schon werden wir, mit der Hilfe von tapferen Leuten wie Euch, dieses Land seinen Bewohnern zurückgeben können.", sourceObjectiveStatus = "unverified-source-field" }
quests[215] = { id = 215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse im Dschungel", description = "Danke, dass Ihr mich gerettet habt, {name}. Ich weiß, wie es aussieht, aber lasst mich bitte erklären!\n\nIch hatte von Leutnant Doren den Auftrag erhalten, mich wieder Kurzens Männern anzuschließen. Ich sollte sie ausspionieren und den Rebellen Informationen bringen, die sie bitter benötigen. Was Ihr hier miterlebt habt, war das, was ich für meine Chance hielt, Kurzens Truppenlager zu infiltrieren. Ich habe mich geirrt und ich muss Euch nochmals danken, dass Ihr mich gerettet habt.\n\nDiese Mission war streng geheim, Ihr dürft also niemandem davon erzählen. Aber wenn Ihr mit Doren sprecht, dann wird der Euch alles erklären.", sourceObjective = "Sprecht im Rebellenlager mit Leutnant Doren.", completion = "Ja, es stimmt, was Thorsen Euch erzählt hat. Ihr müsst das absolut vertraulich behandeln. Einst waren wir Rebellen Colonel Kurzen bis zum Äußersten ergeben. Aber Kurzen erwies sich als so verderbt, dass unsere Loyalität ihm gegenüber sich in Zorn verwandelte. Wenn es bekannt würde, dass Gefreiter Thorsen kürzlich Verbindung zu Kurzens Männern hatte, dann würden wir ihn eines schönen Morgens mit durchgeschnittener Kehle vorfinden.\n\nMeines Wissens nach hatten nur Sergeant Yohwa, Thorsen und ich selbst Kenntnis von Thorsens Auftrag. Aber es muss noch eine weitere Person geben. Einen Verräter.", sourceObjectiveStatus = "unverified-source-field" }
quests[216] = { id = 216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hart auf hart", description = "Die Distelfellfurbolgs bedrohen unsere Expansion! Das Lager der Distelfelle östlich von uns blockiert den Weg zwischen uns hier und dem Splitterholzposten. Dieser Weg würde das Dorf Astranaar umgehen; ohne ihn überlassen wir der Allianz eine zusätzliche Möglichkeit der Ausbreitung.\n\n{name}, wir dürfen keine Lücke in unseren Expansionspfaden erlauben!\n\nBegebt Euch ins Distelfelllager und dünnt die Furbolgs etwas aus. Ihr werdet für diese Aufgabe entschädigt werden, aber noch viel wichtiger ist, dass Ihr Eure Pflicht der Horde gegenüber tun werdet.", sourceObjective = "Schaltet 8 Rächer der Distelfelle und 8 Schamanen der Distelfelle aus. Man findet sie am häufigsten östlich vom Zoramstrand im Lager der Distelfelle. Wenn das erledigt ist, kehrt zu Karang Amakkar beim Außenposten von Zoram'gar im Eschental zurück.", progress = "Habt Ihr den Kampf zu den Distelfellen getragen? Mit einem freien Weg zwischen unseren Stützpunkten erhöhen sich unsere Chancen erheblich, ganz Ashenvale für uns zu beanspruchen.", completion = "Gut gemacht, {class}, gut gemacht! Ich werde weiterhin Truppen aussenden, um die Population der Furbolgs niedrig zu halten, aber ich kann auf mindestens einen weiteren Pfad zählen, der frei von Verstrickungen der Allianz ist. Die Eroberung von Ashenvale durch die Horde ist jetzt in vollem Gang!\n\nIhr habt Euch heute Eure Bezahlung verdient. Ich ziehe den Hut vor Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[217] = { id = 217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Länder des Königs", description = "{name}, unsere Späher haben den Anführer des jüngsten Eindringens der Troggs ermitteln können. Es scheint, als folgten diese Bestien am Loch Modan einem Häuptling namens Grawmug. Grawmug wird jedoch aufs Schwerste bewacht. Zwei seiner Elitewachen, Knirscher und Muskelprotz, weichen nie von seiner Seite.\n\nWenn Ihr Euch dem gewachsen fühlt, {name}, dann möchte ich, dass Ihr das Attentat auf Grawmug und seine beiden Schläger anführt. Wenn die Führungsriege der Troggs tot ist, dann haben wir vielleicht eine Chance, diese Bestien wieder unter die Erde zu treiben.", sourceObjective = "Tötet den Anführer der Troggs, Grawmug, sowie seine beiden Wachen, Knirscher und Muskelprotz, und erstattet dann Hauptmann Rugelfuß im südlichen Wachturm Bericht.", progress = "Grawmug und seine beiden Wachen, Knirscher und Muskelprotz, sind noch immer am Leben. Eure Mission ist nicht beendet, solange noch einer der drei am Leben ist. Das Zwergenreich zählt auf Euch, {name}!", completion = "Ganz ausgezeichnet, {name}! Ihr habt wieder Hoffnung an den Loch Modan gebracht. Jetzt, wo Grawmug tot ist, besteht eine größere Chance, dass die Troggs aus unserem Land vertrieben werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[218] = { id = 218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gestohlene Tagebuch", description = "Mein Tagebuch! Sie haben es in die Höhle gebracht. Der, der es hatte, war ein großer Kerl mit seltsamen Zeichen auf der Haut und im Gesicht. Viel mehr konnte ich leider nicht sehen.\n\nIhr hattet ja mit den Trollen Erfolg, vielleicht könntet Ihr es mir wiederbeschaffen?", sourceObjective = "Grelin Weißbart möchte, dass Ihr Grik'nir den Kalten tötet und ihm sein Tagebuch wiederbeschafft.", progress = "{name}! Glück gehabt?", completion = "Großartig, {name}! Vielen Dank, dass Ihr mein Notizbuch zurückgeholt habt. Nun, es scheint, als sei das Trollproblem hier im Coldridgetal unter Kontrolle und als müssten wir uns nicht allzu viele Sorgen machen.\n\nNachdem ich meinem Bericht den letzten Schliff gegeben habe, werde ich jemanden brauchen, der ihn meinem Bruder Senir bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[219] = { id = 219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisst", description = "Freunde der Allianz! Endlich!\n\nHelft... bitte... \n\nDas Letzte, an das ich mich erinnere, ist, dass diese abscheulichen Orcs unser Regiment überwältigten. Die meisten Männer wurden getötet; ich selbst erhielt einen Schlag an den Kopf und alles wurde schwarz. Jetzt werde ich in dieser Höhle gefangen gehalten. Bitte helft mir; ich bin schwer verletzt.\n\nIch brauche Hilfe auf dem Weg zurück in die Stadt... bitte... Ihr seid meine letzte Hoffnung...", sourceObjective = "Beschützt Korporal Keeshan auf dem Rückweg ins Rotkammgebirge.", progress = "Ja?", completion = "Ihr habt dem Königreich gut gedient, {class}. Danke, dass Ihr Corporal Keeshan bei seiner Flucht vor den gefürchteten Orcs des Blackrockklans geholfen habt. Eure tapferen Taten an diesem Tag sollen nicht unbelohnt bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[220] = { id = 220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Islen hat noch eine weitere Aufgabe für Euch, ehe Ihr zur Belohnung Euer nächstes Totem erhaltet. Die Phiole mit Wasser, die ich Euch gegeben habe, wird für diese Aufgabe gebraucht, um was auch immer es sich dabei handeln mag.\n\nGeht nun und sucht sie auf. Wir werden uns eines Tages wieder begegnen.", sourceObjective = "Bringt die Phiole mit reinstem Wasser zu Islen Wasserdeuter am Tidustritt im Brachland.", progress = "Da seid Ihr ja wieder, {name}. Ihr seht gut aus.\n\nWas führt Euch schon so bald zu mir zurück?", completion = "Ah, eine Phiole mit Wasser, von Brine geschaffen und gesegnet und von keinem Geringeren eingesammelt als Euch selbst.\n\nDie Flüssigkeit in dieser Phiole ist das wichtigste Element, um ein Sapta für Euch herzustellen, doch sie findet auch für eine weitere Aufgabe Verwendung.\n\nMit dem Sapta, das ich für Euch herstelle, solltet Ihr die Wassergeister am Schrein im Silberwald, südlich von Undercity, sehen. Was die verbleibenden Tropfen betrifft, nun, zu den verbleibenden Tropfen sage ich Euch etwas, sobald Ihr glaubt, dass Ihr bereit seid.\n\nSeid Ihr auf eine weitere Reise vorbereitet, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[221] = { id = 221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in den Wäldern", description = "Habt Ihr vielleicht schon festgestellt, dass einige größere Worgen zusammen mit den Schattenwirkern im Wald herumziehen? Nach allem, was wir wissen, machen diese Dunkelläufer den Großteil der Worgen-Population aus.\n\nAuf meinen Wanderungen habe ich außerdem festgestellt, dass sie in den verlassenen Obsthain im Südwesten der Stadt eingefallen sind. Diese Worgen sind etwas zäher als die letzten, denen Ihr begegnet seid.\n\nAlso seht Euch vor.", sourceObjective = "Tötet für Calor aus Dunkelhain 12 Dunkelläufer der Nachtheuler.", progress = "Schon zurück, {name}? Ich hoffe, Ihr seid nicht gekommen, um mir zu sagen, dass Ihr aufgegeben habt?", completion = "Gegen die Dunkelläufer habt Ihr Euch gut geschlagen, {name}. Aber es scheint, als sei ihre Zahl schier unerschöpflich. Ganz gleich, wie viele wir töten, es schießen immer mehr aus dem Boden, um ihre Reihen wieder zu schließen.\n\nWelche böse Macht zieht sie nur hierher? Warum sind sie gekommen, um unser unglückliches Land zu plagen?\n\nDoch ich vertraue auf Meister Carevin. Zweifellos wird er der Sache auf den Grund kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[222] = { id = 222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in den Wäldern", description = "Eure früheren Leistungen haben mich überzeugt, dass Ihr in der Lage seid, Euch mit den zähesten Worgen zu messen, die sich in den Wäldern eingenistet haben.\n\nVon all den Worgen, die plötzlich hier zu finden sind, haben sich die Faulreißer und die Besudelten als die gefährlichsten herausgestellt. Sie haben sich in der Nähe einiger Höhlen und in der Mine im Süden niedergelassen.\n\nNoch aus weiter Entfernung sieht man die Lichter ihrer Feuer...", sourceObjective = "Tötet für Calor aus Dunkelhain 8 Faulreißer der Nachtheuler und 8 besudelte Nachtheuler.", progress = "Furchterregende Biester, nicht wahr? Doch fürchtet Euch nicht, {name}, die, die für das Licht kämpfen, werden niemals fallen!", completion = "Ich will ganz ehrlich mit Euch sein, {name}. Ich hatte nicht geglaubt, dass Ihr so weit kommen würdet. Aber ganz offensichtlich seid Ihr als {class} nicht zu unterschätzen. Und wenn Ihr Euch ganz offiziell Meister Carevins Sache anschließen wollt, dann verfasse ich gern ein Empfehlungsschreiben für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[223] = { id = 223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in den Wäldern", description = "Hier, bitte schön, {name}. Bringt Meister Treuwein diese Nachricht.\n\n<Schnell zieht er ein Stück verblasstes Pergament hervor und reicht es Euch.>\n\nNoch ein paar mehr wie Ihr, dann sind wir bald mehr Kämpfer als die Nachtwache! Vielleicht können wir dann das Werk vollenden, an dem wir wenigen uns heute noch vergebens abmühen.", sourceObjective = "Bringt Calors Notiz zu Jonathan Treuwein.", progress = "Ja, was wollt Ihr? Macht schnell, es gibt wichtige Dinge, um die ich mich kümmern muss.", completion = "Vergebt mir den kühlen Empfang, {name}, aber wie Ihr sicher sehen könnt, bin ich ein viel beschäftigter Mann. Ganz offensichtlich habt Ihr Calor beeindruckt - ich kann Euch versichern, das ist eine beachtliche Leistung - und er hat Euch seine Empfehlung ausgesprochen.\n\nEs sind äußerst üble Gestalten unterwegs, {name}, und wir können die Hilfe von jedem gebrauchen, der seinen Wert bewiesen hat. Wir kämpfen gegen Dämonen, die Untoten und alle, die ihnen Hilfe gewähren. Seid wachsam, seid auf der Hut und traut niemandem, der unserer Sache nicht unterstützt.\n\nRuhm unter dem Licht!", sourceObjectiveStatus = "unverified-source-field" }
quests[224] = { id = 224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Länder des Königs", description = "Wir müssen den Loch beschützen, {name}! Jetzt, wo so viele der Soldaten des Königs tapfer auf weit entfernten Schlachtfeldern kämpfen, sind wir nahe davor, an der Heimatfront überwältigt zu werden. Aus jedem Spalt graben sich Troggs an die Oberfläche! Die Troggplage stellt für Eisenschmiede die größte Gefahr dar. Diese widerwärtigen Mutanten müssen vernichtet werden.\n\nIhr, <tapferer Abenteurer/tapfere Abenteurerin>, müsst Euch für uns hinauswagen und der Bedrohung durch die Troggs ein Ende bereiten. Erschlagt 10 Splittersteintroggs und 10 Späher der Splittersteintroggs und erstattet dann wieder Bericht.", sourceObjective = "Gebirgsjäger Feuerkiesel vom südlichen Wachturm möchte, dass Ihr 10 Splittersteintroggs und 10 Späher der Splittersteintroggs tötet.", progress = "Der Loch Modan wird belagert, {name}! Wir sind auf jedes einsatzfähige Mitglied der Allianz angewiesen. Habt Ihr schon 10 Stonesplitter-Troggs und 10 Stonesplitter-Späher getötet?", completion = "Gut gemacht, {name}! Ihr habt auf dem Schlachtfeld verblüffenden Mut bewiesen. Mit Leistungen wie den Euren werden wir unseren Krieg gegen die Troggs gewinnen. Ihr habt König Magni gut gedient.\n\nWenn Ihr glaubt, dass Ihr gerade für solche Abenteuer gut geeignet seid, dann würde ich vorschlagen, Ihr sprecht mit Gebirgsjäger Gravelgaw. Der Captain hat ihn auf eine harte Patrouille geschickt, bei der er bestimmt Hilfe gebrauchen kann. Meldet Euch bei Gravelgaw; er ist im Turm gleich beim Eingang.", sourceObjectiveStatus = "unverified-source-field" }
quests[225] = { id = 225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verwitterte Grab", description = "Auf dem verwitterten Grabstein steht einfach:\n\nMORGAN LADIMORE\n\n<Als Ihr den Ort weiter untersucht, stellt Ihr fest, dass die Erde über dem Grab kürzlich umgegraben wurde und dass ein guter Teil der Erde entfernt worden zu sein scheint...>", sourceObjective = "Sprecht in Dunkelhain mit Sirra Von'Indi.", completion = "Morgan Ladimore?\n\nAber ja, natürlich. Seine Geschichte ist lang und traurig. Ich kannte ihn gut, ehe er in den Krieg zog, doch das war das letzte Mal, dass ich ihn gesehen habe. Er war ein guter und edler Mann, doch es nahm ein böses Ende mit ihm.\n\nEinen Moment, ich glaube, ich habe hier etwas, das Euch die Geschichte besser erzählen kann als meine eigene Erinnerung...", sourceObjectiveStatus = "unverified-source-field" }
quests[226] = { id = 226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wölfe sind uns auf den Fersen", description = "Sven und mir stehen jetzt gefährliche Tage ins Haus, wo doch der Totenbeschwörer im Osten sitzt und all das. Und weil wir hier draußen allein sind, müssen wir auch selbst jagen, wenn wir etwas essen wollen. Es kommt mir so vor, als würden jedes Mal, wenn ich mit etwas Fleisch zum Lager zurückgehe, verhungernde oder tollwütige Terrorwölfe aus dem Wald kommen, die auch etwas abhaben möchten. Ja, eines steht fest, das Leben hier draußen ist gefährlich!\n\nAber wenn Ihr einige der Wölfe für uns erledigen könntet, dann wäre das Leben für uns etwas leichter. Meist streunen sie nördlich und östlich von hier herum, in der Nähe des Flusses.", sourceObjective = "Tötet 12 verhungernde Terrorwölfe und 8 tollwütige Terrorwölfe und kehrt dann zu Lars in Svens Lager an der westlichen Grenze des Dämmerwalds zurück.", progress = "Seid Ihr immer noch auf der Wolfsjagd?", completion = "Oh, gut. Ihr habt das Rudel ganz schön reduziert. Und nachdem uns diese Wölfe jetzt nicht mehr an den Fersen hängen, können wir uns wieder damit beschäftigen, wie wir mit Morbent Fel fertig werden.\n\nHier, nehmt ein paar von diesen Blitzstrahlbündeln. Sie werden in der Stadt hergestellt und Sven hat etliche davon geschenkt bekommen, um ihn in seiner Sache zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[227] = { id = 227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgan Ladimore", description = "<Er sucht in den Regalen und kommt mit einem ledergebundenen Buch zurück.>\n\nWenn Ihr mehr wissen wollt, dann fragt Althea. Sie ist diejenige, die in letzter Zeit von dem... Ärger... mit ihm am meisten mitbekommen hat.", sourceObjective = "Sprecht in Dunkelhain mit Kommandantin Althea Schwarzhaupt.", completion = "Morgan Ladimore? Nie gehört.\n\nOh, Ihr meint Mor'Ladim! Dann nehme ich an, Ihr kennt die Geschichte nicht?\n\nNun gut, ich gebe Euch die Kurzfassung. Im Dämmerwald wandert seit einiger Zeit ein wandelnder Untoter namens Mor'Ladim herum. Nach allem, was wir herausfinden konnten, scheint dies der untote Körper von Morgan Ladimore zu sein, von dem Ihr offenbar gehört habt. Er bereitet uns alle möglichen Probleme, greift patrouillierende Wachmänner an und tötet Leute.\n\n<Sie mustert Euch prüfend.>\n\nIhr seht mir fähig genug aus; vielleicht könnt Ihr ihn ja zur letzten Ruhe betten.", sourceObjectiveStatus = "unverified-source-field" }
quests[228] = { id = 228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'Ladim", description = "Meine Späher berichten mir, dass Mor'Ladim durch den ganzen Dämmerwald wandert und auf dem Friedhof einen seltsamen, gewundenen Weg einschlägt. Wir haben ihn hinter dem Haus auf dem Hügel begraben, wisst Ihr, wo das ist?\n\nEs gibt nichts, was ich tun könnte, um Euch zu helfen, aber ich wünsche Euch viel Glück.", sourceObjective = "Tötet Mor'Ladim und bringt seinen Schädel nach Dunkelhain zu Kommandantin Althea Schwarzhaupt.", progress = "Ich kann es verstehen, wenn Ihr Probleme mit ihm habt, {name}. Wir haben einige unserer besten Behüter an Mor'Ladim verloren.", completion = "Ihr habt ihn getötet? Das ist eine beachtliche Leistung, {name}! Im Namen der Bewohner von Dunkelhain und im Namen der Nachtwache danke ich Euch.\n\nÄh, da wäre allerdings noch eine kleine Sache...", sourceObjectiveStatus = "unverified-source-field" }
quests[229] = { id = 229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die überlebende Tochter", description = "Ich hätte Euch dies schon früher sagen sollen...\n\nWie soll ich sagen...\n\nMorgan dachte zwar, dass seine ganze Familie umgekommen sei, aber seine Tochter Sarah Ladimore lebt noch: Sie ist jetzt eine Behüterin. Die... Umstände... unter denen ihr Vater zu Tode gekommen ist, haben sie immer sehr aufgewühlt. Vielleicht könntet Ihr zu ihr gehen und ihr mitteilen, was geschehen ist.", sourceObjective = "Sprecht in Dunkelhain mit Behüterin Sarah Ladimore.", completion = "Ja? Mein Vater...\n\n<Sie schlägt die Augen nieder.>\n\nIch wünschte... ich wünschte, es gäbe etwas, das ich für ihn hätte tun können... Wenn ich nur mit ihm gesprochen hätte, ehe er...", sourceObjectiveStatus = "unverified-source-field" }
quests[230] = { id = 230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Svens Lager", description = "Als Ihr durch den Haufen wühlt, findet Ihr ein kleines, schmutzbeflecktes Buch.\n\nDas Buch hat keinen Titel, aber... es enthält Informationen, die Sven bestimmt interessieren.", sourceObjective = "Bringt das Buch von Svens Hof zu Sven.", progress = "Ihr habt was gefunden? Bitte zeigt es mir...", completion = "<Sven liest in dem Buch, dann schlägt er es heftig zu.>\n\nDie schattenhafte Gestalt, die ich sah, war Zeuge, wie meine Familie um's Leben kam! Es gibt da etliche Fragen, die ich diesem Mann gern stellen würde... wenn ich nur wüsste, wer er ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[231] = { id = 231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Liebe einer Tochter", description = "Hier, nehmt dies und legt es auf sein Grab. Vielleicht... vielleicht weiß er dann irgendwie, dass es mir gut geht und dass keiner von uns ihn für das verantwortlich macht, was geschehen ist.\n\n<Jetzt hat sie Tränen in den Augen, als sie einen Ring von der rechten Hand zieht und ihn Euch übergibt.>\n\nUnd... danke, {name}.", sourceObjective = "Bringt Sarah Ladimores Ring zu Morgan Ladimores Grab.", progress = "Lasst mich in Ruhe...", completion = "<Eine geisterhafte Stimme ertönt im Wind.>\n\nIst das...? Sarah? Kann es sein? Ist sie tatsächlich noch am Leben? Die Last fällt von meinen Schultern...\n\n{name}. Nehmt Archeus, mein Schwert. Jetzt, wo meine Seele ihren Frieden findet, brauche ich es nicht mehr. Es wurde geschmiedet, um Gutes zu tun, und obgleich ich selbst mich als unwürdig erwiesen habe, es zu tragen, werdet vielleicht Ihr das Licht durch es verbreiten.\n\nLys, meine Liebste...", sourceObjectiveStatus = "unverified-source-field" }
quests[232] = { id = 232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurierdienst für Apothekerin Zinge", description = "Die Königliche Apothekenvereinigung benötigt Eure Hilfe. Hört gut zu und wir können beide von meinem Plan profitieren.\n\nApotheker Keifer im nächsten Raum mag... begabt sein..., aber seine Forschungen könnten Früchte tragen, wenn sie von einem gewandten Forscher... oder einer gewandten Forscherin verfolgt würden. Zum Glück bin ich eine solche Forscherin. Bringt diese Bestellung zu Alessandro Luca, dem Eigentümer von Blaumond Dies-und-Das. Er wird Euch ein Testset geben. Wenn Ihr es habt, bringt es zu mir zurück und ich werde Euch Eure Aufgabe im Detail erläutern.", sourceObjective = "Bringt die Bestellung nach Unterstadt zu Alessandro Luca.", progress = "Ja, womit kann ich Euch helfen? Seid Ihr hier, um Geschäfte im Namen der Königlichen Apothekenvereinigung zu machen oder seid Ihr nur hergekommen, um meinen Tag zu verschönern?", completion = "Ah, Zinge benötigt ein Set, was? Es betrübt mich, dass Zinge mich nicht mit ihrem holden Anblick selbst beehrt.\n\nNun gut, ich werde Euch ein Set beschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[233] = { id = 233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Postbeförderung im Eisklammtal", description = "Hm, ich nehme nicht an, dass Ihr mir einen Gefallen tun würdet, <Jungchen/Mädchen>? Heute kam ein Stapel Briefe durch den Pass, aber ich habe nicht die Zeit, sie weiterzuleiten.\n\nSie sind alle an Talin Kühnauge adressiert. Ihr findet ihn ein Stück entlang der Straße im Westen. Er hat sein Lager am gefrorenen See aufgeschlagen.\n\nWas meint Ihr?", sourceObjective = "Liefert den Stapel Briefe bei Talin Kühnauge im Eisklammtal ab.", progress = "Ja? Habt Ihr etwas für mich?", completion = "Danke, ich warte schon seit geraumer Zeit auf diese Briefe.\n\nLeider sind sie aber nicht alle für mich. Dieser Brief ist an Grelin Whitebeard adressiert. Er hält sich nicht allzu weit entfernt auf, wenn Ihr ihm den Brief bringen möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[234] = { id = 234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Postbeförderung im Eisklammtal", description = "Wenn ich mich recht erinnere, hat Grelin sein Lager im Südosten, ein Stück die Straße hinunter. Ich bin sicher, er wartet schon sehnsüchtig auf seine Post.", sourceObjective = "Liefert den Brief bei Grelin Weißbart im Eisklammtal ab.", progress = "Kann ich Euch behilflich sein?", completion = "Ah, ausgezeichnet. Es ist schon eine Weile her, dass ich Nachricht aus Ironforge hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[235] = { id = 235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd im Eschental", description = "Achtung, junge Abenteurer! Die Wildnis des Eschentals erwartet Euch!\n\nDie Horde hat eine starke Präsenz in den Ländern nördlich des Brachlandes aufgebaut. Unsere beiden Außenposten - der Splitterholzposten und der Zoramstrandposten - wollen der Horde zu Ruhm gereichen! Diejenigen, die sich beweisen möchten, sollten dort nach Anleitung suchen. Wichtiger Hinweis: Senani Donnerherz im Splitterholzposten, direkt nördlich des Brachlandes, sucht Abenteurer, die an einer großen Jagd im Eschental teilnehmen wollen!", sourceObjective = "Sprecht mit Senani Donnerherz im Splitterholzposten im Eschental.", completion = "Willkommen an der neuen Grenze, {name}. Ashenvale ist ein Land der unbegrenzten Möglichkeiten, eines, in dem jemand Eurer Art, {class}, jede Menge Gelegenheiten finden wird, seinen Mumm unter Beweis zu stellen. Schaut Euch hier im Außenposten um und begebt Euch auf jeden Fall auch einmal hinaus zum Zoramstrand, denn die Horde hat dort noch einen weiteren Außenposten.\n\nEure Anwesenheit hier sagt mir, dass Ihr gekommen seid, um mehr über die Jagd zu lernen. Hört mir genau zu, und ich werde euch gern mitteilen, was Ihr wissen müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[236] = { id = 236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwüster auftanken", description = "{name}! Wurde auch langsam Zeit, dass Ihr auftaucht. Die Schlacht mag vielleicht zu Ende sein, doch wir müssen uns noch immer auf die nächste vorbereiten. Reist zum Flammenkessel im südöstlichen Teil von Tausendwinter und holt mehrere Stück Immerglut.\n\nDie Glutstücke werden mit Kohle vermengt, um Treibstoff für die Verwüster und Belagerungsmaschinen zu liefern.\n\nOh, eins noch: Falls Ihr zufällig Anhänger der Horde im Flammenkessel sehen solltet, dann zögert nicht, tötet sie und nehmt ihre Glutstücke. Wir können nicht zulassen, dass sie in der nächsten Schlacht im Vorteil sind.", sourceObjective = "Belagerungsmeister Starkhand in der Tausendwinterfestung möchte, dass Ihr zum Flammenkessel geht und den Hordlern dort 10 Stück Immerglut abnehmt.", progress = "Nun? Konntet Ihr die Glutstücke finden? Oder ist Euch die Horde zuvorgekommen und hat Euch weinend zurückgelassen?", completion = "Ausgezeichnet! Das wird helfen, die Flammen des Krieges einige Tage lang zu schüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[237] = { id = 237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Länder des Königs", description = "Gebirgsjäger Feuerkiesel hat nur Gutes über Euch zu berichten gehabt, {race}. Daher werde ich Euch eine Mission von äußerster Wichtigkeit anvertrauen. Wir müssen den Druck auf die eindringenden Troggstreitkräfte aufrechterhalten, bis unsere Brüder, die Zwerge, von der Front der Allianz zurückkehren.\n\nBegebt Euch in die südlichen Hügel und tötet 10 Schädelhauer der Splittersteintroggs und 10 Seher der Splittersteintroggs. Eure Angriffe werden uns etwas Zeit verschaffen. Erstattet Bericht, sobald Ihr die Aufgabe erfüllt habt.", sourceObjective = "Gebirgsjäger Kieselwut im südlichen Wachturm möchte, dass Ihr 10 Schädelhauer der Splittersteintroggs und 10 Seher der Splittersteintroggs tötet und ihm anschließend Bericht erstattet.", progress = "Wir brauchen mehr Zeit, {race}. Ihr habt den Befehl, 10 Stonesplitter-Schädelhauer und 10 Stonesplitter-Seher zu töten. Setzt den Feind unter Druck, bis wir Verstärkung erhalten. Jetzt ist nicht die Zeit für Müßiggang.", completion = "Ihr habt Eure Mission gut erfüllt, {race}. Der König selbst wäre stolz auf Euch.\n\nDie Verstärkung, die uns versprochen war, ist jedoch nie angekommen. Anscheinend ist die Front der Allianz getränkt von dem roten Blut unserer gefallenen Brüder. Die Nachricht von diesen Verlusten hinterlässt einen bitteren Nachgeschmack. Doch wir dürfen nicht zulassen, dass ihr Tod vergeblich war. In diesen finsteren Zeiten müssen wir zusammenstehen und den Ruhm der Allianz wieder aufleben lassen.\n\nSprecht wegen Eurer nächsten Aufgabe mit Gebirgsjäger Wallbang. Wir brauchen Euch jetzt mehr als je zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[238] = { id = 238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurierdienst für Apothekerin Zinge", description = "Das Set ist fertig, {name}. Die Apothekerin Zinge wird es zweifellos so schnell wie möglich haben wollen. Bringt es ihr ohne Verzögerung und lasst sie wissen, dass ich die Kosten für das Set mit auf die Rechnung der Gesellschaft schreiben werde. Richtet ihr bitte außerdem meine wärmsten Grüße aus.\n\nAlso los, steht nicht einfach so rum. So ist nun mal das Leben eines einfachen Kuriers, stimmt's?", sourceObjective = "Bringt das Feldprobenset nach Unterstadt zu Apothekerin Zinge.", progress = "Ja, ich denke, Luca ist genauso beunruhigt wie Ihr. Aber es macht keinen Unterschied - gebt mir das Feldprobenset. Ich muss daran einige Veränderungen vornehmen, damit eine Suche nach den geeigneten Grundmaterialien möglich ist.\n\nIhr habt das Set doch, nicht wahr?", completion = "Gut - es freut mich, mit jemandem zu arbeiten, der darauf achtet, nicht meine Zeit zu verschwenden.\n\nNachdem ich einige Veränderungen an diesem Set vorgenommen habe, könnt Ihr euch auf den Weg machen. Ihr werdet damit einige wichtige Daten für die Aufgabe sammeln, die vor uns liegt.\n\nEs dauert nur einen Augenblick, um diese Veränderungen abzuschließen. Während Ihr wartet, solltet Ihr vielleicht schon einmal darüber nachdenken, was Ihr in die Wüste mitnehmen wollt.\n\nJa, ich sagte \"Wüste\".", sourceObjectiveStatus = "unverified-source-field" }
quests[239] = { id = 239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Weststromgarnison", description = "Die Garnison an unserer westlichen Grenze berichtet von steigenden Aktivitäten der Gnolle und der Diebe. Sie bitten uns um die Entsendung weiterer Soldaten aus Sturmwind... aber wir können einfach keine entbehren!\n\nWenn Ihr helfen könntet - wir könnten die Hilfe wirklich gebrauchen. Geht, sprecht mit Stellvertreter Rainer in der Weststromgarnison und fragt ihn, was getan werden muss.\n\nDie Garnison liegt an der Straße im Westen. Wenn Ihr die Brücke über den kleinen Bach überquert habt, liegt sie auf der rechten Seite.", sourceObjective = "Begebt Euch zur Weststromgarnison und sprecht mit Stellvertreter Rainer.", completion = "Marshal Dughan hat Euch geschickt, wie? Ihr seid zwar nicht in der Armee, aber wenn Dughan Euch geschickt hat, dann soll mir das recht sein.\n\nUnsere Lage hier ist, um es gelinde auszudrücken, angespannt. Ich hoffe, Ihr könnt ein wenig aushelfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[240] = { id = 240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Bibbers", description = "Und voilà - \"Krebs\"-Küchlein à la Grual!", sourceObjective = "Kehrt mit den schwärzlichen Krebsküchlein zu Bibbers zurück.", progress = "Da seid Ihr ja, {name}! Habt Ihr mein Essen gebracht?", completion = "Ah! Danke, {name}. Die waren jetzt genau richtig!\n\nUnd hier, bitte gestattet, dass ich Euch dafür bezahle!", sourceObjectiveStatus = "unverified-source-field" }
quests[243] = { id = 243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ins Feld", description = "Ihr werdet Euch in die Tanariswüste begeben und die Gewebebeschaffenheit der Basilisken, Skorpiden und Hyänen testen, die dort heimisch sind. Beschafft Gewebeproben und untersucht sie mit dem Testset; Ihr müsst davon ausgehen, dass eine Reihe der Proben unnütz sind. Ich benötige von jeder Kreaturenart acht akzeptable Proben.\n\nAußerdem verfügen die Goblins von Gadgetzan über eine Kraftquelle, die mit dieser Art von modifiziertem Set verwendet werden muss. Sprecht mit Chefingenieur Bilgenritzel und erwerbt eine für das Set.\n\nKehrt erst zu mir zurück, wenn Ihr erfolgreich wart.", sourceObjective = "Sprecht in Gadgetzan mit Chefingenieur Bilgenritzel über eine Kraftquelle für das Testset.\n\nBereitgestellter Gegenstand:", completion = "Ah, unsere Kraftquellen vom Typ 4711-FTZ! Normalerweise verwenden wir sie, um Brunnen anzutreiben, aber DANK DER WIDERWÄRTIGEN NOMADEN haben wir im Moment einen Überfluss an Kraftquellen.\n\nNatürlich kann ich Euch eine Kraftquelle für jedes beliebige schändliche Wissenschaftsexperiment besorgen, das Ihr vor mir zu verstecken sucht. Aber das kostet Euch etwas, {race}. In Gadgetzan gibt es nichts umsonst.", sourceObjectiveStatus = "unverified-source-field" }
quests[244] = { id = 244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindringende Gnolle", description = "Seid gegrüßt, {class}. Meine Aufgabe ist es, auf diesem Stück Straße zu patrouillieren. Obwohl die Straße im Augenblick sicher ist, habe ich nördlich und östlich von hier einige Lager von Gnollen gesehen.\n\nSeenhain muss erfahren, dass die Gnollstreitkräfte sich sammeln! Meldet Euch bei Stellvertreter Feldon in Seenhain und berichtet ihm von den Gnollen. Wenn Ihr dies tut, dann wird Feldon Euch bestimmt den Sold eines Spähers zahlen.\n\nGewöhnlich inspiziert Feldon das Gebiet südlich der Brücke nach Seenhain.", sourceObjective = "Erstattet Stellvertreter Feldon Bericht. Zu finden ist er an der Brücke südlich von Seenhain im Rotkammgebirge.", completion = "Rotkammgnolle so nah an Elwynn? Es ist möglich, dass sie kurz vor einem Einfall in unsere Heimat stehen. Bald werden die Bewohner von Seenhain nicht die einzigen Menschen sein, die belagert werden!\n\nHier ist Euer Lohn, auch wenn Ihr uns schlechte Nachrichten bringt. Und es kommt auch noch zu einem schlechten Zeitpunkt, denn wir sind nicht gut dafür gerüstet.", sourceObjectiveStatus = "unverified-source-field" }
quests[245] = { id = 245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr auf acht Beinen", description = "Seid gegrüßt, {class}. Vielleicht habt Ihr die Spinnen gesehen, die die Grenze im Westen überrannt haben? Mit den achtbeinigen Monstern werden wir nicht fertig und der Kommandant hat nicht genug Leute, um sie so weit weg von Dunkelhain einsetzen zu können.\n\nIch bitte Euch wirklich nur sehr ungern darum, aber Ihr seht aus, als könntet Ihr mit ihnen fertig werden. Ich kann Euch keine großen Schätze versprechen, aber ich kann Euch belohnen, wenn Ihr dabei helft, die dreckigen Biester auszurotten.\n\nAch, ein Ratschlag noch: Weicht ihrem Gift aus, wenn Ihr könnt.", sourceObjective = "Erledigt 15 Zwerggiftweberspinnen und meldet Euch dann wieder bei Behüter Dodds im Dämmerwald.", completion = "Ah! Ihr seid zurück. Und Ihr seht gar nicht sonderlich angeschlagen aus, scheint mir. Natürlich ist die Nachtwache dankbar für Eure Arbeit, {name}, und ich hatte Euch ja auch eine Belohnung versprochen. Hier bitte.", sourceObjectiveStatus = "unverified-source-field" }
quests[246] = { id = 246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einschätzung der Gefahr", description = "Wir können keinen der Männer hier entbehren, aber mit diesen Gnollen, von denen Ihr mir berichtet habt, muss etwas passieren.\n\nSpäht das südliche Rotkammgebirge nach Gnollen aus. Bedrängt sie, tötet so viele Ihr könnt und erstattet mir dann Bericht über ihre Anzahl. Gebt mir auch eine Einschätzung der Gefahr, die sie darstellen. Möglicherweise findet Ihr Lager dieser Gnolle entlang der südlichen Straße im Rotkammgebirge.\n\nTut dies für die Armee von Sturmwind, {name}, und Ihr erhaltet eine Belohnung.", sourceObjective = "Tötet 10 Bastarde der Rotkammgnolle und 6 Wilderer der Rotkammgnolle und meldet Euch anschließend wieder bei Stellvertreter Feldon in Seenhain.", completion = "<Deputy Feldon hört sich Euren Bericht an.>\n\nDann lagert dort eine beachtliche Streitmacht Gnolle und nach dem, was Ihr mir erzählt habt, sind sie auch zäh. Es kann nicht leicht für Euch gewesen sein, diese Informationen zu beschaffen.\n\nHier, bitte schön, {name}. Wir danken Euch für Eure Hilfe.\n\nUnd falls Ihr es noch nicht getan habt, sprecht in Seenhain auch mit Marshal Marris und Magistrat Solomon. Unsere Situation wird immer verzweifelter - die beiden werden Euch brauchen können, da bin ich mir sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[247] = { id = 247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd ist abgeschlossen", sourceObjective = "{name}, Ihr habt alle drei Tiere erschlagen, um die es bei der Jagd in Ashenvale geht. Ihr habt mir angemessene Beweise von ihrem Tod gebracht; es gibt keinen Zweifel an Eurer Kraft und Eurer Hartnäckigkeit. Das Blut eines Jägers fließt durch Eure Adern, und Ihr solltet dafür belohnt werden!\n\nBitte, nehmt dieses Schmuckstück als Zeichen unserer Anerkennung ob Eurer mächtigen Taten, die Ihr heute für die Horde in Ashenvale vollbracht habt. Mögen Eure Vorfahren über Euch wachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[248] = { id = 248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Beobachtungen", description = "Seit einer Weile schon beobachte ich den Turm von Ilgalar und ich habe herausgefunden, dass Morganth im Konflikt mit den Orcs von Burg Steinwacht liegt. Den Grund für ihren Streit kenne ich nicht, aber vielleicht könnt Ihr mir ja dabei helfen, diesem Rätsel auf die Spur zu kommen.\n\nNehmt eine weitere Glyphe von Azora und begebt Euch dann auf die Spitze des unversehrten Wachturms neben der Burg Steinwacht.\n\nFindet einen passenden Gegenstand, auf dem Ihr die Glyphe ablegen könnt. Eine Truhe oder ein Krug - irgendein Ort, an dem die Glyphe nicht auffällt - ist für meine Zwecke geeignet.", sourceObjective = "Steigt in den unversehrten Wachturm neben der Burg Steinwacht im Rotkammgebirge hinauf.\n\nFindet einen passenden Behälter für die Glyphe von Azora und legt diese dort ab.", progress = "Dieser Krug war einmal mit übel riechendem Schnaps gefüllt. Jetzt liegt er leer und vergessen auf ein paar Fässern.", completion = "Dies ist ein passendes Gefäß für die Glyphe von Azora, sodass Theocritus in den Geist der Bewohner von Burg Steinwacht eindringen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[249] = { id = 249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morganth", description = "Nach langen Beobachtungen habe ich jetzt Morganths Pläne durchschaut.\n\nEr sucht nach der Sense von Elune... und vielleicht hat er sie bereits gefunden! Wenn dem so ist, dann werden das Rotkammgebirge und das Königreich Sturmwind schon bald seine dunkle Macht zu spüren bekommen.\n\nIch selbst bin leider nicht bereit, mich gegen Morganth zu stellen, doch ich fürchte, er muss genau jetzt aufgehalten werden. Daher müsst Ihr Euch Zutritt zum Turm von Ilgalar verschaffen und Morganth entgegentreten.\n\nBesiegt ihn und bringt mir seinen Schattenanhänger. Wenn Ihr dies vermögt, dann schuldet das Königreich Euch viel.", sourceObjective = "Besiegt Morganth.\n\nBringt seinen Schattenanhänger zu Theocritus am Turm von Azora im Wald von Elwynn.", progress = "Sputet Euch, {name}, ehe meine Befürchtungen sich bewahrheiten und Morganths Macht sich ausweitet!", completion = "Ihr habt Eure Sache gut gemacht, {name}. Die Niederlage des Hexenmeisters Morganth hat Stormwind vor einer großen Gefahr bewahrt.\n\nDemütig biete ich Euch diese Belohnung an. Und ich würde Euch Frieden wünschen, wenn dies friedliche Zeiten wären.\n\nDoch stattdessen wünsche ich Euch Glück für die Aufgaben, die vor Euch liegen, und Sieg in den Kämpfen, die Ihr bestehen müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[250] = { id = 250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dunkle Bedrohung", description = "Den Sternen sei Dank, jemand sorgt sich um den Damm. Erst die Zerstörung des Thandolübergangs, dann die Plünderung von Dun Modr! Ich hege keinerlei Zweifel, dass der Damm das Ziel des nächsten Anschlags der Dunkeleisenzwerge sein wird. Der größte Teil meiner Sicherheitsleute wurde an die Front der Allianz versetzt, einschließlich meines besten Kontrolleurs.\n\nUnd deswegen brauche ich Euch, {name}. Ich habe einige Pioniere der Dunkeleisenzwerge gesehen, die an der östlichen Rampe des Damms herumlungerten. Untersucht den Bereich und bringt einen Hinweis zurück.", sourceObjective = "Untersucht den Bereich um die östliche Dammrampe und bringt Chefingenieur Hinderweir einen Hinweis, der Auskunft darüber geben könnte, was die Dunkeleisenzwerge vorhaben.", completion = "Das verdächtig aussehende Fass enthält ein sonderbar riechendes Pulver.", sourceObjectiveStatus = "unverified-source-field" }
quests[251] = { id = 251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übersetzung von Calvinius' Notiz", description = "Bringt den Zettel, den Ihr mir gabt, zu Sirra Von'Indi. Er ist sehr gelehrt und kennt viele Sprachen und alte Künste - wenn überhaupt jemand diese Nachricht übersetzen kann, dann ist er das.", sourceObjective = "Bringt den Brief an Ello zu Sirra Von'Indi.", progress = "Eine Nachricht von Calvinius, dem Einsiedler, wie? Ich kenne ihn nicht persönlich, aber wenn er draußen am Friedhof lebt, dann weiß ich, dass sein Gehirn verfault sein muss!", completion = "<Sirra beginnt, die Notiz zu übersetzen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[252] = { id = 252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übersetzung für Ello", description = "Oh je! Wenn das, was hier steht, wahr ist, dann hat Calvinius etwas... Unsägliches getan.\n\nBringt die übersetzte Notiz besser schnell zu Ello zurück.\n\nBeeilt Euch, denn ich fürchte, Unheil rollt bereits auf unsere Stadt zu...", sourceObjective = "Bringt Lord Ello Schwarzhaupt den übersetzten Brief.", progress = "Ah, ist die Notiz fertig übersetzt? Bitte, zeigt sie mir...", completion = "<Ello liest den Brief und wird kreidebleich. Dann sieht er Euch an.>\n\nIhr mögt Calvinius vielleicht aus Freundlichkeit geholfen haben. Doch dank Eurer Taten ist unsere Stadt verloren.\n\n<Ello versinkt in Gedanken...>", sourceObjectiveStatus = "unverified-source-field" }
quests[253] = { id = 253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braut des Einbalsamierers", description = "Der Einbalsamierer... diesen Namen kennen wir aus einer Geschichte, die wir unseren Kindern erzählen. Er war ein freundlicher Alchemist, den der Tod seiner Frau Eliza in den Wahnsinn trieb. Er wollte sie wiederbeleben und so wandte er schwarze Magie an und pflanzte sein eigenes Herz in die Brust seiner toten Gattin ein.\n\nDies stellte Eliza wieder her, doch nun war sie verflucht... ein unstillbarer Hunger auf Menschenfleisch hatte sich ihrer bemächtigt und der Einbalsamierer musste sie in ihrem Grab liegen lassen.\n\nSeine Macht ruht in seinem Herzen. Findet das Grab seiner Frau, holt sein Herz und bringt es mir, solange es noch schlägt. Wenn Ihr dies tut, wird seine Macht gebrochen sein.", sourceObjective = "Findet Elizas Grab. Beschafft das Herz des Einbalsamierers, das sie in sich trägt, und kehrt zu Ello Schwarzhaupt zurück.", progress = "Habt Ihr Elizas Grab schon gefunden? Habt Ihr das Herz des Einbalsamierers?", completion = "Ihr habt es geschafft! Dank der ihm innewohnenden Magie ist das Herz gegen das Böse des Einbalsamierers gefeit und stellt somit einen mächtigen Schutz für die Stadt Dunkelhain dar.\n\nIhr habt unserem Volk einen großen Dienst erwiesen, {name}. Euer Name wird für alle Zeit in unseren Annalen verzeichnet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[254] = { id = 254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Graben in der Erde", sourceObjective = "Ihr schaufelt die nicht allzu feste Erde über dem Grab weg... und findet die Überreste eines Sarges.\n\nAus dem Sarg ist das Vibrieren und Kratzen von zu Klauen verformten Fingern zu spüren und das Knirschen verfaulter Zähne zu hören...\n\nWerdet Ihr den Sarg öffnen und das Herz des Einbalsamierers bergen?", sourceObjectiveStatus = "unverified-source-field" }
quests[255] = { id = 255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Söldner", description = "Zwei Monate! Zwei Monate, nur um dann aus Eisenschmiede zu hören zu bekommen, dass eine Handvoll Soldaten zu unserer Verteidigung abgestellt wird, und zwei weitere Monate, bis sie ankommen! Schlimm genug, dass unsere Stadt ohne Schutz ist, aber die Ausgrabung und der Damm - der Damm! - sind ebenfalls allen Angriffen schutzlos ausgesetzt.\n\nIch habe also keine Wahl, scheint mir. Ich brauche gedungene Kämpfer.\n\nWie steht es mit Euch? Ihr seht mir tüchtig aus, {class}. Eine Gruppe Oger hat im Nordosten des Sees ihr Lager aufgeschlagen. Vielleicht seid Ihr ja die Unterstützung, die uns hilft, die Bedrohung für unsere Stadt zu beseitigen?", sourceObjective = "Magistrat Stumpfnase aus Thelsamar hat Euch angeheuert, um 4 Oger der Mo'grosh, 4 Schläger der Mo'grosh und 4 Vollstrecker der Mo'grosh zu töten.", completion = "Ah, das sind ausgezeichnete Neuigkeiten! Ich selbst und die Bewohner von Thelsamar wissen Eure Mühen außerordentlich zu schätzen. Und was noch besser ist: Wenn wir in der Lage sind, das Ogerproblem zu lösen, dann können wir unsere Aufmerksamkeit endlich auf diese vom Licht verlassenen Troggs richten.", sourceObjectiveStatus = "unverified-source-field" }
quests[256] = { id = 256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Chok'sul", description = "Auf Befehl des Magistrats von Thelsamar:\n\nDer Tod von Chok'sul, dem Oger und mutmaßlichen Anführer und Kopf hinter den Angriffen auf die Stadt Thelsamar, den Steinwerkdamm und die Ausgrabungsstätte, wird unter allen Umständen gewünscht. Es darf zu jedem Mittel gegriffen werden, das notwendig ist.\n\nEine Barentschädigung kommt zur Auszahlung, wenn der Magistrat einen Beweis für Chok'suls Tod erhält.\n\nZuletzt wurde Chok'sul am Ogerlager im nordöstlichen Teil von Loch Modan gesehen.", sourceObjective = "Tötet Chok'sul und bringt Magistrat Stumpfnase in Thelsamar seinen Kopf.", progress = "Ja? Kann ich Euch behilflich sein?", completion = "Pfui! Was ist das denn? Und warum bringt Ihr...\n\nVerdammt! Kann es sein? Da verbrenn mich doch das Licht; ist das der Kopf dieses verdammten Ogers? Da habt Ihr vielleicht einen Fang gemacht! Hier, nehmt diese Belohnung, zusammen mit meinem Dank und dem der Bewohner von Thelsamar.", sourceObjectiveStatus = "unverified-source-field" }
quests[257] = { id = 257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Prahlen eines Jägers", description = "Ihr glaubt wohl, Ihr könnt Euch mit Daryl dem Kühnen messen, hm? Das will ich auch nicht hoffen! Aber Ihr dürft es natürlich gern versuchen, wenn Ihr denn meint... Hier habt Ihr eine Herausforderung, der Ihr bestimmt nicht gewachsen seid. Also nehmt's nicht zu schwer, wenn Ihr damit nicht fertig werdet.\n\nEin Schwarm Bussarde nistet hier am Loch Modan. Warum versucht Ihr nicht, einige von denen zu erledigen? Ich sag Euch was. Wenn Ihr meine Herausforderung annehmt und es Euch in 15 Minuten gelingt, dann gebe ich Euch meinen Bogen oder mein Gewehr.\n\n<Er mustert Euch abschätzig.>\n\nScheint ja nicht, als ob Ihr viel zu verlieren hättet.", sourceObjective = "Tötet 6 Bergbussarde und kehrt innerhalb von 15 Minuten zu Daryl dem Jüngling in die Jagdhütte der Weltenwanderer zurück.", progress = "Kein Glück gehabt? Macht Euch nix draus, Pupserer...\n\nNicht jeder kann so gut sein wie ich.", completion = "Wie jetzt, Ihr hattet Erfolg?\n\nGlaubt mir, Eisenberndama, das sollte Euch nicht zu Kopf steigen. Denn jeder milchgesichtige Junge mit einem Bogen hätte so... kleine Exemplare töten können. Und ich hoffe, es hat Euch nicht zu viel Spaß gemacht, die Bussarde zu erschießen. Wir wollen doch nicht, dass sie aussterben! \n\nAch so, ähhhm... Es soll keiner sagen, dass Daryl der Kühne sein Wort nicht hält.", sourceObjectiveStatus = "unverified-source-field" }
quests[258] = { id = 258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herausforderung eines Jägers", description = "{name}ath, stimmt's? Ich seh schon, Ihr platzt fast vor Stolz, dass Ihr den ersten Test bestanden habt. Aber ich hab Euch ja auch schon gesagt, dass das keine große Tat war.\n\nIhr solltet Euch mal an der Eberjagd versuchen. Glaubt mir, das sind andere Eber als im Eisklammtal, also solltet Ihr Euch vorsehen. Diesmal gebe ich Euch nur 12 Minuten.\n\nSeid nicht zu traurig, wenn Ihr versagt. Ich würde Euch das Hemd geben, das ich am Leibe trage, wenn Ihr es schaffen würdet!\n\nHabe ich Euch schon mal erzählt, wie ich an meine berühmte Narbe gekommen bin? Nein? Also, das war vor zwei Jahren...", sourceObjective = "Tötet 5 alte Bergeber und kehrt innerhalb von 12 Minuten zu Daryl dem Jüngling in die Jagdhütte der Weltenwanderer zurück.", progress = "Es ist ganz normal, dass man sich selbst bemitleidet, wenn man sich vor jemandem blamiert, der so viel jünger ist als man selbst. Macht Euch nichts draus, Rinovaah...\n\nWie? Hab ich mir Euren Namen falsch gemerkt?", completion = "Ihr seht etwas mitgenommen aus. Die Eber haben Euch wohl ein paar Schwierigkeiten gemacht, wie? Keine Sorge, ich verrate es auch keinem, dass Ihr versagt habt; ich kann mir vorstellen, wie schwer es für Euch sein muss, auch ohne dass sich die Leute über Euch das Maul zerreißen.\n\nOh! Ihr habt es geschafft? Ihr habt die Eber getötet? Ich... also... na ja, das überrascht mich nicht! Jedes Kind hätte das - Wette?\n\nWas für eine Wette?", sourceObjectiveStatus = "unverified-source-field" }
quests[261] = { id = 261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Scharlachroten Pfad", description = "Ich werde offen mit Euch sein. Wir sind im Krieg mit der Geißel. Sie ist ein Übel, das unser Volk verdirbt und unser Land infiziert. Sie muss aufgehalten werden, bevor sie uns übermannt und unsere Welt mit Schatten überzieht. Wir vom Scharlachroten Kreuzzug haben geschworen, die Geißel mit Leib und Seele zu bekämpfen.\n\nWenn Ihr auf unserer Seite steht, dann nehmt Euren Mut zusammen und beweist Eure Zugehörigkeit - zerstört die untoten Verheerer von Desolace im südlich gelegenen Tal der Knochen.\n\nTut dies, und der Kreuzzug wird Euch mit offenen Armen aufnehmen.", sourceObjective = "Vernichtet 30 untote Verheerer und kehrt dann zu Bruder Anton auf die Nijelspitze zurück.", progress = "Die Geißel gewinnt mit jedem Tag an Stärke. Wenn Ihr ihren Vormarsch wirklich aufhalten wollt, dann beweist es mir.", completion = "Ihr habt Eure Entschlossenheit bewiesen, und der scharlachrote Kreuzzug lobt Euch dafür.\n\nWenn Ihr nicht vor rechtschaffenem Gemetzel zurückschreckt, dann ist Euer Pfad vielleicht der unsrige...", sourceObjectiveStatus = "unverified-source-field" }
quests[262] = { id = 262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schattengestalt", description = "Ich muss wissen, wen ich in der Nacht, in der meine Familie ermordet wurde, in den Schatten habe herumschleichen sehen.\n\nBitte, {name}, Ihr habt euren Einfallsreichtum bereits bewiesen. Bitte findet diese schattenhafte Gestalt. Ich muss wissen, was sie für Geheimnisse kennt!\n\nIch habe keine Hinweise, die Ihr nicht bereits hättet, aber hier - nehmt das Buch, das Ihr auf meinem Hof gefunden habt. Vielleicht können einige Stadtbewohner das Buch mit seinem Besitzer in Verbindung bringen.", sourceObjective = "Nehmt das Buch, das Ihr auf Svens Hof gefunden habt, und zeigt es den Einwohnern von Dunkelhain.", progress = "Wenn Ihr einen Gegenstand von der Schattengestalt habt, nach der Ihr sucht, dann zeigt ihn mir. Ich kann vielleicht etwas über seinen Besitzer erspüren.", completion = "Hmm... Jemand hatte dieses Buch erst vor kurzem in der Hand, jemand, der von Rache getrieben wird. Allerdings sind die daran verbliebenen Eindrücke, oder zumindest die Eindrücke von seinem ursprünglichen Besitzer, sehr schwach.\n\nIch kann jedoch sagen, dass der ursprüngliche Besitzer dieses Buches kein Einheimischer von Dunkelhain ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[263] = { id = 263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Länder des Königs", description = "Die Gebirgsjäger sagen mir, dass Ihr recht tapfer und fähig seid, {name}. <Ein/Eine:r> {race} wie Ihr wird hier draußen gebraucht. Wir bekommen das Troggproblem einfach nicht unter Kontrolle. Die Reserve wurde zur Front gerufen, und wir sind hier auf uns allein gestellt. Aber jetzt seid ja Ihr hier, <ein erfahrener/eine erfahrene:c> {class}, also wollen wir doch mal sehen, was Ihr ausrichten könnt.\n\nZieht los und tötet 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs. Wir werden sehen, ob Ihr Eurem Ruf gerecht werdet, <Troggtöter/Troggtöterin>.", sourceObjective = "Gebirgsjäger Wallbang im südlichen Wachturm möchte, dass Ihr 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs tötet.", progress = "Schon wieder zurück? Nur für den Fall, dass ich mich nicht klar ausgedrückt habe: Ihr müsst 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs töten, {name}. Und jetzt schnappt sie Euch, Trogg-Töter!", completion = "Ich wusste schon, als ich Euch zum ersten Mal erblickte, {name}, dass Ihr Ironforge stolz machen würdet. Ihr habt König Magni gut gedient. Jetzt, wo Ihr Euch als so zuverlässige Hilfe für das Königreich erwiesen habt, solltet Ihr vielleicht mit dem Captain reden, um zu sehen, ob er Euch mehr Details anvertraut.\n\nIch ziehe den Hut vor Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
